    assert!(
        stdout.contains(&format!(
            "\"kind\":\"artifactFile\",\"role\":\"dependency-interface\",\"artifactKind\":\"interface\",\"path\":\"{}\",\"uri\":\"file://",
            interface_artifact_path.display()
        )),
        "{stdout}"
    );

    let provider = muga::compile_typed_path(Path::new("samples/packages/app/enum_demo/main.muga"))
        .expect("typed package compilation should pass");
    let cache_artifact_root = temp_package_root("cli-json-check-cache-context-root");
    write_interface_artifacts(
        &cache_artifact_root,
        &provider.package_interfaces(),
        &provider.symbols,
        &["util::states"],
    );
    let cache_entry = write_package_file(
        &root,
        "app/cli_json_cache_context/main.muga",
        r#"
package app::cli_json_cache_context

import util::states

fn main(): Int {
  states::value_or_zero(states::ready(9))
}
"#,
    );
    let cache_output = muga_command()
        .arg("check")
        .arg("--format=json")
        .arg("--artifact-root")
        .arg(&cache_artifact_root)
        .arg(&cache_entry)
        .output()
        .expect("muga command should run");
