#[test]
fn project_manifest_metadata_reports_roots_and_dependency_sources() {
    let workspace = temp_package_root("project-manifest-metadata");
    let app_root = workspace.join("app");
    let shared_root = workspace.join("shared");
    write_package_file(
        &shared_root,
        "muga.toml",
        r#"
[package]
name = "shared"
source = "src"
resources = "resources"
"#,
    );
    write_package_file(
        &shared_root,
        "src/api/main.muga",
        r#"
pub fn value(): Int {
  1
}
"#,
    );
    write_package_file(
        &app_root,
        "muga.toml",
        r#"
[package]
name = "app"
source = "src"
resources = "resources"

[dependencies]
shared = { path = "../shared" }
"#,
    );
    let entry = write_package_file(
        &app_root,
        "src/main/main.muga",
        r#"
import shared::api as api

fn main(): Int {
  api::value()
}
"#,
    );

    let metadata = muga::package::project_manifest_metadata_from_entry(&entry)
        .expect("manifest metadata should load")
        .expect("manifest project should report metadata");

    assert_eq!(metadata.manifest_path, app_root.join("muga.toml"));
    assert_eq!(metadata.root, app_root);
    assert_eq!(metadata.source_root, metadata.root.join("src"));
    assert_eq!(
        metadata.resource_root,
        Some(metadata.root.join("resources"))
    );
    assert_eq!(metadata.package_path, "app");
    assert_eq!(metadata.direct_dependencies, vec!["shared".to_string()]);
    assert_eq!(metadata.dependencies.len(), 1);
    let dependency = &metadata.dependencies[0];
    assert_eq!(dependency.package_path, "shared");
    assert_eq!(dependency.root, app_root.join("../shared"));
    assert_eq!(dependency.source_root, dependency.root.join("src"));
    assert_eq!(
        dependency.resource_root,
        Some(dependency.root.join("resources"))
    );
    assert_eq!(
        dependency.source_kind,
        muga::package::PackageLockfileDependencySourceKind::Path
    );
    assert_eq!(dependency.source, "../shared");
    assert_eq!(dependency.hash, None);
}

#[test]
fn project_manifest_rejects_source_roots_outside_package_root() {
    let cases = vec![
        ("empty", "", "must name a source directory"),
        (
            "absolute",
            "/tmp/muga-external-src",
            "relative slash-separated path",
        ),
        (
            "drive",
            "C:/tmp/muga-external-src",
            "relative slash-separated path",
        ),
        ("parent", "../src", "must stay inside the package root"),
        (
            "empty segment",
            "src//main",
            "must stay inside the package root",
        ),
        ("metadata", ".muga/src", "tool metadata"),
    ];

    for (name, source, expected_message) in cases {
        let root = temp_package_root(&format!("project-manifest-unsafe-source-{name}"));
        write_package_file(
            &root,
            "muga.toml",
            &format!(
                r#"
[package]
name = "unsafe_source"
source = "{source}"
"#
            ),
        );
        let entry = write_package_file(
            &root,
            "src/main/main.muga",
            r#"
fn main(): String {
  "ok"
}
"#,
        );

        let diagnostics = muga::package::project_manifest_metadata_from_entry(&entry)
            .expect_err("unsafe manifest source should be rejected");
        assert!(
            diagnostics.iter().any(|diagnostic| {
                diagnostic.code == "PK014"
                    && diagnostic.message.contains("manifest field `source`")
                    && diagnostic.message.contains(expected_message)
            }),
            "{name}: {diagnostics:#?}"
        );
    }
}

#[test]
fn project_manifest_rejects_dependency_source_roots_outside_package_root() {
    let workspace = temp_package_root("project-manifest-dependency-unsafe-source");
    let app_root = workspace.join("app");
    let shared_root = workspace.join("shared");
    write_package_file(
        &shared_root,
        "muga.toml",
        r#"
[package]
name = "shared"
source = "../external-src"
"#,
    );
    write_package_file(
        &shared_root,
        "../external-src/api/main.muga",
        r#"
pub fn value(): Int {
  1
}
"#,
    );
    write_package_file(
        &app_root,
        "muga.toml",
        r#"
[package]
name = "app"
source = "src"

[dependencies]
shared = { path = "../shared" }
"#,
    );
    let entry = write_package_file(
        &app_root,
        "src/main/main.muga",
        r#"
import shared::api as api

fn main(): Int {
  api::value()
}
"#,
    );

    let diagnostics = muga::package::project_manifest_metadata_from_entry(&entry)
        .expect_err("unsafe dependency source should be rejected");
    assert!(
        diagnostics.iter().any(|diagnostic| {
            diagnostic.code == "PK014"
                && diagnostic.message.contains("manifest field `source`")
                && diagnostic
                    .message
                    .contains("must stay inside the package root")
        }),
        "{diagnostics:#?}"
    );
}

