#[test]
fn muga_test_runs_unit_and_result_tests() {
    let outcome = muga::test_source(
        r#"
@test
fn unit_test(): Unit {
  ()
}

@test
fn result_test(): Result[Unit, String] {
  Result::Ok(())
}
"#,
    )
    .expect("test source should run");

    assert_eq!(outcome.passed_count(), 2);
    assert_eq!(outcome.failed_count(), 0);
    assert_eq!(outcome.tests[0].name, "unit_test");
    assert_eq!(outcome.tests[0].status, muga::TestStatus::Passed);
    assert_eq!(outcome.tests[1].name, "result_test");
    assert_eq!(outcome.tests[1].status, muga::TestStatus::Passed);
}

