#[test]
fn muga_test_rejects_invalid_test_function_shape() {
    let diagnostics = muga::test_source(
        r#"
@test
fn has_param(value: Int): Unit {
  ()
}

@test
fn returns_int(): Int {
  1
}
"#,
    )
    .expect_err("invalid test functions should fail before running");

    assert_eq!(diagnostics.len(), 2);
    assert!(
        diagnostics
            .iter()
            .all(|diagnostic| diagnostic.code == "T024")
    );
    assert!(
        diagnostics
            .iter()
            .any(|diagnostic| diagnostic.message.contains("must not have parameters")),
        "{diagnostics:#?}"
    );
    assert!(
        diagnostics
            .iter()
            .any(|diagnostic| diagnostic.message.contains("must return Unit")),
        "{diagnostics:#?}"
    );
}

#[test]
fn muga_test_rejects_unknown_and_misplaced_attributes() {
    let unknown = muga::test_source(
        r#"
@skip
fn skipped(): Unit {
  ()
}
"#,
    )
    .expect_err("unknown attributes should be rejected");

    assert_eq!(unknown[0].code, "P014");
    assert!(
        unknown[0].message.contains("unknown attribute `@skip`"),
        "{unknown:#?}"
    );

    let misplaced = muga::check_source(
        r#"
@test
value = 1
"#,
    )
    .expect_err("attributes should be allowed only on functions");

    assert_eq!(misplaced[0].code, "P014");
    assert!(
        misplaced[0]
            .message
            .contains("allowed only on function declarations"),
        "{misplaced:#?}"
    );

    let misplaced_json = muga::check_source(
        r#"
@json(rename: "wire")
fn main(): Unit {
  ()
}
"#,
    )
    .expect_err("json attributes should be allowed only on JSON schema members");

    assert_eq!(misplaced_json[0].code, "P014");
    assert!(
        misplaced_json[0]
            .message
            .contains("allowed only on record declarations, record fields, and enum variants"),
        "{misplaced_json:#?}"
    );

    let misplaced_json_flag = muga::check_source(
        r#"
record Settings {
  @json(deny_unknown_fields)
  name: String
}
"#,
    )
    .expect_err("json deny_unknown_fields should be allowed only on records");

    assert_eq!(misplaced_json_flag[0].code, "P014");
    assert!(
        misplaced_json_flag[0]
            .message
            .contains("support only `@json(rename: \"...\", alias: \"...\")`"),
        "{misplaced_json_flag:#?}"
    );

    let misplaced_cli_field_metadata = muga::check_source(
        r#"
@cli(name: "settings")
record Settings {
  name: String
}
"#,
    )
    .expect_err("field-level CLI metadata should not be accepted on records");

    assert_eq!(misplaced_cli_field_metadata[0].code, "P014");
    assert!(
        misplaced_cli_field_metadata[0]
            .message
            .contains("record declarations support only `@cli(about: \"...\")`"),
        "{misplaced_cli_field_metadata:#?}"
    );

    let misplaced_cli_command_metadata = muga::check_source(
        r#"
record Settings {
  @cli(about: "Configure settings")
  name: String
}
"#,
    )
    .expect_err("record-level CLI metadata should not be accepted on fields");

    assert_eq!(misplaced_cli_command_metadata[0].code, "P014");
    assert!(
        misplaced_cli_command_metadata[0]
            .message
            .contains("record fields support only `@cli(name:"),
        "{misplaced_cli_command_metadata:#?}"
    );

    let misplaced_cli_enum_variant_metadata = muga::check_source(
        r#"
@cli(name: "build")
enum Command {
  Build
}
"#,
    )
    .expect_err("variant-level CLI metadata should not be accepted on enum declarations");

    assert_eq!(misplaced_cli_enum_variant_metadata[0].code, "P014");
    assert!(
        misplaced_cli_enum_variant_metadata[0]
            .message
            .contains("enum declarations support only `@cli(about: \"...\")`"),
        "{misplaced_cli_enum_variant_metadata:#?}"
    );

    let misplaced_cli_enum_about_metadata = muga::check_source(
        r#"
enum Command {
  @cli(about: "Build package artifacts")
  Build
}
"#,
    )
    .expect_err("variant CLI metadata without a name should be rejected");

    assert!(
        misplaced_cli_enum_about_metadata.iter().any(|diagnostic| {
            diagnostic.code == "T006"
                && diagnostic
                    .message
                    .contains("requires `@cli(name: \"...\")`")
        }),
        "{misplaced_cli_enum_about_metadata:#?}"
    );

    let duplicate_cli_command_metadata = muga::check_source(
        r#"
enum Command {
  @cli(name: "build", alias: "b")
  Build
  @cli(name: "b")
  Backup
}
"#,
    )
    .expect_err("duplicate CLI command names should be rejected");

    assert!(
        duplicate_cli_command_metadata.iter().any(|diagnostic| {
            diagnostic.code == "E002"
                && diagnostic
                    .message
                    .contains("duplicate CLI command name `b`")
        }),
        "{duplicate_cli_command_metadata:#?}"
    );
}

