#[test]
fn muga_test_assertion_helpers_report_scalar_failures() {
    let root = temp_package_root("muga-test-assertions");
    let entry = write_package_file(
        &root,
        "app/tests/main.muga",
        r#"
package app::tests

import std::test

@test
fn scalar_assertions_pass(): Result[Unit, String] {
  ok = try test::assert_true(true)
  int_ok = try test::assert_eq_int(42, 42)
  bool_ok = try test::assert_eq_bool(false, false)
  test::assert_eq_string("muga", "muga")
}

@test
fn scalar_assertion_fails(): Result[Unit, String] {
  test::assert_eq_string("expected", "actual")
}
"#,
    );

    let outcome = muga::test_path(&entry).expect("package assertion tests should run");

    assert_eq!(outcome.passed_count(), 1);
    assert_eq!(outcome.failed_count(), 1);
    assert_eq!(outcome.tests[0].status, muga::TestStatus::Passed);
    assert_eq!(outcome.tests[1].status, muga::TestStatus::Failed);
    assert_eq!(
        outcome.tests[1].message.as_deref(),
        Some("assert_eq_string failed: expected `expected` but got `actual`")
    );
    assert_eq!(outcome.tests[1].diagnostics.len(), 1);
    let diagnostic = &outcome.tests[1].diagnostics[0];
    assert_eq!(diagnostic.code, "R021");
    assert!(
        diagnostic.message.contains("test assertion failed"),
        "{diagnostic:#?}"
    );
    assert_eq!(diagnostic.span.start.line, 15, "{diagnostic:#?}");
    assert!(
        diagnostic.related.iter().any(|note| {
            note.message
                .contains("while running `app::tests::scalar_assertion_fails`")
        }),
        "{diagnostic:#?}"
    );
}

