#[test]
fn cli_test_json_reports_success_contract_on_stdout() {
    let root = temp_package_root("cli-test-json-success");
    let entry = write_package_file(
        &root,
        "tests.muga",
        r#"
@test
fn passes(): Unit {
  printed = println("hello")
  ()
}
"#,
    );
    let output = muga_command()
        .arg("test")
        .arg("--format=json")
        .arg(&entry)
        .output()
        .expect("muga command should run");
    let stdout = String::from_utf8_lossy(&output.stdout);

    assert!(output.status.success(), "{output:#?}");
    assert_eq!(String::from_utf8_lossy(&output.stderr), "");
    assert!(
        stdout.starts_with("{\"schemaVersion\":1,\"command\":\"test\",\"entry\":{\"path\":\""),
        "{stdout}"
    );
    assert!(stdout.contains("\"status\":\"ok\""), "{stdout}");
    assert!(stdout.contains("\"diagnostics\":[]"), "{stdout}");
    assert!(stdout.contains("\"tests\":["), "{stdout}");
    assert!(
        stdout.contains(
            "\"name\":\"passes\",\"status\":\"passed\",\"message\":null,\"diagnostics\":[],\"stdout\":\"hello\\n\""
        ),
        "{stdout}"
    );
    assert!(
        stdout.contains("\"summary\":{\"passed\":1,\"failed\":0}"),
        "{stdout}"
    );
    assert!(!stdout.contains("test passes ... ok"), "{stdout}");
}

