#[test]
fn muga_fmt_formats_source_deterministically() {
    let source = r#"
fn main():Int{mut total=0
while total<3{total=total+1}
if total==3{total}else{0}
}
"#;
    let expected = r#"fn main(): Int {
  mut total = 0
  while total < 3 {
    total = total + 1
  }
  if total == 3 {
    total
  } else {
    0
  }
}
"#;

    let formatted = muga::format_source(source).expect("source should format");

    assert_eq!(formatted, expected);
    assert_eq!(
        muga::format_source(&formatted).expect("formatted source should reformat"),
        formatted
    );
    muga::check_source(&formatted).expect("formatted source should check");
}

#[test]
fn muga_fmt_outputs_parseable_idempotent_source_for_repository_samples() {
    let root = temp_package_root("fmt-repository-samples");
    let samples_root = root.join("samples");
    let conformance_root = root.join("conformance/current");
    copy_repository_fixture_tree(Path::new("samples"), &samples_root);
    copy_repository_fixture_tree(Path::new("conformance/current"), &conformance_root);

    let paths = recursive_muga_paths(&samples_root)
        .into_iter()
        .chain(recursive_muga_paths(&conformance_root))
        .collect::<Vec<_>>();
    assert!(!paths.is_empty(), "repository should contain Muga samples");

    for path in paths {
        muga::format_path(&path).unwrap_or_else(|diagnostics| {
            panic!("format failed for {}: {diagnostics:#?}", path.display())
        });
        let second = muga::format_path(&path).unwrap_or_else(|diagnostics| {
            panic!("reformat failed for {}: {diagnostics:#?}", path.display())
        });
        assert!(
            !second.changed,
            "formatted output should be idempotent for {}",
            path.display()
        );
    }
}

#[test]
fn muga_fmt_formats_using_statement() {
    let source = r#"
package app::using_fmt
import std::fs
import std::io
import std::path
fn main():Result[Unit,io::IOError]{file_path=path::from_string("out.txt")
using file=try fs::create_text(file_path){wrote=try fs::write_text_to(file,"ok")
flushed=try fs::flush(file)}
Result::Ok(())}
"#;
    let expected = r#"package app::using_fmt

import std::fs
import std::io
import std::path

fn main(): Result[Unit, io::IOError] {
  file_path = path::from_string("out.txt")
  using file = try fs::create_text(file_path) {
    wrote = try fs::write_text_to(file, "ok")
    flushed = try fs::flush(file)
  }
  Result::Ok(())
}
"#;

    assert_eq!(
        muga::format_source(source).expect("using source should format"),
        expected
    );
}

