#[test]
fn muga_fmt_preserves_line_comments() {
    let source = r#"
// file header
fn main():Int{ // entry point
value=1 // seed
// final value
value
} // done
"#;
    let expected = r#"// file header
fn main(): Int {
  // entry point
  value = 1 // seed
  // final value
  value
} // done
"#;

    let formatted = muga::format_source(source).expect("comments should be preserved");

    assert_eq!(formatted, expected);
    assert_eq!(
        muga::format_source(&formatted).expect("formatted source should reformat"),
        formatted
    );
    muga::check_source(&formatted).expect("formatted source should check");

    assert_eq!(
        muga::format_source("fn main():Int{1} // done\n")
            .expect("closing-brace trailing comments should be preserved"),
        "fn main(): Int {\n  1\n} // done\n"
    );
}

