#[test]
fn builtin_eprint_eprintln_capture_stderr_and_return_argument() {
    let result = muga::run_source(
        r#"
fn main(): Int {
  left = eprint("warn: ")
  right = eprintln(41)
  right + 1
}
"#,
    )
    .expect("eprint/eprintln program should run");
    let value = result.main_result.expect("main result should exist");
    assert_eq!(value.to_string(), "42");
    assert_eq!(result.output_text, "");
    assert_eq!(result.stderr_text, "warn: 41\n");
}

#[test]
fn builtin_eprintln_rejects_non_scalar_argument() {
    let diagnostics = muga::check_source(
        r#"
fn main(): Unit {
  values: List[Int] = []
  printed = eprintln(values)
  ()
}
"#,
    )
    .expect_err("eprintln should reject non-scalar values");
    assert!(
        diagnostics.iter().any(|diagnostic| {
            diagnostic.code == "T006"
                && diagnostic
                    .message
                    .contains("`eprintln` accepts only Int, Bool, or String")
        }),
        "{diagnostics:#?}"
    );
}

