#[test]
fn package_std_config_sample_runs_against_emitted_artifacts() {
    let entry = Path::new("samples/packages/app/std_config/main.muga");
    let artifact_root = temp_package_root("package-std-config-artifacts");
    let written =
        muga::write_package_artifacts(entry, &artifact_root).expect("artifacts should emit");

    for expected in ["app__std_config.mgi", "std__config.mgb", "std__path.mgb"] {
        assert!(
            written
                .iter()
                .any(|path| path.file_name().is_some_and(|name| name == expected)),
            "{written:#?}"
        );
    }

    let result = muga::run_path_against_artifact_root(entry, &artifact_root)
        .expect("artifact-backed std::config sample should run");
    let value = result.main_result.expect("main result should exist");
    assert_eq!(
        value.to_string(),
        "Result::Ok(Ada|api|9090|2|prod || ops|localhost|8080|1|dev)"
    );
    assert_eq!(result.output_text, "");

    let implementation = std::fs::read_to_string(artifact_root.join("app__std_config.mgb"))
        .expect("implementation artifact should exist");
    assert!(
        implementation.contains("LoadJsonConfig"),
        "{implementation}"
    );
    assert!(
        implementation.contains("LoadJsonConfigRequired"),
        "{implementation}"
    );
}

