#[test]
fn manifest_resource_export_source_free_bundle_runs_without_sources() {
    let entry = Path::new("samples/projects/resource_export/src/main/main.muga");
    let root = temp_package_root("manifest-resource-export-source-free");
    let bundle = root.join("bundle");
    let output = root.join("exported.bin");

    let emit = muga_command()
        .arg("emit-app-bundle")
        .arg("--source-free")
        .arg("--output-dir")
        .arg(&bundle)
        .arg("--program")
        .arg("resource-export")
        .arg(entry)
        .output()
        .expect("muga emit-app-bundle should run");
    assert!(emit.status.success(), "{emit:#?}");
    assert!(!bundle.join("src").exists());
    assert!(bundle.join("resources/static/payload.bin").is_file());
    assert!(
        bundle
            .join(".muga/build/resource_export__main.mgb")
            .is_file()
    );

    let run = muga_command()
        .arg("run-app-bundle")
        .arg(&bundle)
        .arg("--")
        .arg(&output)
        .output()
        .expect("muga run-app-bundle should run");
    let stdout = String::from_utf8_lossy(&run.stdout);
    let stderr = String::from_utf8_lossy(&run.stderr);

    assert!(run.status.success(), "{run:#?}");
    assert!(
        stdout.contains(
            "Result::Ok(14|file|true|e54f8e906eaac9d311ba74b926b071faee0dc5a0036dd5a5e3c2b23b55f39728)"
        ),
        "{stdout}"
    );
    assert_eq!(stderr, "");
    assert!(
        !output.exists(),
        "source-free resource export should clean up its output"
    );
}

#[test]
fn manifest_report_project_sample_json_built_run_writes_report() {
    let workspace = temp_package_root("manifest-report-project-built-workflow");
    let app_root = workspace.join("report_app");
    let shared_root = workspace.join("report_shared");

    write_package_file(
        &app_root,
        "muga.toml",
        &fs::read_to_string("samples/projects/report_app/muga.toml").unwrap(),
    );
    let entry = write_package_file(
        &app_root,
        "src/main/main.muga",
        &fs::read_to_string("samples/projects/report_app/src/main/main.muga").unwrap(),
    );
    write_package_file(
        &shared_root,
        "muga.toml",
        &fs::read_to_string("samples/projects/report_shared/muga.toml").unwrap(),
    );
    write_package_file(
        &shared_root,
        "src/reports/main.muga",
        &fs::read_to_string("samples/projects/report_shared/src/reports/main.muga").unwrap(),
    );
    let input = write_package_file(&app_root, "data/daily.txt", "ready\n");
    let output = workspace.join("out/summary.txt");
    let input_arg = display_path(&input);
    let output_arg = display_path(&output);

    let built = muga_command()
        .arg("build")
        .arg(&entry)
        .output()
        .expect("muga command should run");
    assert!(built.status.success(), "{built:#?}");
    assert_eq!(String::from_utf8_lossy(&built.stderr), "");

    let run = muga_command()
        .arg("run")
        .arg("--built")
        .arg("--format=json")
        .arg(&entry)
        .arg("--")
        .arg(&input)
        .arg(&output)
        .output()
        .expect("muga command should run");
    let stdout = String::from_utf8_lossy(&run.stdout);
    let escaped_output_arg = output_arg.replace('\\', "\\\\").replace('"', "\\\"");

    assert!(run.status.success(), "{run:#?}");
    assert_eq!(String::from_utf8_lossy(&run.stderr), "");
    assert!(stdout.contains("\"command\":\"run\""), "{stdout}");
    assert!(stdout.contains("\"status\":\"ok\""), "{stdout}");
    assert!(stdout.contains("\"stdout\":\"daily:ready\\n\""), "{stdout}");
    assert!(
        stdout.contains(&format!(
            "\"stderr\":\"wrote report {escaped_output_arg}\\n\""
        )),
        "{stdout}"
    );
    assert!(
        stdout.contains("\"mainResult\":\"Result::Ok(daily:ready|read_text|2)\""),
        "{stdout}"
    );
    assert_eq!(
        fs::read_to_string(output).expect("built run summary file should be written"),
        format!("summary: daily:ready\nsource: {input_arg}\n")
    );
}

