#[test]
fn manifest_cli_tool_project_sample_reports_generated_usage() {
    let entry = Path::new("samples/projects/cli_tool/src/main/main.muga");
    let args = vec!["--help".to_string()];

    let result = muga::run_path_with_args(entry, &args).expect("CLI tool sample should run");
    let value = result.main_result.expect("main result should exist");

    for required in [
        "Usage: cli-tool [global-options] <command> [args]",
        "Run a typed strict CLI tool",
        "Commands:\n  run  aliases: r  Run the main action",
        "inspect  aliases: i  Inspect one target",
        "Global Options:",
        "-p, --profile <String>  Execution profile",
        "-h, --help  Show this help",
    ] {
        assert!(
            result.output_text.contains(required),
            "CLI tool sample usage missing `{required}`:\n{}",
            result.output_text
        );
    }
    assert!(
        value
            .to_string()
            .starts_with("Result::Ok(Usage: cli-tool [global-options] <command> [args]"),
        "{value}"
    );

    let run_help_args = vec!["run".to_string(), "--help".to_string()];
    let run_help =
        muga::run_path_with_args(entry, &run_help_args).expect("CLI tool sample should run");
    let run_help_value = run_help.main_result.expect("main result should exist");

    for required in [
        "Usage: cli-tool run [options] <target>",
        "Run the main action",
        "Arguments:\n  <target>  required; non-empty; Target resource name",
        "-c, --count <Int>  required; range: 1..10; Number of items to process",
        "-a, --action <Action>  required; values: Audit, Apply; Command action",
        "-d, --dry-run[=<Bool>]  Preview changes without applying them",
        "-T, --tag <String>  repeatable; aliases: --tags; Tag filter",
        "-o, --owner <String>  Optional owner",
        "-h, --help  Show this help",
    ] {
        assert!(
            run_help.output_text.contains(required),
            "CLI tool sample run usage missing `{required}`:\n{}",
            run_help.output_text
        );
    }
    assert!(
        run_help_value
            .to_string()
            .starts_with("Result::Ok(Usage: cli-tool run [options]"),
        "{run_help_value}"
    );
}

#[test]
fn manifest_cli_tool_project_sample_reports_cli_parse_errors() {
    let entry = Path::new("samples/projects/cli_tool/src/main/main.muga");
    let missing_args = vec![
        "run".to_string(),
        "--count=3".to_string(),
        "--action".to_string(),
        "Audit".to_string(),
    ];
    let validation_args = vec![
        "run".to_string(),
        "service".to_string(),
        "--count=0".to_string(),
        "--action".to_string(),
        "Audit".to_string(),
    ];
    let unknown_args = vec!["deploy".to_string()];

    let missing =
        muga::run_path_with_args(entry, &missing_args).expect("CLI tool sample should run");
    let missing_value = missing.main_result.expect("main result should exist");
    assert_eq!(
        missing_value.to_string(),
        "Result::Err(cli MissingArgument <target>: missing required CLI positional `<target>`)"
    );
    assert_eq!(missing.output_text, "");

    let validation =
        muga::run_path_with_args(entry, &validation_args).expect("CLI tool sample should run");
    let validation_value = validation.main_result.expect("main result should exist");
    assert_eq!(
        validation_value.to_string(),
        "Result::Err(cli Validation --count: validation failed at path --count: expected Int >= 1)"
    );
    assert_eq!(validation.output_text, "");

    let unknown =
        muga::run_path_with_args(entry, &unknown_args).expect("CLI tool sample should run");
    let unknown_value = unknown.main_result.expect("main result should exist");
    assert_eq!(
        unknown_value.to_string(),
        "Result::Err(cli UnknownArgument deploy: unknown CLI command `deploy`)"
    );
    assert_eq!(unknown.output_text, "");
}

