#[test]
fn build_reuses_unchanged_local_path_dependency_artifacts() {
    let workspace = temp_package_root("build-reuse-local-path-dependency");
    let app_root = workspace.join("app");
    let shared_root = workspace.join("shared");
    write_package_file(
        &shared_root,
        "muga.toml",
        r#"
[package]
name = "shared"
source = "src"
"#,
    );
    let dependency = write_package_file(
        &shared_root,
        "src/logging/main.muga",
        r#"
pub fn value(): Int {
  11
}
"#,
    );
    write_package_file(
        &app_root,
        "muga.toml",
        r#"
[package]
name = "app"
source = "src"

[dependencies]
shared = { path = "../shared" }
"#,
    );
    let entry = write_package_file(
        &app_root,
        "src/main/main.muga",
        r#"
import shared::logging as logging

fn main(): Int {
  logging::value() + 1
}
"#,
    );

    let first = muga::build_package_artifacts(&entry).expect("first build should write artifacts");
    assert!(first.reused_artifacts.is_empty(), "{first:#?}");
    assert_eq!(first.written_artifacts.len(), first.artifacts.len());
    let shared_implementation =
        muga::implementation_artifact::persisted_file_path(&first.artifact_root, "shared::logging");
    let shared_interface = muga::interface::PackageInterfaceGraph::persisted_file_path(
        &first.artifact_root,
        "shared::logging",
    );
    let first_shared_artifact =
        muga::implementation_artifact::read_persisted_file(&shared_implementation)
            .expect("shared implementation artifact should parse");
    assert!(
        !first_shared_artifact.source_hash.is_empty(),
        "{first_shared_artifact:#?}"
    );

    let second =
        muga::build_package_artifacts(&entry).expect("second build should reuse artifacts");
    assert!(second.written_artifacts.is_empty(), "{second:#?}");
    assert_eq!(second.reused_artifacts.len(), second.artifacts.len());

    fs::write(
        &dependency,
        r#"
fn private_offset(): Int {
  0
}

pub fn value(): Int {
  99
}
"#,
    )
    .expect("dependency source should be overwritten");

    let third = muga::build_package_artifacts(&entry)
        .expect("dependency implementation change should rebuild implementation artifact");
    let app_interface = muga::interface::PackageInterfaceGraph::persisted_file_path(
        &third.artifact_root,
        "app::main",
    );
    assert!(
        third
            .written_artifacts
            .iter()
            .any(|path| path == &shared_implementation),
        "{third:#?}"
    );
    assert!(
        third
            .reused_artifacts
            .iter()
            .any(|path| path == &app_interface),
        "{third:#?}"
    );
    assert!(
        third
            .reused_artifacts
            .iter()
            .any(|path| path == &shared_interface),
        "{third:#?}"
    );
    let third_shared_artifact =
        muga::implementation_artifact::read_persisted_file(&shared_implementation)
            .expect("rebuilt shared implementation artifact should parse");
    assert_eq!(
        first_shared_artifact.interface_hash,
        third_shared_artifact.interface_hash
    );
    assert_ne!(
        first_shared_artifact.source_hash,
        third_shared_artifact.source_hash
    );

    let built_run = muga::run_path_against_default_build_artifacts(&entry)
        .expect("rebuilt artifacts should run with changed dependency implementation");
    let value = built_run.main_result.expect("main result should exist");
    assert_eq!(value.to_string(), "100");
}

#[test]
fn build_writes_local_path_dependency_lockfile() {
    let workspace = temp_package_root("build-local-path-lockfile");
    let app_root = workspace.join("app");
    let shared_root = workspace.join("shared");
    write_package_file(
        &shared_root,
        "muga.toml",
        r#"
[package]
name = "shared"
source = "src"
resources = "resources"
"#,
    );
    let dependency = write_package_file(
        &shared_root,
        "src/logging/main.muga",
        r#"
pub fn value(): Int {
  11
}
"#,
    );
    let dependency_resource = write_package_file(
        &shared_root,
        "resources/config/settings.txt",
        "mode = test\n",
    );
    write_package_file(
        &app_root,
        "muga.toml",
        r#"
[package]
name = "app"
source = "src"

[dependencies]
shared = { path = "../shared" }
"#,
    );
    let entry = write_package_file(
        &app_root,
        "src/main/main.muga",
        r#"
import shared::logging as logging

fn main(): Int {
  logging::value() + 1
}
"#,
    );

    muga::build_package_artifacts(&entry).expect("build should write artifacts and lockfile");
    let lockfile_path = app_root.join("muga.lock");
    let first_lockfile = fs::read_to_string(&lockfile_path).expect("lockfile should be written");
    assert!(
        first_lockfile.contains("lockfile_version = 1"),
        "{first_lockfile}"
    );
    assert!(
        first_lockfile.contains(&format!("muga_version = \"{}\"", env!("CARGO_PKG_VERSION"))),
        "{first_lockfile}"
    );
    assert!(first_lockfile.contains("[[package]]"), "{first_lockfile}");
    assert!(
        first_lockfile.contains("alias = \"shared\""),
        "{first_lockfile}"
    );
    assert!(
        first_lockfile.contains("path = \"shared\""),
        "{first_lockfile}"
    );
    assert!(
        first_lockfile.contains("source = { path = \"../shared\" }"),
        "{first_lockfile}"
    );
    let first_hash = lockfile_source_hash(&first_lockfile);
    assert!(first_hash.starts_with("sha256:"), "{first_hash}");
    assert_eq!(first_hash.len(), "sha256:".len() + 64, "{first_hash}");

    fs::write(
        &dependency,
        r#"
pub fn value(): Int {
  99
}
"#,
    )
    .expect("dependency source should be overwritten");
    muga::build_package_artifacts(&entry)
        .expect("build should refresh lockfile after dependency source change");
    let second_lockfile = fs::read_to_string(&lockfile_path).expect("lockfile should still exist");
    let second_hash = lockfile_source_hash(&second_lockfile);
    assert_ne!(first_hash, second_hash);

    fs::write(&dependency_resource, "mode = changed\n")
        .expect("dependency resource should be overwritten");
    muga::build_package_artifacts(&entry)
        .expect("build should refresh lockfile after dependency resource change");
    let resource_lockfile =
        fs::read_to_string(&lockfile_path).expect("lockfile should still exist");
    let resource_hash = lockfile_source_hash(&resource_lockfile);
    assert_ne!(second_hash, resource_hash);
}

#[test]
fn cli_build_reports_reuse_and_refreshes_local_path_lockfile_after_dependency_edits() {
    let workspace = temp_package_root("cli-build-local-path-lockfile-refresh");
    let app_root = workspace.join("app");
    let shared_root = workspace.join("shared");
    write_package_file(
        &shared_root,
        "muga.toml",
        r#"
[package]
name = "shared"
source = "src"
"#,
    );
    let dependency = write_package_file(
        &shared_root,
        "src/logging/main.muga",
        r#"
pub fn value(): Int {
  11
}
"#,
    );
    write_package_file(
        &app_root,
        "muga.toml",
        r#"
[package]
name = "app"
source = "src"

[dependencies]
shared = { path = "../shared" }
"#,
    );
    let entry = write_package_file(
        &app_root,
        "src/main/main.muga",
        r#"
import shared::logging as logging

fn main(): Int {
  logging::value() + 1
}
"#,
    );

    let first_build = muga_command()
        .arg("build")
        .arg(&entry)
        .output()
        .expect("muga command should run");
    let first_stdout = String::from_utf8_lossy(&first_build.stdout);
    assert!(first_build.status.success(), "{first_build:#?}");
    assert_eq!(String::from_utf8_lossy(&first_build.stderr), "");
    assert!(
        first_stdout
            .lines()
            .all(|line| line.starts_with("written\t")),
        "{first_stdout}"
    );
    for file_name in [
        "app__main.mgi",
        "shared__logging.mgi",
        "app__main.mgb",
        "shared__logging.mgb",
        "app__main.mgc",
    ] {
        assert!(
            build_output_has_status_for_file(&first_stdout, "written", file_name),
            "{first_stdout}"
        );
    }
    let lockfile_path = app_root.join("muga.lock");
    let first_lockfile = fs::read_to_string(&lockfile_path).expect("lockfile should be written");
    let first_hash = lockfile_source_hash(&first_lockfile);

    let second_build = muga_command()
        .arg("build")
        .arg(&entry)
        .output()
        .expect("muga command should run");
    let second_stdout = String::from_utf8_lossy(&second_build.stdout);
    assert!(second_build.status.success(), "{second_build:#?}");
    assert_eq!(String::from_utf8_lossy(&second_build.stderr), "");
    assert!(
        second_stdout
            .lines()
            .all(|line| line.starts_with("reused\t")),
        "{second_stdout}"
    );

    fs::write(
        &dependency,
        r#"
fn private_offset(): Int {
  88
}

pub fn value(): Int {
  private_offset() + 11
}
"#,
    )
    .expect("dependency source should be overwritten");

    let implementation_build = muga_command()
        .arg("build")
        .arg(&entry)
        .output()
        .expect("muga command should run");
    let implementation_stdout = String::from_utf8_lossy(&implementation_build.stdout);
    assert!(
        implementation_build.status.success(),
        "{implementation_build:#?}"
    );
    assert_eq!(String::from_utf8_lossy(&implementation_build.stderr), "");
    assert!(
        build_output_has_status_for_file(&implementation_stdout, "written", "shared__logging.mgb"),
        "{implementation_stdout}"
    );
    assert!(
        build_output_has_status_for_file(&implementation_stdout, "written", "app__main.mgb"),
        "{implementation_stdout}"
    );
    for file_name in ["shared__logging.mgi", "app__main.mgi", "app__main.mgc"] {
        assert!(
            build_output_has_status_for_file(&implementation_stdout, "reused", file_name),
            "{implementation_stdout}"
        );
    }
    let implementation_lockfile =
        fs::read_to_string(&lockfile_path).expect("lockfile should still exist");
    let implementation_hash = lockfile_source_hash(&implementation_lockfile);
    assert_ne!(first_hash, implementation_hash);

    let implementation_run = muga_command()
        .arg("run")
        .arg("--built")
        .arg(&entry)
        .output()
        .expect("muga command should run");
    assert!(
        implementation_run.status.success(),
        "{implementation_run:#?}"
    );
    assert_eq!(String::from_utf8_lossy(&implementation_run.stdout), "100\n");

    fs::write(
        &dependency,
        r#"
fn private_offset(): Int {
  89
}

pub fn value(): Int {
  private_offset() + 11
}

pub fn extra(): Int {
  1
}
"#,
    )
    .expect("dependency source should be overwritten");

    let public_build = muga_command()
        .arg("build")
        .arg(&entry)
        .output()
        .expect("muga command should run");
    let public_stdout = String::from_utf8_lossy(&public_build.stdout);
    assert!(public_build.status.success(), "{public_build:#?}");
    assert_eq!(String::from_utf8_lossy(&public_build.stderr), "");
    for file_name in [
        "shared__logging.mgi",
        "shared__logging.mgb",
        "app__main.mgb",
        "app__main.mgc",
    ] {
        assert!(
            build_output_has_status_for_file(&public_stdout, "written", file_name),
            "{public_stdout}"
        );
    }
    let public_lockfile = fs::read_to_string(&lockfile_path).expect("lockfile should still exist");
    let public_hash = lockfile_source_hash(&public_lockfile);
    assert_ne!(implementation_hash, public_hash);

    let public_run = muga_command()
        .arg("run")
        .arg("--built")
        .arg(&entry)
        .output()
        .expect("muga command should run");
    assert!(public_run.status.success(), "{public_run:#?}");
    assert_eq!(String::from_utf8_lossy(&public_run.stdout), "101\n");
}

#[test]
fn manifest_local_archive_dependency_materializes_cache_and_runs() {
    let workspace = temp_package_root("manifest-local-archive-dependency");
    let app_root = workspace.join("app");
    let shared_root = workspace.join("shared");
    let archive_root = workspace.join("archives#quoted\"root");
    write_package_file(
        &shared_root,
        "muga.toml",
        r#"
[package]
name = "shared"
source = "src"
"#,
    );
    let shared_entry = write_package_file(
        &shared_root,
        "src/logging/main.muga",
        r#"
pub fn value(): Int {
  11
}
"#,
    );
    let archive = muga::write_package_archive(&shared_entry, &archive_root)
        .expect("shared archive should be written");
    let archive_file = archive
        .path
        .file_name()
        .and_then(|name| name.to_str())
        .expect("archive should have a UTF-8 file name");
    write_package_file(
        &app_root,
        "muga.toml",
        &format!(
            r#"
[package]
name = "app"
source = "src"

[dependencies]
shared = {{ archive = "../archives#quoted\"root/{archive_file}", hash = "{}" }} # trailing comment
"#,
            archive.content_hash
        ),
    );
    let entry = write_package_file(
        &app_root,
        "src/main/main.muga",
        r#"
import shared::logging as logging

fn main(): Int {
  logging::value() + 1
}
"#,
    );

    let result = muga::run_path(&entry).expect("archive dependency should run");
    assert_eq!(
        result.main_result.map(|value| value.to_string()),
        Some("12".to_string())
    );

    let cache_root =
        archive_dependency_cache_root_for_test(&app_root, "shared", &archive.content_hash);
    assert!(cache_root.join("muga.toml").is_file());
    assert!(cache_root.join("src/logging/main.muga").is_file());

    fs::write(&archive.path, "not an archive").expect("archive file should be mutable in test");
    let cached_result = muga::run_path(&entry).expect("cached archive dependency should run");
    assert_eq!(
        cached_result.main_result.map(|value| value.to_string()),
        Some("12".to_string())
    );

    muga::build_package_artifacts(&entry).expect("build should write archive lockfile metadata");
    let lockfile =
        fs::read_to_string(app_root.join("muga.lock")).expect("lockfile should be written");
    assert!(
        lockfile.contains(&format!(
            "source = {{ archive = \"../archives#quoted\\\"root/{archive_file}\" }}"
        )),
        "{lockfile}"
    );
    assert!(
        lockfile.contains(&format!("hash = \"{}\"", archive.content_hash)),
        "{lockfile}"
    );
}

