#[test]
fn package_content_hash_covers_manifest_and_sorted_sources() {
    let workspace = temp_package_root("package-content-hash");
    let first_root = workspace.join("first");
    write_package_file(
        &first_root,
        "muga.toml",
        r#"
[package]
name = "demo"
source = "src"
"#,
    );
    let first_entry = write_package_file(
        &first_root,
        "src/main/main.muga",
        r#"
import demo::util as util

fn main(): Int {
  util::value()
}
"#,
    );
    write_package_file(
        &first_root,
        "src/util/main.muga",
        r#"
pub fn value(): Int {
  41
}
"#,
    );

    let first_hash = muga::package_content_hash(&first_entry)
        .expect("package content hash should compute")
        .expect("manifest package should produce a hash");
    assert!(first_hash.starts_with("sha256:"), "{first_hash}");
    assert_eq!(first_hash.len(), "sha256:".len() + 64, "{first_hash}");

    let second_root = workspace.join("second");
    write_package_file(
        &second_root,
        "src/util/main.muga",
        r#"
pub fn value(): Int {
  41
}
"#,
    );
    let second_entry = write_package_file(
        &second_root,
        "src/main/main.muga",
        r#"
import demo::util as util

fn main(): Int {
  util::value()
}
"#,
    );
    write_package_file(
        &second_root,
        "muga.toml",
        r#"
[package]
name = "demo"
source = "src"
"#,
    );
    let second_hash = muga::package_content_hash(&second_entry)
        .expect("equivalent package content hash should compute")
        .expect("manifest package should produce a hash");
    assert_eq!(first_hash, second_hash);

    fs::write(
        second_root.join("src/util/main.muga"),
        r#"
pub fn value(): Int {
  42
}
"#
        .trim_start(),
    )
    .expect("source file should be updated");
    let source_changed_hash = muga::package_content_hash(&second_entry)
        .expect("source-changed package content hash should compute")
        .expect("manifest package should produce a hash");
    assert_ne!(first_hash, source_changed_hash);

    fs::write(
        second_root.join("muga.toml"),
        r#"
[package]
name = "demo"
source = "src"

# The manifest bytes are part of the canonical package content input.
"#
        .trim_start(),
    )
    .expect("manifest should be updated");
    let manifest_changed_hash = muga::package_content_hash(&second_entry)
        .expect("manifest-changed package content hash should compute")
        .expect("manifest package should produce a hash");
    assert_ne!(source_changed_hash, manifest_changed_hash);
}

