#[test]
fn package_archive_emission_writes_deterministic_source_archive() {
    let workspace = temp_package_root("package-archive-emission");
    let first_root = workspace.join("first");
    write_package_file(
        &first_root,
        "muga.toml",
        r#"
[package]
name = "demo"
source = "src"
"#,
    );
    let first_entry = write_package_file(
        &first_root,
        "src/main/main.muga",
        r#"
import demo::util as util

fn main(): Int {
  util::value()
}
"#,
    );
    write_package_file(
        &first_root,
        "src/util/main.muga",
        r#"
pub fn value(): Int {
  41
}
"#,
    );
    write_package_file(
        &first_root,
        "src/.muga/build/ignored.muga",
        r#"
this should not contribute
"#,
    );
    write_package_file(
        &first_root,
        "src/.git/ignored.muga",
        r#"
this should also not contribute
"#,
    );
    write_package_file(&first_root, "src/notes.txt", "not source");
    write_package_file(&first_root, "src/muga.lock", "not source");

    let first_archive_root = workspace.join("archives-a");
    let first_archive = muga::write_package_archive(&first_entry, &first_archive_root)
        .expect("package archive should be written");
    let expected_hash = muga::package_content_hash(&first_entry)
        .expect("package content hash should compute")
        .expect("manifest package should produce a hash");
    assert_eq!(first_archive.content_hash, expected_hash);
    let first_archive_text =
        fs::read_to_string(&first_archive.path).expect("archive should be readable");
    assert!(first_archive_text.starts_with("manifest\tmuga.toml\t"));
    let main_index = first_archive_text
        .find("file\tmain/main.muga\t")
        .expect("archive should include main source");
    let util_index = first_archive_text
        .find("file\tutil/main.muga\t")
        .expect("archive should include util source");
    assert!(main_index < util_index, "{first_archive_text}");
    assert!(
        !first_archive_text.contains("this should not contribute"),
        "{first_archive_text}"
    );
    assert!(
        !first_archive_text.contains("this should also not contribute"),
        "{first_archive_text}"
    );
    assert!(
        !first_archive_text.contains("not source"),
        "{first_archive_text}"
    );
    let hash_hex = first_archive
        .content_hash
        .strip_prefix("sha256:")
        .expect("content hash should use sha256 prefix");
    let expected_file_name = format!("demo-sha256-{hash_hex}.mgp");
    assert_eq!(
        first_archive
            .path
            .file_name()
            .and_then(|name| name.to_str()),
        Some(expected_file_name.as_str())
    );

    let second_root = workspace.join("second");
    write_package_file(
        &second_root,
        "src/util/main.muga",
        r#"
pub fn value(): Int {
  41
}
"#,
    );
    let second_entry = write_package_file(
        &second_root,
        "src/main/main.muga",
        r#"
import demo::util as util

fn main(): Int {
  util::value()
}
"#,
    );
    write_package_file(
        &second_root,
        "muga.toml",
        r#"
[package]
name = "demo"
source = "src"
"#,
    );
    let second_archive = muga::write_package_archive(&second_entry, &workspace.join("archives-b"))
        .expect("equivalent package archive should be written");
    let second_archive_text =
        fs::read_to_string(&second_archive.path).expect("second archive should be readable");
    assert_eq!(first_archive.content_hash, second_archive.content_hash);
    assert_eq!(first_archive_text, second_archive_text);
}

