#[test]
fn build_orders_package_artifacts_by_dependency_levels() {
    let workspace = temp_package_root("build-dependency-level-order");
    let app_root = workspace.join("app");
    let alpha_root = workspace.join("alpha");
    let beta_root = workspace.join("beta");
    write_package_file(
        &alpha_root,
        "muga.toml",
        r#"
[package]
name = "alpha"
source = "src"
"#,
    );
    write_package_file(
        &alpha_root,
        "src/math/main.muga",
        r#"
pub fn value(): Int {
  2
}
"#,
    );
    write_package_file(
        &beta_root,
        "muga.toml",
        r#"
[package]
name = "beta"
source = "src"
"#,
    );
    write_package_file(
        &beta_root,
        "src/text/main.muga",
        r#"
pub fn value(): Int {
  10
}
"#,
    );
    write_package_file(
        &app_root,
        "muga.toml",
        r#"
[package]
name = "app"
source = "src"

[dependencies]
alpha = { path = "../alpha" }
beta = { path = "../beta" }
"#,
    );
    let entry = write_package_file(
        &app_root,
        "src/main/main.muga",
        r#"
import alpha::math as math
import beta::text as text

fn main(): Int {
  math::value() + text::value()
}
"#,
    );

    let build = muga::build_package_artifacts(&entry).expect("build should write artifacts");
    let artifact_names = build
        .artifacts
        .iter()
        .map(|path| {
            path.file_name()
                .expect("artifact should have file name")
                .to_string_lossy()
                .to_string()
        })
        .collect::<Vec<_>>();
    let position = |name: &str| {
        artifact_names
            .iter()
            .position(|artifact_name| artifact_name == name)
            .unwrap_or_else(|| panic!("missing {name}: {artifact_names:?}"))
    };

    assert!(position("alpha__math.mgi") < position("beta__text.mgi"));
    assert!(position("beta__text.mgi") < position("app__main.mgi"));
    assert!(position("alpha__math.mgb") < position("beta__text.mgb"));
    assert!(position("beta__text.mgb") < position("app__main.mgb"));

    let built_run =
        muga::run_path_against_default_build_artifacts(&entry).expect("built artifacts should run");
    let value = built_run.main_result.expect("main result should exist");
    assert_eq!(value.to_string(), "12");
}

