#[test]
fn package_public_signatures_round_trip_representative_type_shapes() {
    let provider_root = temp_package_root("public-signature-round-trip-provider");
    write_package_file(
        &provider_root,
        "model/types/main.muga",
        r#"
package model::types

pub record Score {
  label: String
  points: Int
  active: Bool
}

pub record Box[T] {
  value: T
}

pub enum Stage[T] {
  Ready(T)
  Failed(String)
  Empty
}

pub fn identity[T](value: T): T {
  value
}

pub fn keep_unit(): Unit {
  ()
}

pub fn transform(score: Score, mapper: Score -> Score): Score {
  mapper(score)
}
"#,
    );
    write_package_file(
        &provider_root,
        "api/shapes/main.muga",
        r#"
package api::shapes

import model::types
import std::io
import std::path

pub enum ApiEvent[T] {
  Wrapped(T)
  Score(types::Score)
  Located(path::Path)
  Failed(io::IOError)
  Nothing
}

pub record Envelope[T] {
  value: T
  items: List[T]
  index: Map[String, T]
  maybe: Option[T]
  outcome: Result[T, io::IOError]
}

pub fn select_handler(handler: types::Score -> types::Score): types::Score -> types::Score {
  handler
}

pub fn audit(
  envelope: Envelope[types::Score],
  handler: (types::Score, path::Path) -> Result[String, io::IOError],
  maybe: Option[types::Score],
  scores: List[types::Score],
  table: Map[String, types::Score],
  stage: types::Stage[types::Score],
  file: path::Path
): Result[ApiEvent[types::Score], io::IOError] {
  Result::Ok(ApiEvent::Wrapped(envelope.value))
}
"#,
    );
    let provider_entry = write_package_file(
        &provider_root,
        "app/provider/main.muga",
        r#"
package app::provider

import api::shapes

fn main(): Int {
  0
}
"#,
    );

    let program =
        muga::compile_typed_path(&provider_entry).expect("provider package should typecheck");
    let interfaces = program.package_interfaces();
    assert_representative_public_signature_shapes(&interfaces, &program.symbols);
    let text = interfaces.to_persisted_text(&program.symbols);
    for required in [
        "PackageRecord",
        "PackageEnum",
        "GenericParam",
        "List",
        "Map",
        "Option",
        "Result",
        "Function",
        "Unit",
        "Bool",
        "String",
        "Int",
        "std::io",
        "std::path",
    ] {
        assert!(
            text.contains(required),
            "persisted public signature text missing `{required}`:\n{text}"
        );
    }

    let mut symbols = program.symbols.clone();
    let loaded = muga::interface::PackageInterfaceGraph::from_persisted_text(&text, &mut symbols)
        .expect("persisted interfaces should parse");
    assert_eq!(
        loaded.stable_hash(&symbols),
        interfaces.stable_hash(&program.symbols)
    );
    assert_representative_public_signature_shapes(&loaded, &symbols);

    let consumer_root = temp_package_root("public-signature-round-trip-consumer");
    let consumer_entry = write_package_file(
        &consumer_root,
        "app/consumer/main.muga",
        r#"
package app::consumer

import api::shapes
import model::types
import std::io
import std::path

fn keep_label(score: types::Score, file: path::Path): Result[String, io::IOError] {
  Result::Ok(score.label)
}

fn keep_same(score: types::Score): types::Score {
  score
}

fn main(): Int {
  score = types::Score {
    label: "ready"
    points: 7
    active: true
  }
  selected = shapes::select_handler(keep_same)
  same = selected(score)
  ok_score: Result[types::Score, io::IOError] = Result::Ok(same)
  envelope: shapes::Envelope[types::Score] = shapes::Envelope {
    value: same
    items: [same]
    index: Map.empty()
    maybe: Option::Some(same)
    outcome: ok_score
  }
  result = shapes::audit(
    envelope,
    keep_label,
    Option::Some(same),
    [same],
    Map.empty(),
    types::Stage::Ready(same),
    path::from_string("report.txt")
  )
  match result {
    Result::Ok(event) => same.points
    Result::Err(error) => 0
  }
}
"#,
    );

    assert!(!consumer_root.join("api/shapes/main.muga").exists());
    assert!(!consumer_root.join("model/types/main.muga").exists());
    muga::check_package_aware_path_against_loaded_interfaces(&consumer_entry, &loaded, &symbols)
        .expect("consumer should typecheck against representative loaded public signatures");
}

#[test]
fn package_interface_persists_public_doc_comments_without_hashing_them() {
    let root = temp_package_root("interface-doc-comments");
    write_package_file(
        &root,
        "muga.toml",
        r#"
[package]
name = "doc_hash"
source = "src"
"#,
    );
    let entry = write_package_file(
        &root,
        "src/api/main.muga",
        r#"
/// A public widget.
pub record Widget {
  value: Int
}

/// Reads the widget value.
pub fn read(widget: Widget): Int {
  widget.value
}
"#,
    );

    let program = muga::compile_typed_path(&entry).expect("typed package compilation should pass");
    let interfaces = program.package_interfaces();
    let package = interfaces
        .package_by_path("doc_hash::api")
        .expect("package interface should exist");
    assert_eq!(
        package.records[0].doc_comments,
        vec!["A public widget.".to_string()]
    );
    assert_eq!(
        package.functions[0].doc_comments,
        vec!["Reads the widget value.".to_string()]
    );

    let text = interfaces.to_persisted_text(&program.symbols);
    assert!(text.contains("\ndoc\tA public widget.\n"), "{text}");
    assert!(text.contains("\ndoc\tReads the widget value.\n"), "{text}");

    let mut symbols = program.symbols.clone();
    let loaded = muga::interface::PackageInterfaceGraph::from_persisted_text(&text, &mut symbols)
        .expect("persisted interfaces should parse");
    let loaded_package = loaded
        .package_by_path("doc_hash::api")
        .expect("loaded package should exist");
    assert_eq!(
        loaded_package.records[0].doc_comments,
        vec!["A public widget.".to_string()]
    );
    assert_eq!(
        loaded.stable_hash(&symbols),
        interfaces.stable_hash(&program.symbols)
    );

    let changed_docs = text.replace("A public widget.", "A changed public widget.");
    let mut changed_symbols = program.symbols.clone();
    let loaded_changed = muga::interface::PackageInterfaceGraph::from_persisted_text(
        &changed_docs,
        &mut changed_symbols,
    )
    .expect("doc-only interface changes should still parse");
    assert_eq!(
        loaded_changed.stable_hash(&changed_symbols),
        interfaces.stable_hash(&program.symbols)
    );
}

#[test]
fn package_interface_hash_is_stable_for_same_interface() {
    let program = muga::compile_typed_path(Path::new("samples/packages/app/main/main.muga"))
        .expect("typed package compilation should pass");
    let interfaces = program.package_interfaces();
    assert_eq!(
        interfaces.stable_hash(&program.symbols),
        interfaces.stable_hash(&program.symbols)
    );

    let text = interfaces.to_persisted_text(&program.symbols);
    let mut symbols = program.symbols.clone();
    let loaded = muga::interface::PackageInterfaceGraph::from_persisted_text(&text, &mut symbols)
        .expect("persisted interfaces should parse");
    assert_eq!(
        loaded.stable_hash(&symbols),
        interfaces.stable_hash(&program.symbols)
    );
}

#[test]
fn package_interface_hash_ignores_diagnostic_spans() {
    let root = temp_package_root("interface-hash-ignores-spans");
    write_package_file(
        &root,
        "muga.toml",
        r#"
[package]
name = "demo"
source = "src"
"#,
    );
    let entry = write_package_file(
        &root,
        "src/interface/main.muga",
        r#"
package demo::interface

pub record Widget {
  value: Int
}

pub enum Status {
  Ready(Widget)
  Waiting
}

pub fn read(widget: Widget): Int {
  widget.value
}
"#,
    );
    let program = muga::compile_typed_path(&entry).expect("typed package compilation should pass");
    let interfaces = program.package_interfaces();
    let original_hash = interfaces.stable_hash(&program.symbols);

    let moved_span = muga::span::Span::new(
        muga::span::Position::new(90, 7),
        muga::span::Position::new(91, 13),
    );
    let mut moved = interfaces.clone();
    for package in &mut moved.packages {
        for record in &mut package.records {
            record.span = moved_span;
            for field in &mut record.fields {
                field.span = moved_span;
            }
        }
        for enumeration in &mut package.enums {
            enumeration.span = moved_span;
            for variant in &mut enumeration.variants {
                variant.span = moved_span;
            }
        }
        for function in &mut package.functions {
            function.span = moved_span;
            for param in &mut function.params {
                param.span = moved_span;
            }
        }
    }

    assert_eq!(moved.stable_hash(&program.symbols), original_hash);
}

#[test]
fn package_interface_hash_stays_stable_for_representative_public_shapes() {
    let original_root = temp_package_root("interface-hash-representative-original");
    write_package_file(
        &original_root,
        "model/score/main.muga",
        r#"
package model::score

pub record Score {
  label: String
  points: Int
}

pub enum Stage[T] {
  Ready(T)
  Failed(String)
}

pub fn ready[T](value: T): Stage[T] {
  Stage::Ready(value)
}
"#,
    );
    write_package_file(
        &original_root,
        "api/reports/main.muga",
        r#"
package api::reports

import model::score
import std::io
import std::path

pub record Envelope[T] {
  value: T
}

pub enum Report[T] {
  Complete(T)
  Failed(io::IOError)
}

pub fn wrap[T](value: T): Envelope[T] {
  Envelope {
    value: value
  }
}

pub fn from_path(file: path::Path, item: score::Score): Report[Envelope[score::Score]] {
  Report::Complete(wrap(item))
}

pub fn normalize(stage: score::Stage[score::Score]): score::Stage[score::Score] {
  stage
}
"#,
    );
    let original_entry = write_package_file(
        &original_root,
        "app/provider/main.muga",
        r#"
package app::provider

import api::reports

fn main(): String {
  "ok"
}
"#,
    );

    let edited_root = temp_package_root("interface-hash-representative-edited");
    write_package_file(
        &edited_root,
        "model/score/main.muga",
        r#"
package model::score



fn private_bias(): Int {
  1
}

pub record Score {
  label: String
  points: Int
}


pub enum Stage[T] {
  Ready(T)
  Failed(String)
}

pub fn ready[T](value: T): Stage[T] {
  selected = value
  if private_bias() == 1 {
    Stage::Ready(selected)
  } else {
    Stage::Failed("unexpected")
  }
}
"#,
    );
    write_package_file(
        &edited_root,
        "api/reports/main.muga",
        r#"
package api::reports

import model::score
import std::io
import std::path


fn private_label(file: path::Path): String {
  path::as_string(file)
}


pub record Envelope[T] {
  value: T
}


pub enum Report[T] {
  Complete(T)
  Failed(io::IOError)
}

pub fn wrap[T](value: T): Envelope[T] {
  wrapped = Envelope {
    value: value
  }
  wrapped
}


pub fn from_path(file: path::Path, item: score::Score): Report[Envelope[score::Score]] {
  label = private_label(file)
  if label.char_count() >= 0 {
    Report::Complete(wrap(item))
  } else {
    Report::Complete(wrap(item))
  }
}

pub fn normalize(stage: score::Stage[score::Score]): score::Stage[score::Score] {
  match stage {
    score::Stage::Ready(value) => score::Stage::Ready(value)
    score::Stage::Failed(message) => score::Stage::Failed(message)
  }
}
"#,
    );
    let edited_entry = write_package_file(
        &edited_root,
        "app/provider/main.muga",
        r#"
package app::provider

import api::reports

fn main(): String {
  "ok"
}
"#,
    );

    let original = muga::compile_typed_path(&original_entry)
        .expect("original typed package compilation should pass");
    let edited = muga::compile_typed_path(&edited_entry)
        .expect("edited typed package compilation should pass");
    let original_interfaces = original.package_interfaces();
    let edited_interfaces = edited.package_interfaces();

    for package_path in ["model::score", "api::reports"] {
        assert_eq!(
            original_interfaces.stable_hash_for_package(package_path, &original.symbols),
            edited_interfaces.stable_hash_for_package(package_path, &edited.symbols),
            "{package_path} public interface hash should ignore implementation-only edits and source-span movement"
        );
    }

    let original_api_hash = original_interfaces
        .stable_hash_for_package("api::reports", &original.symbols)
        .expect("original API interface hash should exist");
    let edited_api_hash = edited_interfaces
        .stable_hash_for_package("api::reports", &edited.symbols)
        .expect("edited API interface hash should exist");
    let original_api_text = original_interfaces
        .persisted_artifact_text("api::reports", &original.symbols)
        .expect("original API interface artifact text should render");
    let edited_api_text = edited_interfaces
        .persisted_artifact_text("api::reports", &edited.symbols)
        .expect("edited API interface artifact text should render");
    assert_ne!(
        original_api_text, edited_api_text,
        "persisted text should still carry moved diagnostic spans"
    );
    assert!(original_api_text.contains(&format!("\nhash\t{original_api_hash}\n")));
    assert!(edited_api_text.contains(&format!("\nhash\t{edited_api_hash}\n")));

    let original_api = original_interfaces
        .package_by_path("api::reports")
        .expect("original API interface should exist");
    let edited_api = edited_interfaces
        .package_by_path("api::reports")
        .expect("edited API interface should exist");
    assert_ne!(
        original_api.records[0].span.start.line, edited_api.records[0].span.start.line,
        "source-span movement should be present in the audited interface"
    );
    assert_ne!(
        original_api.enums[0].span.start.line, edited_api.enums[0].span.start.line,
        "generic enum span movement should be present in the audited interface"
    );
    assert_ne!(
        original_api.functions[0].span.start.line, edited_api.functions[0].span.start.line,
        "generic function span movement should be present in the audited interface"
    );
}

