fn package_check_reports_stale_generic_interface_artifact_with_regeneration_command() {
    let provider_root = temp_package_root("interface-artifact-stale-generic-provider");
    let provider_entry = write_package_file(
        &provider_root,
        "app/provider/main.muga",
        r#"
package app::provider

import util::generic

fn main(): Int {
  wrapped: generic::Box[Int] = generic::make_box(1)
  wrapped.value
}
"#,
    );
    write_package_file(
        &provider_root,
        "util/generic/main.muga",
        r#"
package util::generic

pub record Box[T] {
  value: T
}

pub fn make_box(value: Int): Box[Int] {
  Box {
    value: value
  }
}
"#,
    );
    let provider =
        muga::compile_typed_path(&provider_entry).expect("provider package should typecheck");
    let mut interfaces = provider.package_interfaces();
    interfaces
        .packages
        .iter_mut()
        .find(|package| package.path == "util::generic")
        .expect("generic package should exist")
        .records
        .iter_mut()
        .find(|record| record.name == "Box")
        .expect("Box should be exported")
        .type_params
        .push("E".to_string());

    let artifact_root = temp_package_root("interface-artifact-stale-generic");
    write_interface_artifacts(
        &artifact_root,
        &interfaces,
        &provider.symbols,
        &["util::generic"],
    );
    let consumer_root = temp_package_root("interface-artifact-stale-generic-consumer");
    let consumer_entry = write_package_file(
        &consumer_root,
        "app/consumer/main.muga",
        r#"
package app::consumer

import util::generic

fn main(): Int {
  wrapped: generic::Box[Int] = generic::make_box(41)
  wrapped.value + 1
}
"#,
    );

    let diagnostics =
        muga::compile_typed_path_against_interface_artifacts(&consumer_entry, &artifact_root)
            .unwrap_err();
    let Some(diagnostic) = diagnostics.iter().find(|diagnostic| {
        diagnostic.code == "PK019"
            && diagnostic.message.contains("package interface artifact")
            && diagnostic.message.contains("util::generic")
            && diagnostic
                .message
                .contains("stale generic record reference `util::generic::Box`")
    }) else {
        panic!(
            "stale generic interface artifact diagnostic should include artifact context: {diagnostics:#?}"
        );
    };
    assert!(
        diagnostic
            .suggestions
            .iter()
            .any(|suggestion| suggestion.message.contains("muga build")
                && suggestion.message.contains("muga emit-interface")),
        "{diagnostic:#?}"
    );
}

