#[test]
fn package_cache_rejects_stale_dependency_interface_artifact() {
    let provider = muga::compile_typed_path(Path::new("samples/packages/app/main/main.muga"))
        .expect("typed package compilation should pass");
    let numbers = provider
        .package_graph
        .package_id("util::numbers")
        .expect("numbers package should exist");
    let mut interfaces = provider.package_interfaces();
    let artifact_root = temp_package_root("cache-stale-dependency-artifacts");
    write_interface_artifacts(
        &artifact_root,
        &interfaces,
        &provider.symbols,
        &["util::numbers"],
    );
    let root = temp_package_root("cache-stale-dependency-downstream");
    let entry = write_package_file(
        &root,
        "app/cache_stale_dependency/main.muga",
        r#"
package app::cache_stale_dependency

import util::numbers

fn main(): Int {
  numbers::inc_twice(1)
}
"#,
    );
    let artifact_path = muga::package_check_cache_artifact_path(&artifact_root, &entry)
        .expect("check cache path should be derived");
    let key = muga::package_check_cache_key(&entry, &artifact_root)
        .expect("cache key should be computed");
    muga::write_package_check_cache_artifact(&artifact_path, &key)
        .expect("check cache artifact should be written");

    interfaces
        .packages
        .iter_mut()
        .find(|interface| interface.package == numbers)
        .expect("numbers interface should exist")
        .functions
        .iter_mut()
        .find(|function| function.name == "inc_twice")
        .expect("inc_twice should be exported")
        .ret = muga::types::TypeInfo::String;
    write_interface_artifacts(
        &artifact_root,
        &interfaces,
        &provider.symbols,
        &["util::numbers"],
    );

    let diagnostics = muga::compile_typed_path_against_cached_interface_artifacts(
        &entry,
        &artifact_root,
        &artifact_path,
    )
    .unwrap_err();
    let diagnostic_json = diagnostics
        .iter()
        .find(|diagnostic| diagnostic.code == "PK021")
        .expect("stale dependency check cache diagnostic should exist")
        .to_json_object();

    assert!(
        diagnostics.iter().any(|diagnostic| {
            diagnostic.code == "PK021"
                && diagnostic
                    .message
                    .contains("dependency interface `util::numbers` changed")
        }),
        "{diagnostics:#?}"
    );
    assert!(
        diagnostic_json.contains("\"kind\":\"artifactHash\""),
        "{diagnostic_json}"
    );
    assert!(
        diagnostic_json.contains("\"hashKind\":\"dependencyInterface\""),
        "{diagnostic_json}"
    );
    assert!(
        diagnostic_json.contains("\"packagePath\":\"util::numbers\""),
        "{diagnostic_json}"
    );
    assert!(
        diagnostic_json.contains("\"kind\":\"regenerationCommand\""),
        "{diagnostic_json}"
    );
}

