#[test]
fn cli_emit_package_archive_writes_archive_and_hash() {
    let workspace = temp_package_root("cli-emit-package-archive");
    write_package_file(
        &workspace,
        "muga.toml",
        r#"
[package]
name = "demo"
source = "src"
"#,
    );
    let entry = write_package_file(
        &workspace,
        "src/main/main.muga",
        r#"
fn main(): Int {
  7
}
"#,
    );
    let archive_root = workspace.join("archives");
    let output = muga_command()
        .arg("emit-package-archive")
        .arg("--archive-root")
        .arg(&archive_root)
        .arg(&entry)
        .output()
        .expect("muga command should run");
    let stdout = String::from_utf8_lossy(&output.stdout);
    let stderr = String::from_utf8_lossy(&output.stderr);

    assert!(output.status.success(), "{output:#?}");
    assert_eq!(stderr, "");
    let lines = stdout.lines().collect::<Vec<_>>();
    assert_eq!(lines.len(), 2, "{stdout}");
    let archive_path = std::path::PathBuf::from(lines[0]);
    assert!(archive_path.is_file(), "{stdout}");
    let expected_hash = muga::package_content_hash(&entry)
        .expect("package content hash should compute")
        .expect("manifest package should produce a hash");
    assert_eq!(lines[1], expected_hash);
    assert!(
        archive_path
            .file_name()
            .and_then(|name| name.to_str())
            .is_some_and(|name| name.ends_with(".mgp") && name.contains(&expected_hash[7..])),
        "{stdout}"
    );

    let json_archive_root = workspace.join("json-archives");
    let json_output = muga_command()
        .arg("emit-package-archive")
        .arg("--format")
        .arg("json")
        .arg("--archive-root")
        .arg(&json_archive_root)
        .arg("--dependency-snippet")
        .arg(&entry)
        .output()
        .expect("muga emit-package-archive --format json should run");
    let json_stdout = String::from_utf8_lossy(&json_output.stdout);
    let json_stderr = String::from_utf8_lossy(&json_output.stderr);

    assert!(json_output.status.success(), "{json_output:#?}");
    assert_eq!(json_stderr, "");
    assert!(
        json_stdout.contains("\"command\":\"emit-package-archive\"")
            && json_stdout.contains("\"status\":\"ok\"")
            && json_stdout.contains("\"entryPackage\":\"demo\"")
            && json_stdout.contains("\"dependencySnippet\"")
            && json_stdout.contains("[dependencies]\\n")
            && json_stdout.contains(&expected_hash),
        "{json_stdout}"
    );
    let json_archives = fs::read_dir(&json_archive_root)
        .expect("json archive root should be readable")
        .collect::<Result<Vec<_>, _>>()
        .expect("json archive entries should be readable");
    assert_eq!(json_archives.len(), 1, "{json_stdout}");
    assert!(json_archives[0].path().is_file(), "{json_stdout}");
}

#[test]
fn cli_verify_package_archive_validates_hash_from_filename() {
    let workspace = temp_package_root("cli-verify-package-archive");
    write_package_file(
        &workspace,
        "muga.toml",
        r#"
[package]
name = "demo"
source = "src"
resources = "resources"
"#,
    );
    let entry = write_package_file(
        &workspace,
        "src/main/main.muga",
        r#"
fn main(): Int {
  7
}
"#,
    );
    write_package_bytes_file(&workspace, "resources/static/logo.bin", &[0, 1, 2, 3]);

    let archive_root = workspace.join("archives");
    let emit = muga_command()
        .arg("emit-package-archive")
        .arg("--archive-root")
        .arg(&archive_root)
        .arg(&entry)
        .output()
        .expect("muga emit-package-archive should run");
    let emit_stdout = String::from_utf8_lossy(&emit.stdout);
    assert!(emit.status.success(), "{emit:#?}");
    let emit_lines = emit_stdout.lines().collect::<Vec<_>>();
    assert_eq!(emit_lines.len(), 2, "{emit_stdout}");
    let archive_path = std::path::PathBuf::from(emit_lines[0]);
    let expected_hash = emit_lines[1];

    let verify = muga_command()
        .arg("verify-package-archive")
        .arg(&archive_path)
        .output()
        .expect("muga verify-package-archive should run");
    let verify_stdout = String::from_utf8_lossy(&verify.stdout);
    let verify_stderr = String::from_utf8_lossy(&verify.stderr);
    assert!(verify.status.success(), "{verify:#?}");
    assert_eq!(verify_stderr, "");
    assert!(verify_stdout.contains("status\tok"), "{verify_stdout}");
    assert!(
        verify_stdout.contains(&format!("hash\t{expected_hash}")),
        "{verify_stdout}"
    );
    assert!(
        verify_stdout.contains("manifest\tmuga.toml"),
        "{verify_stdout}"
    );
    assert!(verify_stdout.contains("sources\t1"), "{verify_stdout}");
    assert!(verify_stdout.contains("resources\t1"), "{verify_stdout}");

    let verify_json = muga_command()
        .arg("verify-package-archive")
        .arg("--format")
        .arg("json")
        .arg(&archive_path)
        .output()
        .expect("muga verify-package-archive --format json should run");
    let verify_json_stdout = String::from_utf8_lossy(&verify_json.stdout);
    let verify_json_stderr = String::from_utf8_lossy(&verify_json.stderr);
    assert!(verify_json.status.success(), "{verify_json:#?}");
    assert_eq!(verify_json_stderr, "");
    assert!(
        verify_json_stdout.contains("\"command\":\"verify-package-archive\""),
        "{verify_json_stdout}"
    );
    assert!(
        verify_json_stdout.contains(&format!("\"hash\":\"{expected_hash}\"")),
        "{verify_json_stdout}"
    );
    assert!(
        verify_json_stdout.contains("\"manifest\":{\"path\":\"muga.toml\"}"),
        "{verify_json_stdout}"
    );
    assert!(
        verify_json_stdout.contains("\"path\":\"main/main.muga\""),
        "{verify_json_stdout}"
    );
    assert!(
        verify_json_stdout.contains("\"path\":\"static/logo.bin\""),
        "{verify_json_stdout}"
    );

    let filename_unpacked = workspace.join("filename-unpacked");
    let unpack = muga_command()
        .arg("unpack-package-archive")
        .arg("--output-dir")
        .arg(&filename_unpacked)
        .arg(&archive_path)
        .output()
        .expect("muga unpack-package-archive should run");
    let unpack_stdout = String::from_utf8_lossy(&unpack.stdout);
    let unpack_stderr = String::from_utf8_lossy(&unpack.stderr);
    assert!(unpack.status.success(), "{unpack:#?}");
    assert_eq!(unpack_stderr, "");
    assert!(
        unpack_stdout.contains("written\t")
            && filename_unpacked.join("muga.toml").is_file()
            && filename_unpacked.join("src/main/main.muga").is_file(),
        "{unpack_stdout}"
    );
    assert_eq!(
        fs::read(filename_unpacked.join("resources/static/logo.bin"))
            .expect("materialized binary resource should be readable"),
        vec![0, 1, 2, 3]
    );

    let json_unpacked = workspace.join("json-unpacked");
    let unpack_json = muga_command()
        .arg("unpack-package-archive")
        .arg("--format")
        .arg("json")
        .arg("--output-dir")
        .arg(&json_unpacked)
        .arg(&archive_path)
        .output()
        .expect("muga unpack-package-archive --format json should run");
    let unpack_json_stdout = String::from_utf8_lossy(&unpack_json.stdout);
    let unpack_json_stderr = String::from_utf8_lossy(&unpack_json.stderr);
    assert!(unpack_json.status.success(), "{unpack_json:#?}");
    assert_eq!(unpack_json_stderr, "");
    assert!(
        unpack_json_stdout.contains("\"command\":\"unpack-package-archive\"")
            && unpack_json_stdout.contains("\"status\":\"ok\"")
            && unpack_json_stdout.contains("\"root\":{\"path\":\"")
            && unpack_json_stdout.contains(&format!("\"hash\":\"{expected_hash}\""))
            && unpack_json_stdout.contains("src/main/main.muga")
            && unpack_json_stdout.contains("resources/static/logo.bin")
            && json_unpacked.join("muga.toml").is_file()
            && json_unpacked.join("resources/static/logo.bin").is_file(),
        "{unpack_json_stdout}"
    );

    let bad_hash_archive =
        archive_path.with_file_name(format!("demo-sha256-{}.mgp", "0".repeat(64)));
    fs::write(
        &bad_hash_archive,
        fs::read(&archive_path).expect("archive bytes should be readable"),
    )
    .expect("bad hash archive copy should be written");
    let bad_hash = muga_command()
        .arg("verify-package-archive")
        .arg("--format")
        .arg("json")
        .arg(&bad_hash_archive)
        .output()
        .expect("muga verify-package-archive bad hash should run");
    let bad_hash_stdout = String::from_utf8_lossy(&bad_hash.stdout);
    let bad_hash_stderr = String::from_utf8_lossy(&bad_hash.stderr);
    assert!(!bad_hash.status.success(), "{bad_hash:#?}");
    assert_eq!(bad_hash_stderr, "");
    assert!(
        bad_hash_stdout.contains("\"command\":\"verify-package-archive\""),
        "{bad_hash_stdout}"
    );
    assert!(
        bad_hash_stdout.contains("\"status\":\"error\""),
        "{bad_hash_stdout}"
    );
    assert!(
        bad_hash_stdout.contains("package archive hash mismatch"),
        "{bad_hash_stdout}"
    );
    assert!(
        bad_hash_stdout.contains("packageArchive"),
        "{bad_hash_stdout}"
    );

    let wrong_name_archive = archive_path.with_file_name("wrong-name.mgp");
    fs::write(
        &wrong_name_archive,
        fs::read(&archive_path).expect("archive bytes should be readable"),
    )
    .expect("wrong name archive copy should be written");
    let wrong_name = muga_command()
        .arg("verify-package-archive")
        .arg(&wrong_name_archive)
        .output()
        .expect("muga verify-package-archive wrong name should run");
    let wrong_name_stderr = String::from_utf8_lossy(&wrong_name.stderr);
    assert!(!wrong_name.status.success(), "{wrong_name:#?}");
    assert!(
        wrong_name_stderr.contains("must use a `*-sha256-<hash>.mgp` file name"),
        "{wrong_name_stderr}"
    );

    let explicit_hash = muga_command()
        .arg("verify-package-archive")
        .arg("--expected-hash")
        .arg(expected_hash)
        .arg(&wrong_name_archive)
        .output()
        .expect("muga verify-package-archive explicit hash should run");
    let explicit_hash_stdout = String::from_utf8_lossy(&explicit_hash.stdout);
    let explicit_hash_stderr = String::from_utf8_lossy(&explicit_hash.stderr);
    assert!(explicit_hash.status.success(), "{explicit_hash:#?}");
    assert_eq!(explicit_hash_stderr, "");
    assert!(
        explicit_hash_stdout.contains(&format!("hash\t{expected_hash}")),
        "{explicit_hash_stdout}"
    );

    let explicit_hash_unpacked = workspace.join("explicit-hash-unpacked");
    let unpack_explicit_hash = muga_command()
        .arg("unpack-package-archive")
        .arg("--expected-hash")
        .arg(expected_hash)
        .arg("--output-dir")
        .arg(&explicit_hash_unpacked)
        .arg(&wrong_name_archive)
        .output()
        .expect("muga unpack-package-archive explicit hash should run");
    let unpack_explicit_hash_stdout = String::from_utf8_lossy(&unpack_explicit_hash.stdout);
    let unpack_explicit_hash_stderr = String::from_utf8_lossy(&unpack_explicit_hash.stderr);
    assert!(
        unpack_explicit_hash.status.success(),
        "{unpack_explicit_hash:#?}"
    );
    assert_eq!(unpack_explicit_hash_stderr, "");
    assert!(
        unpack_explicit_hash_stdout.contains("written\t")
            && explicit_hash_unpacked.join("muga.toml").is_file()
            && explicit_hash_unpacked
                .join("resources/static/logo.bin")
                .is_file(),
        "{unpack_explicit_hash_stdout}"
    );

    let explicit_hash_mismatch = muga_command()
        .arg("verify-package-archive")
        .arg("--format")
        .arg("json")
        .arg(format!("--expected-hash=sha256:{}", "0".repeat(64)))
        .arg(&wrong_name_archive)
        .output()
        .expect("muga verify-package-archive explicit mismatch should run");
    let explicit_hash_mismatch_stdout = String::from_utf8_lossy(&explicit_hash_mismatch.stdout);
    let explicit_hash_mismatch_stderr = String::from_utf8_lossy(&explicit_hash_mismatch.stderr);
    assert!(
        !explicit_hash_mismatch.status.success(),
        "{explicit_hash_mismatch:#?}"
    );
    assert_eq!(explicit_hash_mismatch_stderr, "");
    assert!(
        explicit_hash_mismatch_stdout.contains("package archive hash mismatch"),
        "{explicit_hash_mismatch_stdout}"
    );

    let mismatch_unpacked = workspace.join("mismatch-unpacked");
    let unpack_explicit_mismatch = muga_command()
        .arg("unpack-package-archive")
        .arg(format!("--expected-hash=sha256:{}", "0".repeat(64)))
        .arg("--output-dir")
        .arg(&mismatch_unpacked)
        .arg(&wrong_name_archive)
        .output()
        .expect("muga unpack-package-archive explicit mismatch should run");
    let unpack_explicit_mismatch_stderr = String::from_utf8_lossy(&unpack_explicit_mismatch.stderr);
    assert!(
        !unpack_explicit_mismatch.status.success(),
        "{unpack_explicit_mismatch:#?}"
    );
    assert!(
        unpack_explicit_mismatch_stderr.contains("package archive hash mismatch"),
        "{unpack_explicit_mismatch_stderr}"
    );
    assert!(!mismatch_unpacked.exists());

    let mismatch_json_unpacked = workspace.join("mismatch-json-unpacked");
    let unpack_explicit_mismatch_json = muga_command()
        .arg("unpack-package-archive")
        .arg("--format")
        .arg("json")
        .arg(format!("--expected-hash=sha256:{}", "0".repeat(64)))
        .arg("--output-dir")
        .arg(&mismatch_json_unpacked)
        .arg(&wrong_name_archive)
        .output()
        .expect("muga unpack-package-archive JSON explicit mismatch should run");
    let unpack_explicit_mismatch_json_stdout =
        String::from_utf8_lossy(&unpack_explicit_mismatch_json.stdout);
    let unpack_explicit_mismatch_json_stderr =
        String::from_utf8_lossy(&unpack_explicit_mismatch_json.stderr);
    assert!(
        !unpack_explicit_mismatch_json.status.success(),
        "{unpack_explicit_mismatch_json:#?}"
    );
    assert_eq!(unpack_explicit_mismatch_json_stderr, "");
    assert!(
        unpack_explicit_mismatch_json_stdout.contains("\"command\":\"unpack-package-archive\"")
            && unpack_explicit_mismatch_json_stdout.contains("\"status\":\"error\"")
            && unpack_explicit_mismatch_json_stdout.contains("\"outputDir\":{\"path\":\"")
            && unpack_explicit_mismatch_json_stdout.contains("package archive hash mismatch")
            && unpack_explicit_mismatch_json_stdout.contains("packageArchive")
            && unpack_explicit_mismatch_json_stdout.contains("unpack-output"),
        "{unpack_explicit_mismatch_json_stdout}"
    );
    assert!(!mismatch_json_unpacked.exists());

    let invalid_explicit_hash = muga_command()
        .arg("verify-package-archive")
        .arg("--format")
        .arg("json")
        .arg(format!("--expected-hash=sha256:{}", "A".repeat(64)))
        .arg(&wrong_name_archive)
        .output()
        .expect("muga verify-package-archive invalid explicit hash should run");
    let invalid_explicit_hash_stdout = String::from_utf8_lossy(&invalid_explicit_hash.stdout);
    let invalid_explicit_hash_stderr = String::from_utf8_lossy(&invalid_explicit_hash.stderr);
    assert!(
        !invalid_explicit_hash.status.success(),
        "{invalid_explicit_hash:#?}"
    );
    assert_eq!(invalid_explicit_hash_stderr, "");
    assert!(
        invalid_explicit_hash_stdout.contains("\"command\":\"verify-package-archive\"")
            && invalid_explicit_hash_stdout.contains("\"status\":\"error\"")
            && invalid_explicit_hash_stdout.contains("package archive expected hash")
            && invalid_explicit_hash_stdout.contains("must use lower-case hexadecimal"),
        "{invalid_explicit_hash_stdout}"
    );
}

#[test]
fn cli_emit_package_archive_dependency_snippet_drives_local_archive_workflow() {
    let workspace = temp_package_root("cli-archive-dependency-workflow");
    let shared_root = workspace.join("shared");
    write_package_file(
        &shared_root,
        "muga.toml",
        r#"
[package]
name = "company::shared"
source = "src"
"#,
    );
    let shared_entry = write_package_file(
        &shared_root,
        "src/logging/main.muga",
        r#"
pub fn value(): Int {
  41
}
"#,
    );
    let archive_root = workspace.join("archives#quoted\"root");
    let archive_output = muga_command()
        .arg("emit-package-archive")
        .arg("--archive-root")
        .arg(&archive_root)
        .arg("--dependency-snippet")
        .arg(&shared_entry)
        .output()
        .expect("muga command should run");
    let archive_stdout = String::from_utf8_lossy(&archive_output.stdout);
    let archive_stderr = String::from_utf8_lossy(&archive_output.stderr);

    assert!(archive_output.status.success(), "{archive_output:#?}");
    assert_eq!(archive_stderr, "");
    let lines = archive_stdout.lines().collect::<Vec<_>>();
    assert_eq!(lines.len(), 2, "{archive_stdout}");
    assert_eq!(lines[0], "[dependencies]");
    assert!(
        lines[1].starts_with("\"company::shared\" = { archive = \""),
        "{archive_stdout}"
    );
    assert!(
        lines[1].contains("\", hash = \"sha256:"),
        "{archive_stdout}"
    );
    assert!(lines[1].ends_with("\" }"), "{archive_stdout}");

    let app_root = workspace.join("app");
    write_package_file(
        &app_root,
        "muga.toml",
        &format!(
            r#"
[package]
name = "app"
source = "src"

[dependencies]
{}
"#,
            lines[1]
        ),
    );
    let app_entry = write_package_file(
        &app_root,
        "src/main/main.muga",
        r#"
import company::shared::logging as logging

fn main(): Int {
  logging::value() + 1
}
"#,
    );

    let run_output = muga_command()
        .arg(&app_entry)
        .output()
        .expect("muga command should run");
    assert!(run_output.status.success(), "{run_output:#?}");
    assert_eq!(String::from_utf8_lossy(&run_output.stdout), "42\n");
    assert_eq!(String::from_utf8_lossy(&run_output.stderr), "");

    let expected_hash = muga::package_content_hash(&shared_entry)
        .expect("package content hash should compute")
        .expect("manifest package should produce a hash");
    let cache_root =
        archive_dependency_cache_root_for_test(&app_root, "company::shared", &expected_hash);
    assert!(cache_root.join("muga.toml").is_file());
    assert!(cache_root.join("src/logging/main.muga").is_file());

    let build_output = muga_command()
        .arg("build")
        .arg(&app_entry)
        .output()
        .expect("muga command should run");
    assert!(build_output.status.success(), "{build_output:#?}");
    assert_eq!(String::from_utf8_lossy(&build_output.stderr), "");
    let lockfile =
        fs::read_to_string(app_root.join("muga.lock")).expect("lockfile should be written");
    assert!(
        lockfile
            .contains("source = { archive = \"../archives#quoted\\\"root/company__shared-sha256-"),
        "{lockfile}"
    );
    assert!(
        lockfile.contains(&format!("hash = \"{expected_hash}\"")),
        "{lockfile}"
    );
}

