#[test]
fn cli_build_writes_default_project_artifacts() {
    let root = temp_package_root("cli-build-default-artifacts");
    write_package_file(
        &root,
        "muga.toml",
        r#"
[package]
name = "demo"
source = "src"
"#,
    );
    write_package_file(
        &root,
        "src/util/math/main.muga",
        r#"
pub fn value(): Int {
  11
}
"#,
    );
    let entry = write_package_file(
        &root,
        "src/app/main.muga",
        r#"
import demo::util::math as math

fn main(): Int {
  math::value() + 1
}
"#,
    );

    let output = muga_command()
        .arg("build")
        .arg(&entry)
        .output()
        .expect("muga command should run");
    let stdout = String::from_utf8_lossy(&output.stdout);
    let stderr = String::from_utf8_lossy(&output.stderr);
    let artifact_root = root.join(".muga").join("build");

    assert!(output.status.success(), "{output:#?}");
    assert!(
        stdout.lines().all(|line| line.starts_with("written\t")),
        "{stdout}"
    );
    assert!(stdout.contains(".muga/build"), "{stdout}");
    assert!(stdout.contains("demo__app.mgi"), "{stdout}");
    assert!(stdout.contains("demo__util__math.mgi"), "{stdout}");
    assert!(stdout.contains("demo__app.mgb"), "{stdout}");
    assert!(stdout.contains("demo__util__math.mgb"), "{stdout}");
    assert!(stdout.contains("demo__app.mgc"), "{stdout}");
    assert_eq!(stderr, "");
    assert!(
        muga::interface::PackageInterfaceGraph::persisted_file_path(&artifact_root, "demo::app")
            .is_file()
    );
    assert!(
        muga::implementation_artifact::persisted_file_path(&artifact_root, "demo::util::math")
            .is_file()
    );
    assert!(artifact_root.join("demo__app.mgc").is_file());

    let second_build = muga_command()
        .arg("build")
        .arg(&entry)
        .output()
        .expect("muga command should run");
    let second_stdout = String::from_utf8_lossy(&second_build.stdout);
    assert!(second_build.status.success(), "{second_build:#?}");
    assert_eq!(String::from_utf8_lossy(&second_build.stderr), "");
    assert!(
        second_stdout
            .lines()
            .all(|line| line.starts_with("reused\t")),
        "{second_stdout}"
    );
    assert!(second_stdout.contains("demo__app.mgc"), "{second_stdout}");

    let checked = muga_command()
        .arg("check")
        .arg("--artifact-root")
        .arg(&artifact_root)
        .arg(&entry)
        .output()
        .expect("muga command should run");
    assert!(checked.status.success(), "{checked:#?}");
    assert_eq!(String::from_utf8_lossy(&checked.stdout), "ok\n");

    let artifact_run = muga_command()
        .arg("run")
        .arg("--artifact-root")
        .arg(&artifact_root)
        .arg(&entry)
        .output()
        .expect("muga command should run");
    assert!(artifact_run.status.success(), "{artifact_run:#?}");
    assert_eq!(String::from_utf8_lossy(&artifact_run.stdout), "12\n");

    let default_run = muga_command()
        .arg(&entry)
        .output()
        .expect("muga command should run");
    assert!(default_run.status.success(), "{default_run:#?}");
    assert_eq!(String::from_utf8_lossy(&default_run.stdout), "12\n");
}

#[test]
fn cli_build_json_reports_artifact_status_contract() {
    let root = temp_package_root("cli-build-json-artifacts");
    write_package_file(
        &root,
        "muga.toml",
        r#"
[package]
name = "demo"
source = "src"
"#,
    );
    let entry = write_package_file(
        &root,
        "src/app/main.muga",
        r#"
fn main(): Int {
  42
}
"#,
    );
    let artifact_root = root.join(".muga").join("build");

    let output = muga_command()
        .arg("build")
        .arg("--format=json")
        .arg(&entry)
        .output()
        .expect("muga command should run");
    let stdout = String::from_utf8_lossy(&output.stdout);

    assert!(output.status.success(), "{output:#?}");
    assert_eq!(String::from_utf8_lossy(&output.stderr), "");
    assert!(stdout.contains("\"schemaVersion\":1"), "{stdout}");
    assert!(stdout.contains("\"command\":\"build\""), "{stdout}");
    assert!(stdout.contains("\"status\":\"ok\""), "{stdout}");
    assert!(stdout.contains("\"diagnostics\":[]"), "{stdout}");
    assert!(
        stdout.contains(&format!(
            "\"artifactRoot\":{{\"path\":\"{}\",\"uri\":\"file://",
            artifact_root.display()
        )),
        "{stdout}"
    );
    assert!(stdout.contains("\"artifacts\":["), "{stdout}");
    assert!(stdout.contains("\"status\":\"written\""), "{stdout}");
    assert!(
        stdout.contains("\"artifactKind\":\"interface\""),
        "{stdout}"
    );
    assert!(
        stdout.contains("\"artifactKind\":\"implementation\""),
        "{stdout}"
    );
    assert!(
        stdout.contains("\"artifactKind\":\"checkCache\""),
        "{stdout}"
    );
    assert!(stdout.contains("\"path\":\""), "{stdout}");
    assert!(stdout.contains("\"uri\":\"file://"), "{stdout}");
    assert!(stdout.contains("demo__app.mgi"), "{stdout}");
    assert!(stdout.contains("demo__app.mgb"), "{stdout}");
    assert!(stdout.contains("demo__app.mgc"), "{stdout}");

    let second_output = muga_command()
        .arg("build")
        .arg("--format=json")
        .arg(&entry)
        .output()
        .expect("muga command should run");
    let second_stdout = String::from_utf8_lossy(&second_output.stdout);

    assert!(second_output.status.success(), "{second_output:#?}");
    assert_eq!(String::from_utf8_lossy(&second_output.stderr), "");
    assert!(
        second_stdout.contains("\"command\":\"build\""),
        "{second_stdout}"
    );
    assert!(
        second_stdout.contains("\"status\":\"reused\""),
        "{second_stdout}"
    );
    assert!(
        second_stdout.matches("\"status\":\"reused\"").count() >= 3,
        "{second_stdout}"
    );
}

