    assert!(stdout.contains("\"command\":\"why-rebuild\""), "{stdout}");
    assert!(stdout.contains("\"status\":\"ok\""), "{stdout}");
    assert!(stdout.contains("\"diagnostics\":[]"), "{stdout}");
    assert!(
        stdout.contains(&format!(
            "\"artifactRoot\":{{\"path\":\"{}\",\"uri\":\"file://",
            artifact_root.display()
        )),
        "{stdout}"
    );
