    assert!(stdout.contains("\"packages\":["), "{stdout}");
    assert!(stdout.contains("\"role\":\"entry\""), "{stdout}");
    assert!(stdout.contains("\"role\":\"dependency\""), "{stdout}");
    assert!(stdout.contains("\"artifacts\":["), "{stdout}");
    assert!(
        stdout.contains("\"artifactKind\":\"interface\""),
        "{stdout}"
    );
    assert!(
        stdout.contains("\"artifactKind\":\"implementation\""),
        "{stdout}"
    );
    assert!(
        stdout.contains("\"artifactKind\":\"checkCache\""),
        "{stdout}"
    );
    assert!(stdout.contains("\"state\":\"fresh\""), "{stdout}");
