#[test]
fn cli_why_rebuild_json_reports_stale_source_artifacts() {
    let root = temp_package_root("cli-why-rebuild-json-stale");
    write_package_file(
        &root,
        "muga.toml",
        r#"
[package]
name = "demo"
source = "src"
"#,
    );
    let entry = write_package_file(
        &root,
        "src/app/main.muga",
        r#"
fn main(): Int {
  1
}
"#,
    );

    let build = muga_command()
        .arg("build")
        .arg(&entry)
        .output()
        .expect("muga command should run");
    assert!(build.status.success(), "{build:#?}");

    fs::write(
        &entry,
        r#"
package demo::app

fn main(): Int {
  2
}
"#
        .trim_start(),
    )
    .expect("entry source should be updated");

    let output = muga_command()
        .arg("why-rebuild")
        .arg("--format=json")
        .arg("--built")
        .arg(&entry)
        .output()
        .expect("muga command should run");
    let stdout = String::from_utf8_lossy(&output.stdout);

    assert!(output.status.success(), "{output:#?}");
    assert_eq!(String::from_utf8_lossy(&output.stderr), "");
    assert!(stdout.contains("\"command\":\"why-rebuild\""), "{stdout}");
    assert!(stdout.contains("\"status\":\"ok\""), "{stdout}");
    assert!(stdout.contains("\"state\":\"stale\""), "{stdout}");
    assert!(stdout.contains("source hash changed"), "{stdout}");
    assert!(stdout.contains("entry package source changed"), "{stdout}");
    assert!(stdout.contains("\"hashKind\":\"source\""), "{stdout}");
    assert!(stdout.contains("demo__app.mgb"), "{stdout}");
    assert!(stdout.contains("demo__app.mgc"), "{stdout}");
    assert!(stdout.contains("\"role\":\"expected\""), "{stdout}");
    assert!(stdout.contains("\"role\":\"actual\""), "{stdout}");
}

