    assert!(stdout.contains("\"command\":\"why-rebuild\""), "{stdout}");
    assert!(stdout.contains("\"kind\":\"lockfile\""), "{stdout}");
    assert!(stdout.contains("\"state\":\"fresh\""), "{stdout}");
