#[test]
fn cli_why_rebuild_json_reports_invalid_and_hash_mismatched_artifacts() {
    let root = temp_package_root("cli-why-rebuild-json-invalid");
    write_package_file(
        &root,
        "muga.toml",
        r#"
[package]
name = "demo"
source = "src"
"#,
    );
    let entry = write_package_file(
        &root,
        "src/app/main.muga",
        r#"
fn main(): Int {
  42
}
"#,
    );
    let artifact_root = root.join(".muga").join("build");

    let build = muga_command()
        .arg("build")
        .arg(&entry)
        .output()
        .expect("muga command should run");
    assert!(build.status.success(), "{build:#?}");

    fs::write(
        artifact_root.join("demo__app.mgb"),
        "not a package implementation artifact\n",
    )
    .expect("implementation artifact should be tampered");
    let check_cache = artifact_root.join("demo__app.mgc");
    let check_cache_text =
        fs::read_to_string(&check_cache).expect("check cache artifact should exist");
    let mut check_cache_lines = check_cache_text.lines().collect::<Vec<_>>();
    check_cache_lines[1] = "hash\tbad";
    fs::write(&check_cache, format!("{}\n", check_cache_lines.join("\n")))
        .expect("check cache artifact should be tampered");

    let output = muga_command()
        .arg("why-rebuild")
        .arg("--format=json")
        .arg("--built")
        .arg(&entry)
        .output()
        .expect("muga command should run");
    let stdout = String::from_utf8_lossy(&output.stdout);

    assert!(output.status.success(), "{output:#?}");
    assert_eq!(String::from_utf8_lossy(&output.stderr), "");
    assert!(stdout.contains("\"command\":\"why-rebuild\""), "{stdout}");
    assert!(stdout.contains("\"status\":\"ok\""), "{stdout}");
    assert!(stdout.contains("\"state\":\"invalid\""), "{stdout}");
    assert!(stdout.contains("\"state\":\"hashMismatch\""), "{stdout}");
    assert!(
        stdout.contains("invalid package implementation artifact header"),
        "{stdout}"
    );
    assert!(
        stdout.contains("package check cache artifact hash mismatch"),
        "{stdout}"
    );
    assert!(stdout.contains("demo__app.mgb"), "{stdout}");
    assert!(stdout.contains("demo__app.mgc"), "{stdout}");
    assert!(stdout.contains("\"hashKind\":\"artifact\""), "{stdout}");
    assert!(
        stdout.contains("muga emit-check-cache --artifact-root <dir> <entry>"),
        "{stdout}"
    );
}

#[test]
fn cli_check_built_uses_default_project_artifacts_without_dependency_source_body() {
    let root = temp_package_root("cli-check-built-artifacts");
    write_package_file(
        &root,
        "muga.toml",
        r#"
[package]
name = "demo"
source = "src"
"#,
    );
    let dependency = write_package_file(
        &root,
        "src/util/math/main.muga",
        r#"
pub fn value(): Int {
  11
}
"#,
    );
    let entry = write_package_file(
        &root,
        "src/app/main.muga",
        r#"
import demo::util::math as math

fn main(): Int {
  math::value() + 1
}
"#,
    );

    let built = muga_command()
        .arg("build")
        .arg(&entry)
        .output()
        .expect("muga command should run");
    assert!(built.status.success(), "{built:#?}");
    fs::write(
        &dependency,
        r#"
pub fn value(): Int {
  @
}
"#,
    )
    .expect("dependency source should be overwritten");

    let checked = muga_command()
        .arg("check")
        .arg("--built")
        .arg(&entry)
        .output()
        .expect("muga command should run");
    assert!(checked.status.success(), "{checked:#?}");
    assert_eq!(String::from_utf8_lossy(&checked.stdout), "ok\n");
    assert_eq!(String::from_utf8_lossy(&checked.stderr), "");

    let source_check = muga_command()
        .arg("check")
        .arg(&entry)
        .output()
        .expect("muga command should run");
    assert!(!source_check.status.success(), "{source_check:#?}");
}

