#[test]
fn cli_run_built_preserves_json_validation_metadata() {
    let root = temp_package_root("cli-run-built-json-validation");
    write_package_file(
        &root,
        "muga.toml",
        r#"
[package]
name = "demo"
source = "src"
"#,
    );
    let entry = write_package_file(
        &root,
        "src/app/main.muga",
        r#"
import std::json

record Settings {
  @validate(min: 1)
  port: Int
}

fn message(value: Result[Settings, json::Error]): String {
  match value {
    Result::Ok(_) => "ok"
    Result::Err(error) => error.message
  }
}

fn main(): Result[String, json::Error] {
  value = try json::parse("{\"port\":0}")
  Result::Ok(message(json::decode(value)))
}
"#,
    );

    let built = muga_command()
        .arg("build")
        .arg(&entry)
        .output()
        .expect("muga command should run");
    assert!(built.status.success(), "{built:#?}");

    let built_run = muga_command()
        .arg("run")
        .arg("--built")
        .arg(&entry)
        .output()
        .expect("muga command should run");
    assert!(built_run.status.success(), "{built_run:#?}");
    assert_eq!(
        String::from_utf8_lossy(&built_run.stdout),
        "Result::Ok(validation failed at path .port: expected Int >= 1)\n"
    );
    assert_eq!(String::from_utf8_lossy(&built_run.stderr), "");
}

