#[test]
fn artifact_run_covers_representative_dependency_api_without_source() {
    let provider_root = temp_package_root("representative-api-artifact-provider");
    write_package_file(
        &provider_root,
        "model/score/main.muga",
        r#"
package model::score

pub record Score {
  label: String,
  points: Int
}

pub enum Stage[T] {
  Ready(T)
  Failed(String)
}

pub record Envelope[T] {
  stage: Stage[T]
}

pub fn ready[T](value: T): Stage[T] {
  Stage::Ready(value)
}

pub fn failed[T](message: String): Stage[T] {
  Stage::Failed(message)
}

pub fn wrap[T](stage: Stage[T]): Envelope[T] {
  Envelope {
    stage: stage
  }
}
"#,
    );
    write_package_file(
        &provider_root,
        "util/parse/main.muga",
        r#"
package util::parse

import model::score
import std::path

pub fn parse_score(name_text: String, raw_text: String): Result[score::Envelope[score::Score], String] {
  file_path = path::from_string(name_text)
  label = match path::file_stem(file_path) {
    Option::Some(value) => value
    Option::None => "score"
  }
  points = try raw_text.trim().parse_int()
  value = score::Score {
    label: label,
    points: points
  }
  Result::Ok(score::wrap(score::ready(value)))
}
"#,
    );
    write_package_file(
        &provider_root,
        "api/reports/main.muga",
        r#"
package api::reports

import model::score
import util::parse

fn describe(envelope: score::Envelope[score::Score]): String {
  match envelope.stage {
    score::Stage::Ready(value) => value.label.concat(":").concat(value.points.to_string())
    score::Stage::Failed(message) => message
  }
}

pub fn summarize(name_text: String, raw_text: String): String {
  parsed = parse::parse_score(name_text, raw_text)
  match parsed {
    Result::Ok(envelope) => describe(envelope)
    Result::Err(message) => "error:".concat(message)
  }
}
"#,
    );
    let provider_entry = write_package_file(
        &provider_root,
        "app/provider/main.muga",
        r#"
package app::provider

import api::reports

fn main(): String {
  reports::summarize("daily.muga", " 42 ")
}
"#,
    );
    let artifact_root = temp_package_root("representative-api-artifact-root");
    let written = muga::write_package_artifacts(&provider_entry, &artifact_root)
        .expect("provider artifacts should be written");
    for expected in [
        "api__reports.mgb",
        "util__parse.mgb",
        "model__score.mgb",
        "std__path.mgb",
    ] {
        assert!(
            written
                .iter()
                .any(|path| path.file_name().is_some_and(|name| name == expected)),
            "{written:#?}"
        );
    }

    let consumer_root = temp_package_root("representative-api-artifact-consumer");
    let consumer_entry = write_package_file(
        &consumer_root,
        "app/consumer/main.muga",
        r#"
package app::consumer

import api::reports

fn main(): String {
  reports::summarize("daily.muga", " 42 ")
}
"#,
    );
    assert!(!consumer_root.join("api/reports/main.muga").exists());
    assert!(!consumer_root.join("util/parse/main.muga").exists());
    assert!(!consumer_root.join("model/score/main.muga").exists());
    muga::write_package_check_cache_artifact_for_root(&consumer_entry, &artifact_root)
        .expect("consumer check cache should be written against interface artifacts");

    let result = muga::run_path_against_artifact_root(&consumer_entry, &artifact_root)
        .expect("consumer should run representative dependency API from artifacts");
    let value = result.main_result.expect("main result should exist");
    assert_eq!(value.to_string(), "daily:42");
    assert_eq!(result.output_text, "");
}

