#[test]
fn runtime_errors_include_call_context_related_notes() {
    let source = r#"
fn explode(): Int {
  1 / 0
}

fn wrapper(): Int {
  explode()
}

fn main(): Int {
  wrapper()
}
"#;
    let diagnostics = muga::run_source(source).expect_err("expected runtime error");
    let diagnostic = diagnostics
        .iter()
        .find(|diagnostic| diagnostic.code == "R013")
        .expect("division diagnostic should exist");

    assert!(
        diagnostic
            .related
            .iter()
            .any(|note| note.message == "called `explode` here"),
        "{diagnostics:#?}"
    );
    assert!(
        diagnostic
            .related
            .iter()
            .any(|note| note.message == "called `wrapper` here"),
        "{diagnostics:#?}"
    );
    assert!(
        diagnostic
            .related
            .iter()
            .any(|note| note.message == "while running `main`"),
        "{diagnostics:#?}"
    );
    let text = diagnostic.to_string();
    assert!(
        text.contains("note:") && text.contains("called `explode` here"),
        "{text}"
    );
}

