#[test]
fn for_loop_artifact_run_uses_emitted_dependency_implementation() {
    let provider_root = temp_package_root("for-artifact-provider");
    write_package_file(
        &provider_root,
        "util/loops/main.muga",
        r#"
package util::loops

pub fn sum(items: List[Int]): Int {
  mut total = 0
  for item in items {
    total = total + item
  }
  total
}
"#,
    );
    let provider_entry = write_package_file(
        &provider_root,
        "app/provider/main.muga",
        r#"
package app::provider

import util::loops

fn main(): Int {
  loops::sum([1, 2, 3])
}
"#,
    );
    let artifact_root = temp_package_root("for-artifact-root");
    muga::write_package_artifacts(&provider_entry, &artifact_root)
        .expect("provider artifacts should be written");

    let consumer_root = temp_package_root("for-artifact-consumer");
    let consumer_entry = write_package_file(
        &consumer_root,
        "app/consumer/main.muga",
        r#"
package app::consumer

import util::loops

fn main(): Int {
  loops::sum([1, 2, 3, 4])
}
"#,
    );
    assert!(!consumer_root.join("util/loops/main.muga").exists());
    muga::write_package_check_cache_artifact_for_root(&consumer_entry, &artifact_root)
        .expect("consumer check cache should be written against interface artifact");

    let result = muga::run_path_against_artifact_root(&consumer_entry, &artifact_root)
        .expect("consumer should run dependency for-loop implementation artifact");
    let value = result.main_result.expect("main result should exist");
    assert_eq!(value.to_string(), "10");
}

