#[test]
fn structural_equality_is_rejected_by_current_policy() {
    let source = r#"
record Point {
  x: Int
}

enum Choice {
  Left(Int)
  Right
}

fn record_eq(left: Point, right: Point): Bool {
  left == right
}

fn enum_eq(left: Choice, right: Choice): Bool {
  left == right
}

fn list_eq(left: List[Int], right: List[Int]): Bool {
  left == right
}

fn map_eq(left: Map[String, Int], right: Map[String, Int]): Bool {
  left == right
}

fn option_eq(left: Option[Int], right: Option[Int]): Bool {
  left == right
}

fn result_eq(left: Result[Int, String], right: Result[Int, String]): Bool {
  left == right
}

fn main(): Int {
  0
}
"#;
    let diagnostics = muga::check_source(source).expect_err("structural equality must be rejected");
    let equality_errors = diagnostics
        .iter()
        .filter(|diagnostic| diagnostic.code == "T003")
        .count();
    assert_eq!(equality_errors, 6, "{diagnostics:#?}");
    assert!(
        diagnostics
            .iter()
            .all(|diagnostic| diagnostic.code == "T003"),
        "structural equality rejection should not need secondary diagnostics: {diagnostics:#?}"
    );
}

