#[test]
fn direct_recursion_requires_actionable_annotation_suggestion() {
    let source = r#"
fn fact(n) {
  if n == 0 {
    1
  } else {
    n * fact(n - 1)
  }
}
"#;
    let diagnostics = muga::check_source(source).expect_err("expected recursive annotation error");
    let diagnostic = diagnostics
        .iter()
        .find(|diagnostic| {
            diagnostic.code == "E006"
                && diagnostic.suggestions.iter().any(|suggestion| {
                    suggestion.message.contains("parameter type annotation")
                        && suggestion.message.contains("return type")
                        && suggestion.message.contains("recursive function")
                })
        })
        .expect("direct recursion diagnostic should include annotation guidance");

    assert_eq!(diagnostic.span.start.line, 2, "{diagnostic:#?}");
}

#[test]
fn mutual_recursion_requires_actionable_signature_suggestion() {
    let source = r#"
fn is_even(n) {
  if n == 0 {
    true
  } else {
    is_odd(n - 1)
  }
}

fn is_odd(n) {
  if n == 0 {
    false
  } else {
    is_even(n - 1)
  }
}
"#;
    let diagnostics =
        muga::check_source(source).expect_err("expected mutual recursion signature error");
    let recursive_diagnostics = diagnostics
        .iter()
        .filter(|diagnostic| diagnostic.code == "E007")
        .collect::<Vec<_>>();
    assert_eq!(recursive_diagnostics.len(), 2, "{diagnostics:#?}");
    assert!(
        recursive_diagnostics.iter().all(|diagnostic| {
            diagnostic.suggestions.iter().any(|suggestion| {
                suggestion.message.contains("parameter type annotations")
                    && suggestion.message.contains("explicit return type")
                    && suggestion.message.contains("mutually recursive group")
            })
        }),
        "{diagnostics:#?}"
    );
}

