#[test]
fn standard_cli_parse_required_record_runs() {
    let root = temp_package_root("std-cli-parse-required-record");
    let entry = write_package_file(
        &root,
        "app/std_cli_parse_required_record/main.muga",
        r#"
package app::std_cli_parse_required_record

import std::cli

pub enum Mode {
  Serve
  Batch
}

pub record Settings {
  @cli(name: "host", alias: "server-host")
  @validate(non_empty)
  name: String
  @validate(min: 1, max: 65535)
  port: Int
  enabled: Bool
  label: Option[String]
  tags: List[String]
  mode: Mode
  optional_mode: Option[Mode]
  modes: List[Mode]
  @cli(hidden)
  token: Option[String]
}

fn mode_text(value: Mode): String {
  match value {
    Mode::Serve => "Serve"
    Mode::Batch => "Batch"
  }
}

fn option_string_text(value: Option[String]): String {
  match value {
    Option::Some(text) => text
    Option::None => "none"
  }
}

fn option_mode_text(value: Option[Mode]): String {
  match value {
    Option::Some(mode) => mode_text(mode)
    Option::None => "none"
  }
}

fn main(): Result[String, cli::Error] {
  args = ["--server-host", "api", "--port=8080", "--enabled", "--label", "blue", "--tags", "edge", "--tags=ops", "--mode", "Batch", "--optional_mode", "Serve", "--modes", "Serve", "--modes=Batch", "--token", "secret"]
  settings: Settings = try cli::parse(args)
  mut text = settings.name.concat("|").concat(settings.port.to_string())
  text = text.concat("|").concat(settings.enabled.to_string())
  text = text.concat("|").concat(option_string_text(settings.label))
  text = text.concat("|").concat(settings.tags.len().to_string()).concat("|").concat(settings.tags[0]).concat("|").concat(settings.tags[1])
  text = text.concat("|").concat(mode_text(settings.mode))
  text = text.concat("|").concat(option_mode_text(settings.optional_mode))
  text = text.concat("|").concat(settings.modes.len().to_string()).concat("|").concat(mode_text(settings.modes[0])).concat("|").concat(mode_text(settings.modes[1]))
  text = text.concat("|").concat(option_string_text(settings.token))
  Result::Ok(text)
}
"#,
    );

    let result = muga::run_path(&entry).expect("std::cli parse program should run");
    let value = result.main_result.expect("main result should exist");
    assert_eq!(
        value.to_string(),
        "Result::Ok(api|8080|true|blue|2|edge|ops|Batch|Serve|2|Serve|Batch|secret)"
    );
}

#[test]
fn standard_cli_parse_reports_required_and_synthesized_absent_values() {
    let root = temp_package_root("std-cli-parse-errors");
    let entry = write_package_file(
        &root,
        "app/std_cli_parse_errors/main.muga",
        r#"
package app::std_cli_parse_errors

import std::cli

pub record Settings {
  name: String
  enabled: Bool
  label: Option[String]
  tags: List[String]
}

fn option_text(value: Option[String]): String {
  match value {
    Option::Some(text) => text
    Option::None => "none"
  }
}

fn kind_name(kind: cli::ErrorKind): String {
  match kind {
    cli::ErrorKind::UnknownArgument => "UnknownArgument"
    cli::ErrorKind::MissingArgument => "MissingArgument"
    cli::ErrorKind::MissingValue => "MissingValue"
    cli::ErrorKind::InvalidValue => "InvalidValue"
    cli::ErrorKind::Validation => "Validation"
    cli::ErrorKind::UnsupportedTarget => "UnsupportedTarget"
  }
}

fn describe(args: List[String]): String {
  parsed: Result[Settings, cli::Error] = cli::parse(args)
  match parsed {
    Result::Ok(settings) => settings.name.concat("|").concat(settings.enabled.to_string()).concat("|").concat(option_text(settings.label)).concat("|").concat(settings.tags.len().to_string())
    Result::Err(error) => kind_name(error.kind).concat(":").concat(error.argument).concat(":").concat(error.message)
  }
}

fn main(): String {
  describe(["--name", "app"]).concat("|").concat(describe([])).concat("|").concat(describe(["--name"]))
}
"#,
    );

    let result = muga::run_path(&entry).expect("std::cli parse error program should run");
    let value = result.main_result.expect("main result should exist");
    let text = value.to_string();
    assert!(text.contains("app|false|none|0"), "{text}");
    assert!(text.contains("MissingArgument:--name"), "{text}");
    assert!(text.contains("MissingValue:--name"), "{text}");
}

