#[test]
fn standard_cli_parse_or_record_overlay_runs() {
    let root = temp_package_root("std-cli-parse-or-record");
    let entry = write_package_file(
        &root,
        "app/std_cli_parse_or_record/main.muga",
        r#"
package app::std_cli_parse_or_record

import std::cli

pub enum Mode {
  Serve
  Batch
}

pub record Owner {
  name: String
}

pub record Settings {
  @json(rename: "host")
  @validate(non_empty)
  name: String
  @validate(min: 1, max: 65535)
  port: Int
  enabled: Bool
  label: Option[String]
  tags: List[String]
  mode: Mode
  owner: Owner
}

fn label_text(value: Option[String]): String {
  match value {
    Option::Some(text) => text
    Option::None => "none"
  }
}

fn mode_text(value: Mode): String {
  match value {
    Mode::Serve => "Serve"
    Mode::Batch => "Batch"
  }
}

fn main(): String {
  defaults = Settings {
    name: "127.0.0.1"
    port: 3000
    enabled: false
    label: Option::None
    tags: ["default"]
    mode: Mode::Serve
    owner: Owner { name: "root" }
  }
  args = ["--host", "localhost", "--port=8080", "--enabled", "--label", "blue", "--tags", "api", "--tags=web", "--mode", "Batch"]
  match cli::parse_or(args, defaults) {
    Result::Ok(settings) => settings.name.concat("|").concat(settings.port.to_string()).concat("|").concat(settings.enabled.to_string()).concat("|").concat(label_text(settings.label)).concat("|").concat(settings.tags.len().to_string()).concat("|").concat(settings.tags[0]).concat("|").concat(settings.tags[1]).concat("|").concat(mode_text(settings.mode)).concat("|").concat(settings.owner.name)
    Result::Err(error) => error.message
  }
}
"#,
    );

    let result = muga::run_path(&entry).expect("std::cli parse_or program should run");
    let value = result.main_result.expect("main result should exist");
    assert_eq!(
        value.to_string(),
        "localhost|8080|true|blue|2|api|web|Batch|root"
    );
}

#[test]
fn standard_cli_parse_or_reports_recoverable_errors() {
    let root = temp_package_root("std-cli-parse-or-errors");
    let entry = write_package_file(
        &root,
        "app/std_cli_parse_or_errors/main.muga",
        r#"
package app::std_cli_parse_or_errors

import std::cli

pub record Settings {
  @validate(non_empty)
  name: String
  @validate(min: 1)
  port: Int
}

fn defaults(): Settings {
  Settings { name: "app", port: 1 }
}

fn kind_name(kind: cli::ErrorKind): String {
  match kind {
    cli::ErrorKind::UnknownArgument => "UnknownArgument"
    cli::ErrorKind::MissingArgument => "MissingArgument"
    cli::ErrorKind::MissingValue => "MissingValue"
    cli::ErrorKind::InvalidValue => "InvalidValue"
    cli::ErrorKind::Validation => "Validation"
    cli::ErrorKind::UnsupportedTarget => "UnsupportedTarget"
  }
}

fn describe(args: List[String]): String {
  match cli::parse_or(args, defaults()) {
    Result::Ok(settings) => settings.name
    Result::Err(error) => kind_name(error.kind).concat(":").concat(error.argument).concat(":").concat(error.message)
  }
}

fn main(): String {
  describe(["--unknown"]).concat("|").concat(describe(["--name"])).concat("|").concat(describe(["--port", "nope"])).concat("|").concat(describe(["--name", ""]))
}
"#,
    );

    let result = muga::run_path(&entry).expect("std::cli parse_or error program should run");
    let value = result.main_result.expect("main result should exist");
    let text = value.to_string();
    assert!(text.contains("UnknownArgument:--unknown"), "{text}");
    assert!(text.contains("MissingValue:--name"), "{text}");
    assert!(text.contains("InvalidValue:--port"), "{text}");
    assert!(text.contains("Validation:--name"), "{text}");
}

