#[test]
fn standard_cli_parse_request_required_record_runs() {
    let root = temp_package_root("std-cli-parse-request-required");
    let entry = write_package_file(
        &root,
        "app/std_cli_parse_request_required/main.muga",
        r#"
package app::std_cli_parse_request_required

import std::cli
import std::string

@cli(about: "Run a command")
pub record Command {
  @cli(positional: 1, help: "Target name")
  target: String
  @cli(short: "c", help: "Item count")
  count: Int
  @cli(name: "dry-run", help: "Preview changes")
  dry_run: Bool
  @cli(name: "tag", help: "Tag filter")
  tags: List[String]
}

fn render(command: Command): String {
  string::join([command.target, command.count.to_string(), command.dry_run.to_string(), command.tags.len().to_string(), command.tags[0], command.tags[1]], "|")
}

fn describe(args: List[String]): String {
  match cli::parse_request[Command](args, "app") {
    Result::Ok(request) => match request {
      cli::Request::Help(help) => "help:".concat(help)
      cli::Request::Parsed(command) => "parsed:".concat(render(command))
    }
    Result::Err(error) => "err:".concat(error.argument).concat(":").concat(error.message)
  }
}

fn main(): String {
  string::join([
    describe(["--help", "--unknown"]),
    describe(["service", "--count=2", "--dry-run", "--tag", "ops", "--tag=prod"]),
    describe(["--", "--help", "--count", "2"])
  ], "\n---\n")
}
"#,
    );

    let result = muga::run_path(&entry).expect("std::cli parse_request program should run");
    let value = result.main_result.expect("main result should exist");
    let text = value.to_string();
    assert!(
        text.contains("help:Usage: app [options] <target>"),
        "{text}"
    );
    assert!(text.contains("Run a command"), "{text}");
    assert!(text.contains("-h, --help  Show this help"), "{text}");
    assert!(text.contains("parsed:service|2|true|2|ops|prod"), "{text}");
    assert!(text.contains("err:--count"), "{text}");
    assert!(!text.contains("unknown CLI option `--unknown`"), "{text}");
}

