#[test]
fn standard_cli_parse_request_rejects_invalid_contracts() {
    let root = temp_package_root("std-cli-parse-request-invalid");
    let missing_type_entry = write_package_file(
        &root,
        "app/std_cli_parse_request_missing_type/main.muga",
        r#"
package app::std_cli_parse_request_missing_type

import std::cli

pub record Command {
  target: String
}

fn main(): Result[cli::Request[Command], cli::Error] {
  cli::parse_request([], "app")
}
"#,
    );
    let diagnostics = muga::check_path(&missing_type_entry)
        .expect_err("missing parse_request type anchor should be rejected");
    assert!(
        diagnostics.iter().any(|diagnostic| {
            diagnostic.code == "T004"
                && diagnostic.message.contains(
                    "`cli::parse_request` requires exactly 1 explicit record type argument",
                )
        }),
        "{diagnostics:#?}"
    );

    let short_conflict_entry = write_package_file(
        &root,
        "app/std_cli_parse_request_or_short_conflict/main.muga",
        r#"
package app::std_cli_parse_request_or_short_conflict

import std::cli

pub record Settings {
  @cli(short: "h")
  host: String
}

fn defaults(): Settings {
  Settings { host: "api" }
}

fn main(): Result[cli::Request[Settings], cli::Error] {
  cli::parse_request_or([], "app", defaults())
}
"#,
    );
    let diagnostics = muga::check_path(&short_conflict_entry)
        .expect_err("parse_request_or help short conflict should be rejected");
    assert!(
        diagnostics.iter().any(|diagnostic| {
            diagnostic.code == "T006"
                && diagnostic
                    .message
                    .contains("`cli::parse_request_or` reserves `--help` and `-h`")
                && diagnostic.message.contains("field `host`")
                && diagnostic.message.contains("@cli(short: \"h\")")
        }),
        "{diagnostics:#?}"
    );
}

