#[test]
fn standard_cli_field_metadata_parse_and_usage_runs() {
    let root = temp_package_root("std-cli-field-metadata");
    let entry = write_package_file(
        &root,
        "app/std_cli_field_metadata/main.muga",
        r#"
package app::std_cli_field_metadata

import std::cli
import std::string

pub record Settings {
  @json(rename: "server_host", alias: "legacy_host")
  @cli(name: "host", alias: "server-host", help: "Server host name")
  @validate(non_empty)
  name: String

  @cli(name: "tag", alias: "tags", help: "Filter tag")
  tags: List[String]

  @cli(hidden)
  debug_token: Option[String]
}

fn token_text(value: Option[String]): String {
  match value {
    Option::Some(text) => text
    Option::None => "none"
  }
}

fn defaults(): Settings {
  Settings {
    name: "localhost"
    tags: ["default"]
    debug_token: Option::None
  }
}

fn parsed_text(): String {
  args = ["--server-host", "api", "--tag", "blue", "--tags=green", "--debug_token", "secret"]
  match cli::parse_or(args, defaults()) {
    Result::Ok(settings) => string::join([
      settings.name,
      settings.tags.len().to_string(),
      settings.tags[0],
      settings.tags[1],
      token_text(settings.debug_token)
    ], "|")
    Result::Err(error) => error.message
  }
}

fn legacy_json_alias_result(): String {
  match cli::parse_or(["--legacy_host", "api"], defaults()) {
    Result::Ok(settings) => settings.name
    Result::Err(error) => error.argument
  }
}

fn main(): String {
  string::join([
    parsed_text(),
    legacy_json_alias_result(),
    cli::usage_for("app", defaults())
  ], "\n---\n")
}
"#,
    );

    let result = muga::run_path(&entry).expect("std::cli field metadata program should run");
    let value = result.main_result.expect("main result should exist");
    let text = value.to_string();
    assert!(text.contains("api|2|blue|green|secret"), "{text}");
    assert!(text.contains("--legacy_host"), "{text}");
    assert!(text.contains("--host <String>"), "{text}");
    assert!(text.contains("aliases: --server-host"), "{text}");
    assert!(text.contains("default: \"localhost\""), "{text}");
    assert!(text.contains("Server host name"), "{text}");
    assert!(text.contains("--tag <String>  repeatable"), "{text}");
    assert!(text.contains("aliases: --tags"), "{text}");
    assert!(text.contains("Filter tag"), "{text}");
    assert!(!text.contains("--debug_token"), "{text}");
    assert!(!text.contains("legacy_host <String>"), "{text}");
}

#[test]
fn standard_cli_short_option_metadata_parse_and_usage_runs() {
    let root = temp_package_root("std-cli-short-option-metadata");
    let entry = write_package_file(
        &root,
        "app/std_cli_short_option_metadata/main.muga",
        r#"
package app::std_cli_short_option_metadata

import std::cli
import std::string

pub enum Mode {
  Serve
  Batch
}

pub record Settings {
  @cli(name: "host", short: "H", alias: "server-host", help: "Server host name")
  @validate(non_empty)
  host: String

  @cli(short: "p", help: "HTTP port")
  @validate(min: 1, max: 65535)
  port: Int

  @cli(name: "dry-run", short: "d", help: "Preview changes")
  dry_run: Bool

  @cli(name: "tag", short: "t", alias: "tags", help: "Filter tag")
  tags: List[String]

  @cli(short: "m", help: "Run mode")
  mode: Mode

  @cli(short: "o", help: "Optional owner")
  owner: Option[String]

  @cli(short: "s", hidden)
  token: Option[String]
}

fn mode_text(value: Mode): String {
  match value {
    Mode::Serve => "Serve"
    Mode::Batch => "Batch"
  }
}

fn option_text(value: Option[String]): String {
  match value {
    Option::Some(text) => text
    Option::None => "none"
  }
}

fn defaults(): Settings {
  Settings {
    host: "localhost"
    port: 3000
    dry_run: false
    tags: []
    mode: Mode::Serve
    owner: Option::None
    token: Option::None
  }
}

fn kind_text(kind: cli::ErrorKind): String {
  match kind {
    cli::ErrorKind::UnknownArgument => "UnknownArgument"
    cli::ErrorKind::MissingArgument => "MissingArgument"
    cli::ErrorKind::MissingValue => "MissingValue"
    cli::ErrorKind::InvalidValue => "InvalidValue"
    cli::ErrorKind::Validation => "Validation"
    cli::ErrorKind::UnsupportedTarget => "UnsupportedTarget"
  }
}

fn parsed_text(args: List[String]): String {
  match cli::parse_or(args, defaults()) {
    Result::Ok(settings) => string::join([
      settings.host,
      settings.port.to_string(),
      settings.dry_run.to_string(),
      settings.tags.len().to_string(),
      settings.tags[0],
      settings.tags[1],
      mode_text(settings.mode),
      option_text(settings.owner),
      option_text(settings.token)
    ], "|")
    Result::Err(error) => kind_text(error.kind).concat(":").concat(error.argument)
  }
}

fn error_text(args: List[String]): String {
  match cli::parse_or(args, defaults()) {
    Result::Ok(settings) => settings.host
    Result::Err(error) => kind_text(error.kind).concat(":").concat(error.argument)
  }
}

fn main(): String {
  parsed = parsed_text(["-H", "api", "-p=8080", "-d", "-t", "edge", "-t=ops", "-m", "Batch", "-o", "Kai", "-s", "secret"])
  dash_value = parsed_text(["-H=-literal", "-p=1", "-t=x", "-t=y", "-m=Serve"])
  usage = cli::usage_for("app", defaults())
  required_usage = cli::usage_for_required[Settings]("app")
  short_help = cli::has_short_flag(["-h", "--", "-x"], "h").to_string()
  stopped_help = cli::has_short_flag(["--", "-h"], "h").to_string()
  missing = error_text(["-H", "-p", "8080"])
  unknown = error_text(["-x"])
  string::join([parsed, dash_value, usage, required_usage, short_help, stopped_help, missing, unknown], "\n---\n")
}
"#,
    );

    let result = muga::run_path(&entry).expect("std::cli short option program should run");
    let value = result.main_result.expect("main result should exist");
    let text = value.to_string();
    assert!(
        text.contains("api|8080|true|2|edge|ops|Batch|Kai|secret"),
        "{text}"
    );
    assert!(
        text.contains("-literal|1|false|2|x|y|Serve|none|none"),
        "{text}"
    );
    assert!(text.contains("-H, --host <String>"), "{text}");
    assert!(text.contains("aliases: --server-host"), "{text}");
    assert!(text.contains("-p, --port <Int>"), "{text}");
    assert!(text.contains("-d, --dry-run[=<Bool>]"), "{text}");
    assert!(text.contains("-t, --tag <String>  repeatable"), "{text}");
    assert!(text.contains("-m, --mode <Serve|Batch>"), "{text}");
    assert!(text.contains("-m, --mode <Mode>"), "{text}");
    assert!(text.contains("-o, --owner <String>"), "{text}");
    assert!(!text.contains("-s, --token"), "{text}");
    assert!(text.contains("true\n---\nfalse"), "{text}");
    assert!(text.contains("MissingValue:-H"), "{text}");
    assert!(text.contains("UnknownArgument:-x"), "{text}");
}

#[test]
fn standard_cli_compact_short_option_syntax_runs() {
    let root = temp_package_root("std-cli-compact-short-option-syntax");
    let entry = write_package_file(
        &root,
        "app/std_cli_compact_short_option_syntax/main.muga",
        r#"
package app::std_cli_compact_short_option_syntax

import std::cli
import std::string

pub record Command {
  @cli(short: "a")
  alpha: Bool

  @cli(short: "b")
  beta: Bool

  @cli(short: "v")
  verbose: List[Bool]

  @cli(short: "n")
  count: Int

  @cli(short: "o")
  output: String

  @cli(short: "d")
  debug: Option[Bool]

  @cli(positional: 1)
  target: String
}

fn kind_text(kind: cli::ErrorKind): String {
  match kind {
    cli::ErrorKind::UnknownArgument => "UnknownArgument"
    cli::ErrorKind::MissingArgument => "MissingArgument"
    cli::ErrorKind::MissingValue => "MissingValue"
    cli::ErrorKind::InvalidValue => "InvalidValue"
    cli::ErrorKind::Validation => "Validation"
    cli::ErrorKind::UnsupportedTarget => "UnsupportedTarget"
  }
}

fn option_bool_text(value: Option[Bool]): String {
  match value {
    Option::Some(flag) => flag.to_string()
    Option::None => "none"
  }
}

fn render(command: Command): String {
  string::join([
    command.alpha.to_string(),
    command.beta.to_string(),
    command.count.to_string(),
    command.output,
    command.verbose.len().to_string(),
    option_bool_text(command.debug),
    command.target
  ], "|")
}

fn request_text(args: List[String]): String {
  match cli::parse_request[Command](args, "compact") {
    Result::Ok(request) => match request {
      cli::Request::Help(help) => "Help:".concat(help)
      cli::Request::Parsed(command) => render(command)
    }
    Result::Err(error) => kind_text(error.kind).concat(":").concat(error.argument)
  }
}

fn main(): String {
  compact = request_text(["-abn3", "-oout.txt", "-vv=false", "-d=true", "input"])
  explicit = request_text(["-abo=log.txt", "-n", "7", "-v", "input"])
  attached_dash = request_text(["-o-file", "-n-1", "input"])
  missing = request_text(["-abo"])
  unknown = request_text(["-abx"])
  unknown_prefix = request_text(["-zoo"])
  invalid = request_text(["-nxyz", "input"])
  help = request_text(["-h", "-nxyz"])
  string::join([compact, explicit, attached_dash, missing, unknown, unknown_prefix, invalid, help], "\n---\n")
}
"#,
    );

    let result = muga::run_path(&entry).expect("std::cli compact short program should run");
    let value = result.main_result.expect("main result should exist");
    let text = value.to_string();
    assert!(text.contains("true|true|3|out.txt|2|true|input"), "{text}");
    assert!(text.contains("true|true|7|log.txt|1|none|input"), "{text}");
    assert!(text.contains("false|false|-1|-file|0|none|input"), "{text}");
    assert!(text.contains("MissingValue:-o"), "{text}");
    assert!(text.contains("UnknownArgument:-x"), "{text}");
    assert!(text.contains("UnknownArgument:-zoo"), "{text}");
    assert!(text.contains("InvalidValue:-n"), "{text}");
    assert!(text.contains("Help:Usage: compact"), "{text}");
}

#[test]
fn standard_cli_subcommand_parse_request_runs() {
    let root = temp_package_root("std-cli-subcommand-parse-request");
    let entry = write_package_file(
        &root,
        "app/std_cli_subcommand_parse_request/main.muga",
        r#"
package app::std_cli_subcommand_parse_request

import std::cli
import std::string

@cli(about: "Project command")
pub enum Command {
  @cli(name: "build", alias: "b", about: "Build package artifacts")
  Build(BuildCommand)

  @cli(name: "config", alias: "cfg", about: "Configure project")
  Config(ConfigCommand)

  @cli(name: "internal", about: "Internal command", hidden)
  Internal(InternalCommand)
}

@cli(about: "Build package artifacts")
pub record BuildCommand {
  @cli(positional: 1, help: "Entry source file")
  entry: String

  @cli(short: "j", help: "Parallel jobs")
  jobs: Int

  @cli(help: "Release mode")
  release: Bool
}

@cli(about: "Configure project")
pub enum ConfigCommand {
  @cli(name: "set", about: "Set config value")
  Set(ConfigSet)

  @cli(name: "get", about: "Get config value")
  Get(ConfigGet)
}

pub record ConfigSet {
  @cli(positional: 1, help: "Config key")
  key: String

  @cli(positional: 2, help: "Config value")
  value: String
}

pub record ConfigGet {
  @cli(positional: 1, help: "Config key")
  key: String
}

pub record InternalCommand {
  @cli(positional: 1)
  name: String
}

fn render(command: Command): String {
  match command {
    Command::Build(build) => string::join(["build", build.entry, build.jobs.to_string(), build.release.to_string()], "|")
    Command::Config(config) => match config {
      ConfigCommand::Set(config_set) => string::join(["set", config_set.key, config_set.value], "|")
      ConfigCommand::Get(config_get) => string::join(["get", config_get.key], "|")
    }
    Command::Internal(internal) => "internal:".concat(internal.name)
  }
}

fn describe(args: List[String]): String {
  match cli::parse_request[Command](args, "muga") {
    Result::Ok(request) => match request {
      cli::Request::Help(help) => "help:".concat(help)
      cli::Request::Parsed(command) => "parsed:".concat(render(command))
    }
    Result::Err(error) => "err:".concat(error.argument).concat(":").concat(error.message)
  }
}

fn main(): String {
  string::join([
    describe(["build", "-j4", "--release", "app/main.muga"]),
    describe(["b", "app/lib.muga", "-j", "2"]),
    describe(["config", "set", "theme", "dark"]),
    describe(["cfg", "get", "theme"]),
    describe(["--help"]),
    describe(["config", "--help"]),
    describe(["config", "set", "--help"]),
    describe(["unknown"]),
    describe([])
  ], "\n---\n")
}
"#,
    );

    let result = muga::run_path(&entry).expect("std::cli subcommand program should run");
    let value = result.main_result.expect("main result should exist");
    let text = value.to_string();
    assert!(text.contains("parsed:build|app/main.muga|4|true"), "{text}");
    assert!(text.contains("parsed:build|app/lib.muga|2|false"), "{text}");
    assert!(text.contains("parsed:set|theme|dark"), "{text}");
    assert!(text.contains("parsed:get|theme"), "{text}");
    assert!(text.contains("help:Usage: muga <command> [args]"), "{text}");
    assert!(
        text.contains("build  aliases: b  Build package artifacts"),
        "{text}"
    );
    assert!(
        text.contains("config  aliases: cfg  Configure project"),
        "{text}"
    );
    assert!(!text.contains("Internal command"), "{text}");
    assert!(
        text.contains("help:Usage: muga config <command> [args]"),
        "{text}"
    );
    assert!(text.contains("set  Set config value"), "{text}");
    assert!(
        text.contains("help:Usage: muga config set [options] <key> <value>"),
        "{text}"
    );
    assert!(
        text.contains("err:unknown:unknown CLI command `unknown`"),
        "{text}"
    );
    assert!(
        text.contains("err:<command>:missing required CLI command `<command>`"),
        "{text}"
    );
}

#[test]
fn standard_cli_subcommand_parse_request_artifact_run_uses_schema_payload() {
    let root = temp_package_root("std-cli-subcommand-artifacts");
    let entry = write_package_file(
        &root,
        "app/std_cli_subcommand_artifacts/main.muga",
        r#"
package app::std_cli_subcommand_artifacts

import std::cli

@cli(about: "Artifact command")
pub enum Command {
  @cli(name: "build", about: "Build artifacts")
  Build(BuildCommand)
}

pub record BuildCommand {
  @cli(positional: 1)
  entry: String

  @cli(short: "j")
  jobs: Int
}

fn main(): String {
  match cli::parse_request[Command](["build", "-j2", "artifact.muga"], "tool") {
    Result::Ok(request) => match request {
      cli::Request::Help(help) => help
      cli::Request::Parsed(command) => match command {
        Command::Build(build) => build.entry.concat("|").concat(build.jobs.to_string())
      }
    }
    Result::Err(error) => error.message
  }
}
"#,
    );
    let artifact_root = root.join("artifacts");
    muga::write_package_artifacts(&entry, &artifact_root).expect("artifacts should emit");

    let result = muga::run_path_against_artifact_root(&entry, &artifact_root)
        .expect("artifact-backed std::cli subcommand program should run");
    let value = result.main_result.expect("main result should exist");
    assert_eq!(value.to_string(), "artifact.muga|2");

    let build = muga_command()
        .arg("build")
        .arg(&entry)
        .output()
        .expect("muga command should run");
    assert!(build.status.success(), "{build:#?}");
    assert_eq!(String::from_utf8_lossy(&build.stderr), "");

    let built_run = muga_command()
        .arg("run")
        .arg("--built")
        .arg(&entry)
        .output()
        .expect("muga command should run");
    assert!(built_run.status.success(), "{built_run:#?}");
    assert_eq!(
        String::from_utf8_lossy(&built_run.stdout),
        "artifact.muga|2\n"
    );
    assert_eq!(String::from_utf8_lossy(&built_run.stderr), "");
}

