#[test]
fn standard_cli_positional_field_metadata_parse_and_usage_runs() {
    let root = temp_package_root("std-cli-positional-field-metadata");
    let entry = write_package_file(
        &root,
        "app/std_cli_positional_field_metadata/main.muga",
        r#"
package app::std_cli_positional_field_metadata

import std::cli
import std::string

pub enum Format {
  Text
  Json
}

pub record Settings {
  @cli(positional: 1, help: "Input path")
  @validate(non_empty)
  input_path: String

  @cli(positional: 2, help: "Optional output path")
  output_path: Option[String]

  @cli(positional: 3, help: "Extra labels")
  labels: List[String]

  @cli(name: "format", short: "f", help: "Output format")
  format: Format

  @cli(short: "v", help: "Verbose output")
  verbose: Bool
}

pub record Single {
  @cli(positional: 1, help: "Single input")
  input_path: String
}

fn option_text(value: Option[String]): String {
  match value {
    Option::Some(text) => text
    Option::None => "none"
  }
}

fn format_text(value: Format): String {
  match value {
    Format::Text => "Text"
    Format::Json => "Json"
  }
}

fn kind_text(kind: cli::ErrorKind): String {
  match kind {
    cli::ErrorKind::UnknownArgument => "UnknownArgument"
    cli::ErrorKind::MissingArgument => "MissingArgument"
    cli::ErrorKind::MissingValue => "MissingValue"
    cli::ErrorKind::InvalidValue => "InvalidValue"
    cli::ErrorKind::Validation => "Validation"
    cli::ErrorKind::UnsupportedTarget => "UnsupportedTarget"
  }
}

fn defaults(): Settings {
  Settings {
    input_path: "default.muga"
    output_path: Option::None
    labels: ["default"]
    format: Format::Text
    verbose: false
  }
}

fn parsed_text(args: List[String]): String {
  match cli::parse_or(args, defaults()) {
    Result::Ok(settings) => string::join([
      settings.input_path,
      option_text(settings.output_path),
      settings.labels.len().to_string(),
      settings.labels[0],
      settings.labels[1],
      format_text(settings.format),
      settings.verbose.to_string()
    ], "|")
    Result::Err(error) => kind_text(error.kind).concat(":").concat(error.argument)
  }
}

fn strict_error(args: List[String]): String {
  parsed: Result[Settings, cli::Error] = cli::parse(args)
  match parsed {
    Result::Ok(settings) => settings.input_path
    Result::Err(error) => kind_text(error.kind).concat(":").concat(error.argument).concat(":").concat(error.message)
  }
}

fn single_error(args: List[String]): String {
  parsed: Result[Single, cli::Error] = cli::parse(args)
  match parsed {
    Result::Ok(settings) => settings.input_path
    Result::Err(error) => kind_text(error.kind).concat(":").concat(error.argument)
  }
}

fn main(): String {
  parsed = parsed_text(["input.muga", "--format", "Json", "out.txt", "-v", "alpha", "--", "-literal"])
  stopped = parsed_text(["--", "-literal", "out.txt", "tail", "more"])
  missing = strict_error([])
  extra = single_error(["one", "two"])
  unknown_dash = parsed_text(["-literal"])
  usage = cli::usage_for("app", defaults())
  required_usage = cli::usage_for_required[Settings]("app")
  string::join([parsed, stopped, missing, extra, unknown_dash, usage, required_usage], "\n---\n")
}
"#,
    );

    let result = muga::run_path(&entry).expect("std::cli positional metadata program should run");
    let value = result.main_result.expect("main result should exist");
    let text = value.to_string();
    assert!(
        text.contains("input.muga|out.txt|2|alpha|-literal|Json|true"),
        "{text}"
    );
    assert!(
        text.contains("-literal|out.txt|2|tail|more|Text|false"),
        "{text}"
    );
    assert!(
        text.contains(
            "MissingArgument:<input-path>:missing required CLI positional `<input-path>`"
        ),
        "{text}"
    );
    assert!(text.contains("UnknownArgument:two"), "{text}");
    assert!(text.contains("UnknownArgument:-literal"), "{text}");
    assert!(
        text.contains("Usage: app [options] <input-path> [output-path] [labels...]"),
        "{text}"
    );
    assert!(text.contains("Arguments:\n  <input-path>"), "{text}");
    assert!(text.contains("non-empty; Input path"), "{text}");
    assert!(
        text.contains("[output-path]  default: none; Optional output path"),
        "{text}"
    );
    assert!(
        text.contains("[labels...]  repeatable; default: [\"default\"]; Extra labels"),
        "{text}"
    );
    assert!(
        text.contains("Options:\n  -f, --format <Text|Json>"),
        "{text}"
    );
    assert!(text.contains("-v, --verbose[=<Bool>]"), "{text}");
    assert!(text.contains("-f, --format <Format>  required"), "{text}");
}

