#[test]
fn standard_cli_parse_or_artifact_run_uses_schema_payload() {
    let root = temp_package_root("std-cli-parse-or-artifacts");
    let entry = write_package_file(
        &root,
        "app/std_cli_parse_or_artifacts/main.muga",
        r#"
package app::std_cli_parse_or_artifacts

import std::cli

pub record Settings {
  @cli(name: "user", alias: "name", help: "User name")
  name: String
  @cli(name: "port-number")
  port: Int
}

fn main(): String {
  defaults = Settings { name: "app", port: 3000 }
  match cli::parse_or(["--name", "artifact", "--port-number=9000"], defaults) {
    Result::Ok(settings) => settings.name.concat("|").concat(settings.port.to_string())
    Result::Err(error) => error.message
  }
}
"#,
    );
    let artifact_root = root.join("artifacts");
    muga::write_package_artifacts(&entry, &artifact_root).expect("artifacts should emit");

    let result = muga::run_path_against_artifact_root(&entry, &artifact_root)
        .expect("artifact-backed std::cli parse_or program should run");
    let value = result.main_result.expect("main result should exist");
    assert_eq!(value.to_string(), "artifact|9000");

    let build = muga_command()
        .arg("build")
        .arg(&entry)
        .output()
        .expect("muga command should run");
    assert!(build.status.success(), "{build:#?}");
    assert_eq!(String::from_utf8_lossy(&build.stderr), "");

    let built_run = muga_command()
        .arg("run")
        .arg("--built")
        .arg(&entry)
        .output()
        .expect("muga command should run");
    assert!(built_run.status.success(), "{built_run:#?}");
    assert_eq!(
        String::from_utf8_lossy(&built_run.stdout),
        "artifact|9000\n"
    );
    assert_eq!(String::from_utf8_lossy(&built_run.stderr), "");
}

