#[test]
fn standard_fmt_format_values_reports_template_errors() {
    let root = temp_package_root("std-fmt-format-errors");
    let entry = write_package_file(
        &root,
        "app/std_fmt_format_errors/main.muga",
        r#"
package app::std_fmt_format_errors

import std::fmt
import std::string

fn describe(error: fmt::FormatError): String {
  match error {
    fmt::FormatError::MissingValue(index) => "missing:".concat(index.to_string())
    fmt::FormatError::UnclosedPlaceholder(index) => "unclosed:".concat(index.to_string())
    fmt::FormatError::UnexpectedClose(index) => "close:".concat(index.to_string())
  }
}

fn render(result: Result[String, fmt::FormatError]): String {
  match result {
    Result::Ok(value) => value
    Result::Err(error) => describe(error)
  }
}

fn main(): String {
  string::join([
    render(fmt::format_values("{} {}", ["one"])),
    render(fmt::format_values("{bad", [])),
    render(fmt::format_values("bad }", []))
  ], "|")
}
"#,
    );

    let result = muga::run_path(&entry).expect("std::fmt format_values errors should run");
    let value = result.main_result.expect("main result should exist");
    assert_eq!(value.to_string(), "missing:1|unclosed:0|close:4");
}

