#[test]
fn standard_fmt_missing_import_suggests_import() {
    let root = temp_package_root("std-fmt-missing-import");
    let entry = write_package_file(
        &root,
        "app/std_fmt_missing_import/main.muga",
        r#"
package app::std_fmt_missing_import

fn main(): String {
  fmt::repeat("-", 2)
}
"#,
    );

    let diagnostics = muga::check_path(&entry).unwrap_err();
    let diagnostic = diagnostics
        .iter()
        .find(|diagnostic| diagnostic.code == "PK009")
        .expect("missing fmt import diagnostic should exist");
    assert!(diagnostic.message.contains("unknown import alias `fmt`"));
    assert!(
        diagnostic
            .suggestions
            .iter()
            .any(|suggestion| suggestion.message.contains("import std::fmt")),
        "{diagnostic:#?}"
    );
}

#[test]
fn standard_fmt_artifact_run_uses_emitted_std_implementations() {
    let root = temp_package_root("std-fmt-artifacts");
    let entry = write_package_file(
        &root,
        "app/std_fmt_artifacts/main.muga",
        r#"
package app::std_fmt_artifacts

import std::fmt

fn main(): String {
  fmt::pad_right("ok", 4, ".")
}
"#,
    );
    let artifact_root = root.join("artifacts");
    let written =
        muga::write_package_artifacts(&entry, &artifact_root).expect("artifacts should emit");

    assert!(
        written
            .iter()
            .any(|path| path.file_name().is_some_and(|name| name == "std__fmt.mgi")),
        "{written:#?}"
    );
    assert!(
        written
            .iter()
            .any(|path| path.file_name().is_some_and(|name| name == "std__fmt.mgb")),
        "{written:#?}"
    );

    let result = muga::run_path_against_artifact_root(&entry, &artifact_root)
        .expect("artifact-backed std::fmt package program should run");
    let value = result.main_result.expect("main result should exist");
    assert_eq!(value.to_string(), "ok..");
}

