#[test]
fn standard_json_parse_objects_arrays_and_scalars() {
    let root = temp_package_root("std-json-parse");
    let entry = write_package_file(
        &root,
        "app/std_json_parse/main.muga",
        r#"
package app::std_json_parse

import std::json

fn describe(value: json::Value): Result[String, json::Error] {
  match value {
    json::Value::Null => Result::Ok("null")
    json::Value::Bool(flag) => Result::Ok(flag.to_string())
    json::Value::Number(number) => match json::number_as_int(number) {
      Result::Ok(int_value) => Result::Ok(int_value.to_string())
      Result::Err(error) => Result::Err(error)
    }
    json::Value::String(text) => Result::Ok(text)
    json::Value::Array(items) => Result::Ok(items.len().to_string())
    json::Value::Object(fields) => match fields.get("name") {
      Option::Some(item) => describe(item)
      Option::None => Result::Ok("missing")
    }
  }
}

fn main(): Result[String, json::Error] {
  parsed = try json::parse("{\"name\":\"Ada\",\"items\":[1,true,null]}")
  describe(parsed)
}
"#,
    );

    let result = muga::run_path(&entry).expect("std::json parse program should run");
    let value = result.main_result.expect("main result should exist");
    assert_eq!(value.to_string(), "Result::Ok(Ada)");
}

#[test]
fn standard_json_value_accessors_run_as_virtual_package() {
    let root = temp_package_root("std-json-accessors");
    let entry = write_package_file(
        &root,
        "app/std_json_accessors/main.muga",
        r#"
package app::std_json_accessors

import std::json

fn array_len(value: json::Value): Result[Int, json::Error] {
  items = try json::as_array(value)
  Result::Ok(items.len())
}

fn main(): Result[String, json::Error] {
  parsed = try json::parse("{\"name\":\"Ada\",\"port\":8080,\"enabled\":true,\"items\":[1,2,3]}")
  name = try json::object_string_required(parsed, "name")
  port = try json::object_int_required(parsed, "port")
  enabled = try json::object_bool_required(parsed, "enabled")
  fallback = try json::object_string_or(parsed, "missing", "fallback")
  maybe_items = try json::object_get(parsed, "items")
  item_count = match maybe_items {
    Option::Some(value) => try array_len(value)
    Option::None => 0
  }
  text = name.concat("|").concat(port.to_string()).concat("|").concat(enabled.to_string()).concat("|").concat(fallback)
  Result::Ok(text.concat("|").concat(item_count.to_string()))
}
"#,
    );

    let result = muga::run_path(&entry).expect("std::json accessor program should run");
    let value = result.main_result.expect("main result should exist");
    assert_eq!(value.to_string(), "Result::Ok(Ada|8080|true|fallback|3)");
}

#[test]
fn standard_json_value_accessors_report_shape_errors() {
    let root = temp_package_root("std-json-accessor-errors");
    let entry = write_package_file(
        &root,
        "app/std_json_accessor_errors/main.muga",
        r#"
package app::std_json_accessor_errors

import std::json

fn error_message(value: Result[Option[Int], json::Error]): String {
  match value {
    Result::Ok(field) => match field {
      Option::Some(item) => item.to_string()
      Option::None => "missing"
    }
    Result::Err(error) => error.message
  }
}

fn object_error_message(value: Result[Option[json::Value], json::Error]): String {
  match value {
    Result::Ok(field) => "ok"
    Result::Err(error) => error.message
  }
}

fn main(): String {
  fields: Map[String, json::Value] = Map.empty()
  object = json::Value::Object(fields.insert("port", json::Value::String("fast")))
  field_error = error_message(json::object_int(object, "port"))
  missing = error_message(json::object_int(object, "missing"))
  base_error = object_error_message(json::object_get(json::Value::String("text"), "port"))
  field_error.concat("|").concat(missing).concat("|").concat(base_error)
}
"#,
    );

    let result = muga::run_path(&entry).expect("std::json accessor error program should run");
    let value = result.main_result.expect("main result should exist");
    let text = value.to_string();
    assert!(
        text.contains("expected JSON Number for object field `port`"),
        "{text}"
    );
    assert!(text.contains("missing"), "{text}");
    assert!(text.contains("expected JSON Object"), "{text}");
}

#[test]
fn standard_json_required_object_fields_report_missing_errors() {
    let root = temp_package_root("std-json-required-accessors");
    let entry = write_package_file(
        &root,
        "app/std_json_required_accessors/main.muga",
        r#"
package app::std_json_required_accessors

import std::json

fn string_message(value: Result[String, json::Error]): String {
  match value {
    Result::Ok(item) => item
    Result::Err(error) => error.message
  }
}

fn int_message(value: Result[Int, json::Error]): String {
  match value {
    Result::Ok(item) => item.to_string()
    Result::Err(error) => error.message
  }
}

fn bool_message(value: Result[Bool, json::Error]): String {
  match value {
    Result::Ok(item) => item.to_string()
    Result::Err(error) => error.message
  }
}

fn main(): Result[String, json::Error] {
  parsed = try json::parse("{\"name\":\"Ada\",\"port\":8080,\"enabled\":true}")
  name = try json::object_string_required(parsed, "name")
  port = try json::object_int_required(parsed, "port")
  enabled = try json::object_bool_required(parsed, "enabled")
  missing_name = string_message(json::object_string_required(parsed, "missing_name"))
  missing_port = int_message(json::object_int_required(parsed, "missing_port"))
  missing_enabled = bool_message(json::object_bool_required(parsed, "missing_enabled"))
  wrong_type = int_message(json::object_int_required(parsed, "name"))
  Result::Ok(name.concat("|").concat(port.to_string()).concat("|").concat(enabled.to_string()).concat("|").concat(missing_name).concat("|").concat(missing_port).concat("|").concat(missing_enabled).concat("|").concat(wrong_type))
}
"#,
    );

    let result = muga::run_path(&entry).expect("std::json required accessor program should run");
    let value = result.main_result.expect("main result should exist");
    let text = value.to_string();
    assert!(text.contains("Result::Ok(Ada|8080|true|"), "{text}");
    assert!(
        text.contains("missing JSON object field `missing_name`"),
        "{text}"
    );
    assert!(
        text.contains("missing JSON object field `missing_port`"),
        "{text}"
    );
    assert!(
        text.contains("missing JSON object field `missing_enabled`"),
        "{text}"
    );
    assert!(
        text.contains("expected JSON Number for object field `name`"),
        "{text}"
    );
}

#[test]
fn standard_json_composite_object_fields_run_as_virtual_package() {
    let root = temp_package_root("std-json-composite-accessors");
    let entry = write_package_file(
        &root,
        "app/std_json_composite_accessors/main.muga",
        r#"
package app::std_json_composite_accessors

import std::json

fn array_message(value: Result[List[json::Value], json::Error]): String {
  match value {
    Result::Ok(items) => items.len().to_string()
    Result::Err(error) => error.message
  }
}

fn object_message(value: Result[Map[String, json::Value], json::Error]): String {
  match value {
    Result::Ok(fields) => fields.len().to_string()
    Result::Err(error) => error.message
  }
}

fn main(): Result[String, json::Error] {
  parsed = try json::parse("{\"items\":[1,2],\"meta\":{\"team\":\"core\"}}")
  items = try json::object_array_required(parsed, "items")
  maybe_items = try json::object_array(parsed, "items")
  optional_count = match maybe_items {
    Option::Some(values) => values.len()
    Option::None => 0
  }
  empty_items: List[json::Value] = []
  fallback_items = try json::object_array_or(parsed, "missing_items", empty_items)
  meta = try json::object_object_required(parsed, "meta")
  empty_meta: Map[String, json::Value] = Map.empty()
  fallback_meta = try json::object_object_or(parsed, "missing_meta", empty_meta)
  missing_array = array_message(json::object_array_required(parsed, "missing_array"))
  missing_object = object_message(json::object_object_required(parsed, "missing_object"))
  wrong_array = array_message(json::object_array_required(parsed, "meta"))
  wrong_object = object_message(json::object_object_required(parsed, "items"))
  Result::Ok(items.len().to_string().concat("|").concat(optional_count.to_string()).concat("|").concat(fallback_items.len().to_string()).concat("|").concat(meta.len().to_string()).concat("|").concat(fallback_meta.len().to_string()).concat("|").concat(missing_array).concat("|").concat(missing_object).concat("|").concat(wrong_array).concat("|").concat(wrong_object))
}
"#,
    );

    let result = muga::run_path(&entry).expect("std::json composite accessor program should run");
    let value = result.main_result.expect("main result should exist");
    let text = value.to_string();
    assert!(text.contains("Result::Ok(2|2|0|1|0|"), "{text}");
    assert!(
        text.contains("missing JSON object field `missing_array`"),
        "{text}"
    );
    assert!(
        text.contains("missing JSON object field `missing_object`"),
        "{text}"
    );
    assert!(
        text.contains("expected JSON Array for object field `meta`"),
        "{text}"
    );
    assert!(
        text.contains("expected JSON Object for object field `items`"),
        "{text}"
    );
}

#[test]
fn standard_json_path_helpers_run_as_virtual_package() {
    let root = temp_package_root("std-json-path-helpers");
    let entry = write_package_file(
        &root,
        "app/std_json_path_helpers/main.muga",
        r#"
package app::std_json_path_helpers

import std::json

fn option_message(value: Result[Option[json::Value], json::Error]): String {
  match value {
    Result::Ok(item) => match item {
      Option::Some(_) => "present"
      Option::None => "missing"
    }
    Result::Err(error) => error.message
  }
}

fn required_message(value: Result[json::Value, json::Error]): String {
  match value {
    Result::Ok(_) => "present"
    Result::Err(error) => error.message
  }
}

fn main(): Result[String, json::Error] {
  parsed = try json::parse("{\"meta\":{\"team\":\"core\"},\"items\":[{\"name\":\"Ada\"},{\"name\":\"Grace\"}]}")
  team_value = try json::at_required(parsed, [json::PathSegment::Field("meta"), json::PathSegment::Field("team")])
  team = try json::as_string(team_value)
  first_value = try json::at_required(parsed, [json::PathSegment::Field("items"), json::PathSegment::Index(0), json::PathSegment::Field("name")])
  first = try json::as_string(first_value)
  missing = option_message(json::at(parsed, [json::PathSegment::Field("meta"), json::PathSegment::Field("missing")]))
  out_of_range = option_message(json::at(parsed, [json::PathSegment::Field("items"), json::PathSegment::Index(3)]))
  wrong_shape = required_message(json::at_required(parsed, [json::PathSegment::Field("items"), json::PathSegment::Field("bad")]))
  missing_required = required_message(json::at_required(parsed, [json::PathSegment::Field("meta"), json::PathSegment::Field("missing")]))
  Result::Ok(team.concat("|").concat(first).concat("|").concat(missing).concat("|").concat(out_of_range).concat("|").concat(wrong_shape).concat("|").concat(missing_required))
}
"#,
    );

    let result = muga::run_path(&entry).expect("std::json path helper program should run");
    let value = result.main_result.expect("main result should exist");
    let text = value.to_string();
    assert!(
        text.contains("Result::Ok(core|Ada|missing|missing|"),
        "{text}"
    );
    assert!(
        text.contains("expected JSON Object at path .items.bad"),
        "{text}"
    );
    assert!(
        text.contains("missing JSON value at path .meta.missing"),
        "{text}"
    );
}

#[test]
fn standard_json_path_scalar_helpers_run_as_virtual_package() {
    let root = temp_package_root("std-json-path-scalar-helpers");
    let entry = write_package_file(
        &root,
        "app/std_json_path_scalar_helpers/main.muga",
        r#"
package app::std_json_path_scalar_helpers

import std::json

fn option_string_message(value: Result[Option[String], json::Error]): String {
  match value {
    Result::Ok(item) => match item {
      Option::Some(_) => "present"
      Option::None => "missing"
    }
    Result::Err(error) => error.message
  }
}

fn option_int_message(value: Result[Option[Int], json::Error]): String {
  match value {
    Result::Ok(item) => match item {
      Option::Some(_) => "present"
      Option::None => "missing"
    }
    Result::Err(error) => error.message
  }
}

fn string_message(value: Result[String, json::Error]): String {
  match value {
    Result::Ok(_) => "present"
    Result::Err(error) => error.message
  }
}

fn int_message(value: Result[Int, json::Error]): String {
  match value {
    Result::Ok(_) => "present"
    Result::Err(error) => error.message
  }
}

fn bool_message(value: Result[Bool, json::Error]): String {
  match value {
    Result::Ok(_) => "present"
    Result::Err(error) => error.message
  }
}

fn main(): Result[String, json::Error] {
  parsed = try json::parse("{\"meta\":{\"team\":\"core\",\"enabled\":true,\"count\":3,\"ratio\":1.5},\"items\":[{\"name\":\"Ada\"}]}")
  team = try json::at_string_required(parsed, [json::PathSegment::Field("meta"), json::PathSegment::Field("team")])
  fallback = try json::at_string_or(parsed, [json::PathSegment::Field("meta"), json::PathSegment::Field("missing")], "fallback")
  count = try json::at_int_required(parsed, [json::PathSegment::Field("meta"), json::PathSegment::Field("count")])
  enabled = try json::at_bool_required(parsed, [json::PathSegment::Field("meta"), json::PathSegment::Field("enabled")])
  missing = option_string_message(json::at_string(parsed, [json::PathSegment::Field("meta"), json::PathSegment::Field("missing")]))
  out_of_range = option_int_message(json::at_int(parsed, [json::PathSegment::Field("items"), json::PathSegment::Index(3)]))
  wrong_string = string_message(json::at_string_required(parsed, [json::PathSegment::Field("meta"), json::PathSegment::Field("count")]))
  wrong_int = int_message(json::at_int_required(parsed, [json::PathSegment::Field("meta"), json::PathSegment::Field("ratio")]))
  wrong_traversal = bool_message(json::at_bool_required(parsed, [json::PathSegment::Field("items"), json::PathSegment::Field("bad")]))
  Result::Ok(team.concat("|").concat(fallback).concat("|").concat(count.to_string()).concat("|").concat(enabled.to_string()).concat("|").concat(missing).concat("|").concat(out_of_range).concat("|").concat(wrong_string).concat("|").concat(wrong_int).concat("|").concat(wrong_traversal))
}
"#,
    );

    let result = muga::run_path(&entry).expect("std::json path scalar helper program should run");
    let value = result.main_result.expect("main result should exist");
    let text = value.to_string();
    assert!(
        text.contains("Result::Ok(core|fallback|3|true|missing|missing|"),
        "{text}"
    );
    assert!(
        text.contains("expected JSON String at path .meta.count"),
        "{text}"
    );
    assert!(
        text.contains("expected JSON Int at path .meta.ratio"),
        "{text}"
    );
    assert!(
        text.contains("expected JSON Object at path .items.bad"),
        "{text}"
    );
}

#[test]
fn standard_json_path_collection_helpers_run_as_virtual_package() {
    let root = temp_package_root("std-json-path-collection-helpers");
    let entry = write_package_file(
        &root,
        "app/std_json_path_collection_helpers/main.muga",
        r#"
package app::std_json_path_collection_helpers

import std::json

fn option_string_list_message(value: Result[Option[List[String]], json::Error]): String {
  match value {
    Result::Ok(item) => match item {
      Option::Some(_) => "present"
      Option::None => "missing"
    }
    Result::Err(error) => error.message
  }
}

fn option_value_list_message(value: Result[Option[List[json::Value]], json::Error]): String {
  match value {
    Result::Ok(item) => match item {
      Option::Some(_) => "present"
      Option::None => "missing"
    }
    Result::Err(error) => error.message
  }
}

fn string_list_message(value: Result[List[String], json::Error]): String {
  match value {
    Result::Ok(_) => "present"
    Result::Err(error) => error.message
  }
}

fn int_list_message(value: Result[List[Int], json::Error]): String {
  match value {
    Result::Ok(_) => "present"
    Result::Err(error) => error.message
  }
}

fn object_message(value: Result[Map[String, json::Value], json::Error]): String {
  match value {
    Result::Ok(_) => "present"
    Result::Err(error) => error.message
  }
}

fn main(): Result[String, json::Error] {
  parsed = try json::parse("{\"meta\":{\"tags\":[\"core\",\"api\"],\"counts\":[1,2],\"flags\":[true,false],\"obj\":{\"team\":\"core\"},\"bad_tags\":[\"ok\",3],\"ratio_counts\":[1,1.5]},\"items\":[{\"name\":\"Ada\"}]}")
  tags = try json::at_string_array_required(parsed, [json::PathSegment::Field("meta"), json::PathSegment::Field("tags")])
  fallback = try json::at_string_array_or(parsed, [json::PathSegment::Field("meta"), json::PathSegment::Field("missing_tags")], ["fallback"])
  counts = try json::at_int_array_required(parsed, [json::PathSegment::Field("meta"), json::PathSegment::Field("counts")])
  flags = try json::at_bool_array_required(parsed, [json::PathSegment::Field("meta"), json::PathSegment::Field("flags")])
  obj = try json::at_object_required(parsed, [json::PathSegment::Field("meta"), json::PathSegment::Field("obj")])
  items = try json::at_array_required(parsed, [json::PathSegment::Field("items")])
  empty_values: List[json::Value] = []
  fallback_values = try json::at_array_or(parsed, [json::PathSegment::Field("missing_items")], empty_values)
  missing = option_string_list_message(json::at_string_array(parsed, [json::PathSegment::Field("meta"), json::PathSegment::Field("none")]))
  out_of_range = option_value_list_message(json::at_array(parsed, [json::PathSegment::Field("items"), json::PathSegment::Index(3)]))
  wrong_array = string_list_message(json::at_string_array_required(parsed, [json::PathSegment::Field("meta"), json::PathSegment::Field("obj")]))
  wrong_string_item = string_list_message(json::at_string_array_required(parsed, [json::PathSegment::Field("meta"), json::PathSegment::Field("bad_tags")]))
  wrong_int_item = int_list_message(json::at_int_array_required(parsed, [json::PathSegment::Field("meta"), json::PathSegment::Field("ratio_counts")]))
  wrong_traversal = object_message(json::at_object_required(parsed, [json::PathSegment::Field("items"), json::PathSegment::Field("bad")]))
  Result::Ok(tags.len().to_string().concat("|").concat(fallback.len().to_string()).concat("|").concat(counts.len().to_string()).concat("|").concat(flags.len().to_string()).concat("|").concat(obj.len().to_string()).concat("|").concat(items.len().to_string()).concat("|").concat(fallback_values.len().to_string()).concat("|").concat(missing).concat("|").concat(out_of_range).concat("|").concat(wrong_array).concat("|").concat(wrong_string_item).concat("|").concat(wrong_int_item).concat("|").concat(wrong_traversal))
}
"#,
    );
    let result =
        muga::run_path(&entry).expect("std::json path collection helper program should run");
    let value = result.main_result.expect("main result should exist");
    let text = value.to_string();
    assert!(
        text.contains("Result::Ok(2|1|2|2|1|1|0|missing|missing|"),
        "{}",
        text
    );
    for expected in [
        "expected JSON Array at path .meta.obj",
        "expected JSON String at path .meta.bad_tags[1]",
        "expected JSON Int at path .meta.ratio_counts[1]",
        "expected JSON Object at path .items.bad",
    ] {
        assert!(text.contains(expected), "{}", text);
    }
}

#[test]
fn standard_json_scalar_array_projections_run_as_virtual_package() {
    let root = temp_package_root("std-json-array-projections");
    let entry = write_package_file(
        &root,
        "app/std_json_array_projections/main.muga",
        r#"
package app::std_json_array_projections

import std::json

fn strings_message(value: Result[List[String], json::Error]): String {
  match value {
    Result::Ok(items) => items.len().to_string()
    Result::Err(error) => error.message
  }
}

fn ints_message(value: Result[List[Int], json::Error]): String {
  match value {
    Result::Ok(items) => items.len().to_string()
    Result::Err(error) => error.message
  }
}

fn bools_message(value: Result[List[Bool], json::Error]): String {
  match value {
    Result::Ok(items) => items.len().to_string()
    Result::Err(error) => error.message
  }
}

fn main(): Result[String, json::Error] {
  parsed = try json::parse("{\"names\":[\"Ada\",\"Grace\"],\"ports\":[80,443],\"flags\":[true,false],\"bad_names\":[\"ok\",1]}")
  names_values = try json::object_array_required(parsed, "names")
  ports_values = try json::object_array_required(parsed, "ports")
  flags_values = try json::object_array_required(parsed, "flags")
  bad_name_values = try json::object_array_required(parsed, "bad_names")
  names = try json::array_strings(names_values)
  ports = try json::array_ints(ports_values)
  flags = try json::array_bools(flags_values)
  bad_names = strings_message(json::array_strings(bad_name_values))
  bad_ints = ints_message(json::array_ints([json::Value::Number(json::Number::Raw("1.5"))]))
  bad_bools = bools_message(json::array_bools([json::Value::String("yes")]))
  Result::Ok(names.len().to_string().concat("|").concat(ports.len().to_string()).concat("|").concat(flags.len().to_string()).concat("|").concat(bad_names).concat("|").concat(bad_ints).concat("|").concat(bad_bools))
}
"#,
    );

    let result =
        muga::run_path(&entry).expect("std::json scalar array projection program should run");
    let value = result.main_result.expect("main result should exist");
    let text = value.to_string();
    assert!(text.contains("Result::Ok(2|2|2|"), "{text}");
    assert!(
        text.contains("expected JSON String for array item at index 1"),
        "{text}"
    );
    assert!(
        text.contains("expected JSON Int for array item at index 0"),
        "{text}"
    );
    assert!(
        text.contains("expected JSON Bool for array item at index 0"),
        "{text}"
    );
}

#[test]
fn standard_json_scalar_array_field_helpers_run_as_virtual_package() {
    let root = temp_package_root("std-json-array-field-helpers");
    let entry = write_package_file(
        &root,
        "app/std_json_array_field_helpers/main.muga",
        r#"
package app::std_json_array_field_helpers

import std::json

fn string_list_message(value: Result[List[String], json::Error]): String {
  match value {
    Result::Ok(items) => items.len().to_string()
    Result::Err(error) => error.message
  }
}

fn int_list_message(value: Result[List[Int], json::Error]): String {
  match value {
    Result::Ok(items) => items.len().to_string()
    Result::Err(error) => error.message
  }
}

fn bool_list_message(value: Result[List[Bool], json::Error]): String {
  match value {
    Result::Ok(items) => items.len().to_string()
    Result::Err(error) => error.message
  }
}

fn string_option_message(value: Result[Option[List[String]], json::Error]): String {
  match value {
    Result::Ok(field) => match field {
      Option::Some(items) => items.len().to_string()
      Option::None => "none"
    }
    Result::Err(error) => error.message
  }
}

fn bool_option_message(value: Result[Option[List[Bool]], json::Error]): String {
  match value {
    Result::Ok(field) => match field {
      Option::Some(items) => items.len().to_string()
      Option::None => "none"
    }
    Result::Err(error) => error.message
  }
}

fn main(): Result[String, json::Error] {
  parsed = try json::parse("{\"tags\":[\"tool\",\"service\"],\"ports\":[80,443],\"flags\":[true,false],\"bad_tags\":[\"ok\",1],\"bad_ports\":[1.5],\"bad_flags\":[\"true\"],\"shape\":{\"bad\":true}}")
  tags = try json::object_string_array_required(parsed, "tags")
  ports = try json::object_int_array_required(parsed, "ports")
  flags = try json::object_bool_array_required(parsed, "flags")
  fallback_tags: List[String] = ["default"]
  default_tags = try json::object_string_array_or(parsed, "missing_tags", fallback_tags)
  missing_flags = bool_option_message(json::object_bool_array(parsed, "missing_flags"))
  missing_required = string_list_message(json::object_string_array_required(parsed, "missing_tags"))
  bad_tags = string_list_message(json::object_string_array_required(parsed, "bad_tags"))
  bad_ports = int_list_message(json::object_int_array_required(parsed, "bad_ports"))
  bad_flags = bool_list_message(json::object_bool_array_required(parsed, "bad_flags"))
  shape = string_option_message(json::object_string_array(parsed, "shape"))
  Result::Ok(tags.len().to_string().concat("|").concat(ports.len().to_string()).concat("|").concat(flags.len().to_string()).concat("|").concat(default_tags.len().to_string()).concat("|").concat(missing_flags).concat("|").concat(missing_required).concat("|").concat(bad_tags).concat("|").concat(bad_ports).concat("|").concat(bad_flags).concat("|").concat(shape))
}
"#,
    );

    let result =
        muga::run_path(&entry).expect("std::json scalar array field helper program should run");
    let value = result.main_result.expect("main result should exist");
    let text = value.to_string();
    assert!(text.contains("Result::Ok(2|2|2|1|none|"), "{text}");
    assert!(
        text.contains("missing JSON object field `missing_tags`"),
        "{text}"
    );
    assert!(
        text.contains("expected JSON String for object field `bad_tags` array item at index 1"),
        "{text}"
    );
    assert!(
        text.contains("expected JSON Int for object field `bad_ports` array item at index 0"),
        "{text}"
    );
    assert!(
        text.contains("expected JSON Bool for object field `bad_flags` array item at index 0"),
        "{text}"
    );
    assert!(
        text.contains("expected JSON Array for object field `shape`"),
        "{text}"
    );
}

