#[test]
fn standard_json_parse_reports_data_error_kinds() {
    let root = temp_package_root("std-json-errors");
    let entry = write_package_file(
        &root,
        "app/std_json_errors/main.muga",
        r#"
package app::std_json_errors

import std::json

fn error_kind_name(error: json::Error): String {
  match error.kind {
    json::ErrorKind::UnexpectedEnd => "UnexpectedEnd"
    json::ErrorKind::UnexpectedToken => "UnexpectedToken"
    json::ErrorKind::InvalidEscape => "InvalidEscape"
    json::ErrorKind::InvalidNumber => "InvalidNumber"
    json::ErrorKind::NumberOutOfRange => "NumberOutOfRange"
    json::ErrorKind::DuplicateKey => "DuplicateKey"
    json::ErrorKind::TrailingCharacters => "TrailingCharacters"
    json::ErrorKind::NestingLimitExceeded => "NestingLimitExceeded"
    json::ErrorKind::Validation => "Validation"
  }
}

fn parse_kind(text: String): String {
  match json::parse(text) {
    Result::Ok(parsed) => "ok"
    Result::Err(error) => error_kind_name(error)
  }
}

fn main(): String {
  first = parse_kind("{\"a\":1,\"a\":2}")
  second = parse_kind("{\"x\":\"\\q\"}")
  third = parse_kind("9223372036854775808")
  fourth = parse_kind("true false")
  first.concat("|").concat(second).concat("|").concat(third).concat("|").concat(fourth)
}
"#,
    );

    let result = muga::run_path(&entry).expect("std::json error program should run");
    let value = result.main_result.expect("main result should exist");
    assert_eq!(
        value.to_string(),
        "DuplicateKey|InvalidEscape|NumberOutOfRange|TrailingCharacters"
    );
}

