#[test]
fn standard_json_encode_typed_record_runs() {
    let root = temp_package_root("std-json-encode-typed-record");
    let entry = write_package_file(
        &root,
        "app/std_json_encode_typed_record/main.muga",
        r#"
package app::std_json_encode_typed_record

import std::json

enum Mode {
  @json(rename: "auto", alias: "automatic")
  Auto
  @json(rename: "manual")
  Manual
}

enum Action {
  Idle
  Route(Server)
}

record Server {
  @json(rename: "server_host", alias: "host")
  @validate(non_empty)
  host: String
  @json(rename: "server_port")
  @validate(min: 1, max: 10)
  port: Int
}

record Settings {
  name: String
  enabled: Bool
  owner: Option[String]
  server: Server
  mode: Mode
  action: Action
  tags: List[String]
  limits: Map[String, Int]
  raw: json::Value
}

fn main(): Result[String, json::Error] {
  limits: Map[String, Int] = Map.empty()
  raw_map: Map[String, json::Value] = Map.empty()
  settings = Settings {
    name: "Ada",
    enabled: true,
    owner: Option::None,
    server: Server { host: "api", port: 5 },
    mode: Mode::Auto,
    action: Action::Route(Server { host: "edge", port: 7 }),
    tags: ["cli", "json"],
    limits: limits.insert("max", 5),
    raw: json::Value::Object(raw_map.insert("team", json::Value::String("core")))
  }
  json::encode_typed(settings)
}
"#,
    );

    let result = muga::run_path(&entry).expect("typed std::json encode program should run");
    let value = result.main_result.expect("main result should exist");
    assert_eq!(
        value.to_string(),
        "Result::Ok({\"action\":{\"Route\":{\"server_host\":\"edge\",\"server_port\":7}},\"enabled\":true,\"limits\":{\"max\":5},\"mode\":\"auto\",\"name\":\"Ada\",\"raw\":{\"team\":\"core\"},\"server\":{\"server_host\":\"api\",\"server_port\":5},\"tags\":[\"cli\",\"json\"]})"
    );
}

