#[test]
fn standard_json_parse_reports_nesting_limit() {
    let root = temp_package_root("std-json-nesting");
    let nested = format!("{}0{}", "[".repeat(130), "]".repeat(130));
    let entry = write_package_file(
        &root,
        "app/std_json_nesting/main.muga",
        &format!(
            r#"
package app::std_json_nesting

import std::json

fn error_kind_name(error: json::Error): String {{
  match error.kind {{
    json::ErrorKind::UnexpectedEnd => "UnexpectedEnd"
    json::ErrorKind::UnexpectedToken => "UnexpectedToken"
    json::ErrorKind::InvalidEscape => "InvalidEscape"
    json::ErrorKind::InvalidNumber => "InvalidNumber"
    json::ErrorKind::NumberOutOfRange => "NumberOutOfRange"
    json::ErrorKind::DuplicateKey => "DuplicateKey"
    json::ErrorKind::TrailingCharacters => "TrailingCharacters"
    json::ErrorKind::NestingLimitExceeded => "NestingLimitExceeded"
    json::ErrorKind::Validation => "Validation"
  }}
}}

fn main(): String {{
  match json::parse("{nested}") {{
    Result::Ok(parsed) => "ok"
    Result::Err(error) => error_kind_name(error)
  }}
}}
"#
        ),
    );

    let result = muga::run_path(&entry).expect("std::json nesting program should run");
    let value = result.main_result.expect("main result should exist");
    assert_eq!(value.to_string(), "NestingLimitExceeded");
}

#[test]
fn standard_json_encode_reports_nesting_limit() {
    let root = temp_package_root("std-json-encode-nesting");
    let entry = write_package_file(
        &root,
        "app/std_json_encode_nesting/main.muga",
        r#"
package app::std_json_encode_nesting

import std::json

fn error_kind_name(error: json::Error): String {
  match error.kind {
    json::ErrorKind::UnexpectedEnd => "UnexpectedEnd"
    json::ErrorKind::UnexpectedToken => "UnexpectedToken"
    json::ErrorKind::InvalidEscape => "InvalidEscape"
    json::ErrorKind::InvalidNumber => "InvalidNumber"
    json::ErrorKind::NumberOutOfRange => "NumberOutOfRange"
    json::ErrorKind::DuplicateKey => "DuplicateKey"
    json::ErrorKind::TrailingCharacters => "TrailingCharacters"
    json::ErrorKind::NestingLimitExceeded => "NestingLimitExceeded"
    json::ErrorKind::Validation => "Validation"
  }
}

fn main(): String {
  mut value = json::int(0)
  mut depth = 0
  while depth < 130 {
    value = json::Value::Array([value])
    depth = depth + 1
  }
  match json::encode(value) {
    Result::Ok(text) => text
    Result::Err(error) => error_kind_name(error)
  }
}
"#,
    );

    let result = muga::run_path(&entry).expect("std::json encode nesting program should run");
    let value = result.main_result.expect("main result should exist");
    assert_eq!(value.to_string(), "NestingLimitExceeded");
}

