#[test]
fn standard_json_decode_rejects_deferred_structural_targets() {
    let cases = [
        (
            "std-json-decode-unsupported-generic-enum",
            "app/std_json_decode_unsupported_generic_enum/main.muga",
            r#"
package app::std_json_decode_unsupported_generic_enum

import std::json

enum Box[T] {
  Value(T)
}

record Settings {
  boxed: Box[String]
}

fn main(): Result[Settings, json::Error] {
  parsed = try json::parse("{\"boxed\":{\"Value\":\"x\"}}")
  decoded: Result[Settings, json::Error] = json::decode(parsed)
  decoded
}
"#,
            "Box[String]",
        ),
        (
            "std-json-decode-unsupported-generic-record",
            "app/std_json_decode_unsupported_generic/main.muga",
            r#"
package app::std_json_decode_unsupported_generic

import std::json

record Box[T] {
  value: T
}

record Settings {
  boxed: Box[String]
}

fn main(): Result[Settings, json::Error] {
  parsed = try json::parse("{\"boxed\":{\"value\":\"x\"}}")
  decoded: Result[Settings, json::Error] = json::decode(parsed)
  decoded
}
"#,
            "Box[String]",
        ),
        (
            "std-json-decode-unsupported-map-key",
            "app/std_json_decode_unsupported_map_key/main.muga",
            r#"
package app::std_json_decode_unsupported_map_key

import std::json

record Settings {
  values: Map[Int, String]
}

fn main(): Result[Settings, json::Error] {
  parsed = try json::parse("{\"values\":{\"1\":\"x\"}}")
  decoded: Result[Settings, json::Error] = json::decode(parsed)
  decoded
}
"#,
            "Map[Int, String]",
        ),
    ];

    for (root_name, relative, source, expected_type) in cases {
        let root = temp_package_root(root_name);
        let entry = write_package_file(&root, relative, source);
        let diagnostics =
            muga::run_path(&entry).expect_err("unsupported structural target should be rejected");
        assert!(
            diagnostics.iter().any(|diagnostic| {
                diagnostic.code == "T006"
                    && diagnostic.message.contains("`json::decode` supports only")
                    && diagnostic.message.contains(expected_type)
            }),
            "{expected_type}: {diagnostics:#?}"
        );
    }
}

