#[test]
fn standard_json_decode_artifact_run_uses_schema_payload() {
    let root = temp_package_root("std-json-decode-required-artifacts");
    let entry = write_package_file(
        &root,
        "app/std_json_decode_required_artifacts/main.muga",
        r#"
package app::std_json_decode_required_artifacts

import std::json
import std::string

record Settings {
  name: String
  port: Int
  tags: List[String]
}

fn main(): Result[String, json::Error] {
  parsed = try json::parse("{\"name\":\"Ada\",\"port\":9090,\"tags\":[\"tool\"]}")
  settings: Settings = try json::decode(parsed)
  Result::Ok(string::join([settings.name, settings.port.to_string(), settings.tags.len().to_string()], "|"))
}
"#,
    );
    let artifact_root = root.join("artifacts");
    let written =
        muga::write_package_artifacts(&entry, &artifact_root).expect("artifacts should emit");

    assert!(
        written
            .iter()
            .any(|path| path.file_name().is_some_and(|name| name == "std__json.mgb")),
        "{written:#?}"
    );

    let result = muga::run_path_against_artifact_root(&entry, &artifact_root)
        .expect("artifact-backed std::json decode program should run");
    let value = result.main_result.expect("main result should exist");
    assert_eq!(value.to_string(), "Result::Ok(Ada|9090|1)");

    let build = muga_command()
        .arg("build")
        .arg(&entry)
        .output()
        .expect("muga command should run");
    assert!(build.status.success(), "{build:#?}");
    assert_eq!(String::from_utf8_lossy(&build.stderr), "");

    let built_run = muga_command()
        .arg("run")
        .arg("--built")
        .arg(&entry)
        .output()
        .expect("muga command should run");
    assert!(built_run.status.success(), "{built_run:#?}");
    assert_eq!(
        String::from_utf8_lossy(&built_run.stdout),
        "Result::Ok(Ada|9090|1)\n"
    );
    assert_eq!(String::from_utf8_lossy(&built_run.stderr), "");
}

