#[test]
fn standard_config_load_json_or_artifact_run_uses_schema_payload() {
    let root = temp_package_root("std-config-load-json-or-artifacts");
    let config = write_package_file(
        &root,
        "settings.json",
        r#"
{
  "owner": "ops",
  "servers": [{ "port": 9090 }],
  "limits": { "max": 7 }
}
"#,
    );
    let config_literal = muga_string_literal(&display_path(&config));
    let entry = write_package_file(
        &root,
        "app/std_config_load_json_or_artifacts/main.muga",
        &format!(
            r#"
package app::std_config_load_json_or_artifacts

import std::config
import std::path
import std::string

record Server {{
  port: Int
}}

record Settings {{
  port: Int
  owner: Option[String]
  servers: List[Server]
  limits: Map[String, Int]
}}

fn option_string(value: Option[String]): String {{
  match value {{
    Option::Some(text) => text
    Option::None => "none"
  }}
}}

fn option_int(value: Option[Int]): String {{
  match value {{
    Option::Some(number) => number.to_string()
    Option::None => "none"
  }}
}}

fn default_settings(): Settings {{
  servers: List[Server] = []
  limits: Map[String, Int] = Map.empty()
  Settings {{ port: 8080, owner: Option::None, servers: servers, limits: limits }}
}}

fn main(): Result[String, config::Error] {{
  settings = try config::load_json_or(path::from_string({config_literal}), default_settings())
  Result::Ok(string::join([
    option_string(settings.owner),
    settings.servers[0].port.to_string(),
    option_int(settings.limits.get("max")),
    settings.port.to_string()
  ], "|"))
}}
"#
        ),
    );
    let artifact_root = root.join("artifacts");
    let written =
        muga::write_package_artifacts(&entry, &artifact_root).expect("artifacts should emit");

    for expected in ["std__config.mgb", "std__path.mgb"] {
        assert!(
            written
                .iter()
                .any(|path| path.file_name().is_some_and(|name| name == expected)),
            "{written:#?}"
        );
    }

    let result = muga::run_path_against_artifact_root(&entry, &artifact_root)
        .expect("artifact-backed std::config load_json_or program should run");
    let value = result.main_result.expect("main result should exist");
    assert_eq!(value.to_string(), "Result::Ok(ops|9090|7|8080)");

    let build = muga_command()
        .arg("build")
        .arg(&entry)
        .output()
        .expect("muga command should run");
    assert!(build.status.success(), "{build:#?}");
    assert_eq!(String::from_utf8_lossy(&build.stderr), "");

    let built_run = muga_command()
        .arg("run")
        .arg("--built")
        .arg(&entry)
        .output()
        .expect("muga command should run");
    assert!(built_run.status.success(), "{built_run:#?}");
    assert_eq!(
        String::from_utf8_lossy(&built_run.stdout),
        "Result::Ok(ops|9090|7|8080)\n"
    );
    assert_eq!(String::from_utf8_lossy(&built_run.stderr), "");
}

