#[test]
fn standard_fs_read_resource_text_reads_archive_dependency_resources_from_cache() {
    let workspace = temp_package_root("std-fs-resource-archive-dependency");
    let shared_root = workspace.join("shared");
    let app_root = workspace.join("app");
    let archive_root = workspace.join("archives");
    write_package_file(
        &shared_root,
        "muga.toml",
        r#"
[package]
name = "shared"
source = "src"
resources = "resources"
"#,
    );
    write_package_file(&shared_root, "resources/static/banner.txt", "from-archive");
    let shared_entry = write_package_file(
        &shared_root,
        "src/resources/main.muga",
        r#"
import std::fs
import std::io

pub fn banner(): Result[String, io::IOError] {
  fs::read_resource_text("shared", "static/banner.txt")
}
"#,
    );
    let archive =
        muga::write_package_archive(&shared_entry, &archive_root).expect("archive should emit");
    let archive_file = archive
        .path
        .file_name()
        .and_then(|name| name.to_str())
        .expect("archive file name should be UTF-8");
    write_package_file(
        &app_root,
        "muga.toml",
        &format!(
            r#"
[package]
name = "app"
source = "src"

[dependencies]
shared = {{ archive = "../archives/{archive_file}", hash = "{}" }}
"#,
            archive.content_hash
        ),
    );
    let entry = write_package_file(
        &app_root,
        "src/main/main.muga",
        r#"
import shared::resources as resources
import std::io

fn main(): Result[String, io::IOError] {
  text = try resources::banner()
  Result::Ok(text.concat("|app"))
}
"#,
    );

    let result = muga::run_path(&entry).expect("archive dependency resource source run should run");
    let value = result.main_result.expect("main result should exist");
    assert_eq!(value.to_string(), "Result::Ok(from-archive|app)");
    let cache_resource = app_root
        .join(".muga/packages")
        .join(format!(
            "shared-sha256-{}",
            archive
                .content_hash
                .strip_prefix("sha256:")
                .expect("archive hash should be sha256")
        ))
        .join("resources/static/banner.txt");
    assert!(
        cache_resource.exists(),
        "expected cached resource at {}",
        display_path(&cache_resource)
    );

    muga::build_package_artifacts(&entry).expect("archive dependency resource build should pass");
    let built = muga::run_path_against_default_build_artifacts(&entry)
        .expect("archive dependency resource built run should run");
    let value = built.main_result.expect("main result should exist");
    assert_eq!(value.to_string(), "Result::Ok(from-archive|app)");
}

