#[test]
fn cli_emit_app_bundle_writes_source_backed_layout_and_launcher() {
    let root = temp_package_root("cli-emit-app-bundle");
    write_package_file(
        &root,
        "muga.toml",
        r#"
[package]
name = "app"
source = "src"
resources = "resources"
"#,
    );
    write_package_file(&root, "resources/messages/greeting.txt", "bundle");
    let entry = write_package_file(
        &root,
        "src/main/main.muga",
        r#"
import std::cli
import std::env
import std::fs
import std::io

fn main(): Result[String, io::IOError] {
  text = try fs::read_resource_text("app", "messages/greeting.txt")
  arg = cli::positional_or(env::args(), 0, "none")
  Result::Ok(text.concat("|").concat(arg))
}
"#,
    );
    let bundle = root.join("dist/app");

    let output = muga_command()
        .arg("emit-app-bundle")
        .arg("--output-dir")
        .arg(&bundle)
        .arg("--program")
        .arg("bundle-tool")
        .arg(&entry)
        .output()
        .expect("muga command should run");
    let stdout = String::from_utf8_lossy(&output.stdout);
    let stderr = String::from_utf8_lossy(&output.stderr);

    assert!(output.status.success(), "{output:#?}");
    assert!(stdout.contains("written\t"), "{stdout}");
    assert!(
        stdout.contains("bin/bundle-tool") || stdout.contains("bin\\bundle-tool"),
        "{stdout}"
    );
    assert_eq!(stderr, "");
    assert!(bundle.join("muga.toml").is_file());
    assert!(bundle.join("muga.lock").is_file());
    assert!(bundle.join("src/main/main.muga").is_file());
    assert!(bundle.join("resources/messages/greeting.txt").is_file());
    assert!(bundle.join(".muga/app-bundle").is_file());
    assert!(bundle.join(".muga/build/app__main.mgi").is_file());
    assert!(bundle.join(".muga/build/app__main.mgc").is_file());
    assert!(bundle.join(".muga/build/app__main.mgb").is_file());
    assert!(bundle.join("bin/bundle-tool").is_file());
    assert!(bundle.join("README.md").is_file());

    let json_bundle = root.join("dist/json-app");
    let json_output = muga_command()
        .arg("emit-app-bundle")
        .arg("--format")
        .arg("json")
        .arg("--output-dir")
        .arg(&json_bundle)
        .arg("--program")
        .arg("json-bundle-tool")
        .arg(&entry)
        .output()
        .expect("muga emit-app-bundle --format json should run");
    let json_stdout = String::from_utf8_lossy(&json_output.stdout);
    let json_stderr = String::from_utf8_lossy(&json_output.stderr);
    assert!(json_output.status.success(), "{json_output:#?}");
    assert_eq!(json_stderr, "");
    assert!(
        json_stdout.contains("\"command\":\"emit-app-bundle\"")
            && json_stdout.contains("\"status\":\"ok\"")
            && json_stdout.contains("\"root\":{\"path\":\"")
            && json_stdout.contains("\"entry\":{\"path\":\"")
            && json_stdout.contains("\"launcher\":{\"path\":\"")
            && json_stdout.contains("\"program\":\"json-bundle-tool\"")
            && json_stdout.contains("\"sourceMode\":\"sourceBacked\"")
            && json_stdout.contains("\"artifacts\":[")
            && json_stdout.contains("\"files\":[")
            && json_stdout.contains(".muga/app-bundle")
            && json_stdout.contains("bin/json-bundle-tool")
            && json_bundle.join("bin/json-bundle-tool").is_file(),
        "{json_stdout}"
    );

    let bundle_readme = fs::read_to_string(bundle.join("README.md")).unwrap();
    for required in [
        "bin/bundle-tool",
        "muga run-app-bundle .",
        "muga install-app --output-dir <bin-dir> --program bundle-tool .",
        "muga list-installed-apps --output-dir <bin-dir>",
        "muga uninstall-app --output-dir <bin-dir> --program bundle-tool",
        "muga emit-app-completions --format json --output-dir <completion-dir> --type <Type> .",
        "muga emit-app-archive --archive-root <archive-dir> --program bundle-tool .",
        "muga verify-app-archive <archive-file>",
        "muga unpack-app-archive [--format text|json] [--expected-hash sha256:<hex>] --output-dir <bundle-dir> <archive-file>",
        "Use `--replace-owned` when updating a launcher already installed by Muga",
        "never edit shell startup files",
    ] {
        assert!(
            bundle_readme.contains(required),
            "bundle README missing `{required}`:\n{bundle_readme}"
        );
    }

    let run = Command::new("sh")
        .arg(bundle.join("bin/bundle-tool"))
        .arg("Ada")
        .env("MUGA_BIN", env!("CARGO_BIN_EXE_muga"))
        .output()
        .expect("app bundle launcher should run");
    let run_stdout = String::from_utf8_lossy(&run.stdout);
    let run_stderr = String::from_utf8_lossy(&run.stderr);

    assert!(run.status.success(), "{run:#?}");
    assert!(
        run_stdout.contains("Result::Ok(bundle|Ada)"),
        "{run_stdout}"
    );
    assert_eq!(run_stderr, "");
}

#[test]
fn emit_app_bundle_reports_bundle_local_artifact_paths() {
    let root = temp_package_root("emit-app-bundle-artifact-paths");
    write_package_file(
        &root,
        "muga.toml",
        r#"
[package]
name = "app"
source = "src"
"#,
    );
    let entry = write_package_file(
        &root,
        "src/main/main.muga",
        r#"
fn main(): String {
  "ok"
}
"#,
    );
    let bundle = root.join("dist/app");

    let output =
        muga::emit_app_bundle(&entry, &bundle, None).expect("app bundle should be emitted");
    let bundle_artifact_root = bundle.join(".muga/build");

    assert!(
        output
            .artifacts
            .iter()
            .all(|path| path.starts_with(&bundle_artifact_root)),
        "{:#?}",
        output.artifacts
    );
    assert!(
        output
            .artifacts
            .contains(&bundle_artifact_root.join("app__main.mgi")),
        "{:#?}",
        output.artifacts
    );
    assert!(
        output
            .files
            .contains(&bundle_artifact_root.join("app__main.mgi")),
        "{:#?}",
        output.files
    );
}

#[test]
fn cli_emit_app_bundle_writes_dependency_aware_layout_and_launcher() {
    let workspace = temp_package_root("cli-emit-app-bundle-dependency");
    let base = workspace.join("base");
    let shared = workspace.join("shared");
    let app = workspace.join("app");
    write_package_file(
        &base,
        "muga.toml",
        r#"
[package]
name = "base"
source = "src"
resources = "resources"
"#,
    );
    write_package_file(&base, "resources/messages/base.txt", "base");
    write_package_file(
        &base,
        "src/core/main.muga",
        r#"
import std::fs
import std::io

pub fn value(): Result[String, io::IOError] {
  fs::read_resource_text("base", "messages/base.txt")
}
"#,
    );
    write_package_file(
        &shared,
        "muga.toml",
        r#"
[package]
name = "shared"
source = "src"

[dependencies]
base = { path = "../base" }
"#,
    );
    write_package_file(
        &shared,
        "src/logging/main.muga",
        r#"
import base::core as core
import std::io

pub fn value(): Result[String, io::IOError] {
  text = try core::value()
  Result::Ok(text.concat("|shared"))
}
"#,
    );
    write_package_file(
        &app,
        "muga.toml",
        r#"
[package]
name = "app"
source = "src"

[dependencies]
shared = { path = "../shared" }
"#,
    );
    let entry = write_package_file(
        &app,
        "src/main/main.muga",
        r#"
import std::cli
import std::env
import std::io
import shared::logging as logging

fn main(): Result[String, io::IOError] {
  text = try logging::value()
  arg = cli::positional_or(env::args(), 0, "none")
  Result::Ok(text.concat("|").concat(arg))
}
"#,
    );
    let bundle = workspace.join("dist/app");

    let output = muga_command()
        .arg("emit-app-bundle")
        .arg("--output-dir")
        .arg(&bundle)
        .arg("--program")
        .arg("dep-tool")
        .arg(&entry)
        .output()
        .expect("muga command should run");
    let stdout = String::from_utf8_lossy(&output.stdout);
    let stderr = String::from_utf8_lossy(&output.stderr);

    assert!(output.status.success(), "{output:#?}");
    assert_eq!(stderr, "");
    assert!(bundle.join("muga.toml").is_file());
    assert!(bundle.join("muga.lock").is_file());
    assert!(bundle.join(".muga/bundle-deps/base/muga.toml").is_file());
    assert!(
        bundle
            .join(".muga/bundle-deps/base/src/core/main.muga")
            .is_file()
    );
    assert!(
        bundle
            .join(".muga/bundle-deps/base/resources/messages/base.txt")
            .is_file()
    );
    assert!(bundle.join(".muga/bundle-deps/shared/muga.toml").is_file());
    assert!(
        bundle
            .join(".muga/bundle-deps/shared/src/logging/main.muga")
            .is_file()
    );
    assert!(bundle.join(".muga/build/base__core.mgi").is_file());
    assert!(bundle.join(".muga/build/shared__logging.mgb").is_file());
    assert!(bundle.join(".muga/build/app__main.mgc").is_file());
    assert!(bundle.join(".muga/app-bundle").is_file());
    assert!(stdout.contains("bin/dep-tool") || stdout.contains("bin\\dep-tool"));

    let manifest = fs::read_to_string(bundle.join("muga.toml")).expect("manifest should exist");
    assert!(
        manifest.contains("\"shared\" = { path = \".muga/bundle-deps/shared\" }"),
        "{manifest}"
    );
    let shared_manifest = fs::read_to_string(bundle.join(".muga/bundle-deps/shared/muga.toml"))
        .expect("shared manifest should exist");
    assert!(
        shared_manifest.contains("\"base\" = { path = \"../base\" }"),
        "{shared_manifest}"
    );
    let lockfile = fs::read_to_string(bundle.join("muga.lock")).expect("lockfile should exist");
    assert!(
        lockfile.contains("source = { path = \".muga/bundle-deps/base\" }"),
        "{lockfile}"
    );
    assert!(
        lockfile.contains("source = { path = \".muga/bundle-deps/shared\" }"),
        "{lockfile}"
    );

    let run = Command::new("sh")
        .arg(bundle.join("bin/dep-tool"))
        .arg("Ada")
        .env("MUGA_BIN", env!("CARGO_BIN_EXE_muga"))
        .output()
        .expect("dependency-aware app bundle launcher should run");
    let run_stdout = String::from_utf8_lossy(&run.stdout);
    let run_stderr = String::from_utf8_lossy(&run.stderr);

    assert!(run.status.success(), "{run:#?}");
    assert!(
        run_stdout.contains("Result::Ok(base|shared|Ada)"),
        "{run_stdout}"
    );
    assert_eq!(run_stderr, "");
}

