#[test]
fn compile_bytecode_nested_using_cleanup_error_branch_unwinds_outer_cleanup() {
    let root = temp_package_root("std-fs-nested-using-cleanup-bytecode");
    let outer = root.join("outer.txt");
    let inner = root.join("inner.txt");
    let outer_literal = muga_string_literal(&display_path(&outer));
    let inner_literal = muga_string_literal(&display_path(&inner));
    let entry = write_package_file(
        &root,
        "app/std_fs_nested_using_cleanup_bytecode/main.muga",
        &format!(
            r#"
package app::std_fs_nested_using_cleanup_bytecode

import std::fs
import std::io
import std::path

fn main(): Result[Unit, io::IOError] {{
  outer_path = path::from_string({outer_literal})
  inner_path = path::from_string({inner_literal})
  using outer_file = try fs::create_text(outer_path) {{
    outer_wrote = fs::write_text_to(outer_file, "outer")
    using inner_file = try fs::create_text(inner_path) {{
      inner_wrote = fs::write_text_to(inner_file, "inner")
    }}
  }}
  Result::Ok(())
}}
"#
        ),
    );

    let program = muga::compile_bytecode_path(&entry).expect("nested using should compile");
    let main_ref = program.main.expect("main function ref should exist");
    let main_function = program
        .entry
        .instructions
        .iter()
        .find_map(|instruction| match instruction {
            Instruction::DefineFunction {
                target, function, ..
            } if *target == main_ref => Some(&program.functions[*function]),
            _ => None,
        })
        .expect("main function should be defined");
    let close_call_count = main_function
        .chunk
        .instructions
        .windows(3)
        .filter(|window| {
            matches!(
                (&window[0], &window[2]),
                (
                    Instruction::LoadName { target, .. },
                    Instruction::Call { argc: 1, .. }
                ) if program.symbols.resolve(target.name).contains("close")
            )
        })
        .count();
    assert!(
        close_call_count >= 4,
        "nested using should close the outer handle on inner acquisition failure, inner cleanup failure, and normal outer fallthrough; saw {close_call_count} close call sites in {:#?}",
        main_function.chunk.instructions
    );
    assert!(
        program.locals.iter().any(|local| program
            .symbols
            .resolve(local.name)
            .starts_with("__muga_using_cleanup_failed_")),
        "cleanup unwind should track the first cleanup failure before preserving the original control transfer"
    );
}

