#[test]
fn standard_fs_file_handle_interface_exposes_handle_facts_and_close_mode() {
    let root = temp_package_root("std-fs-file-handle-interface");
    let target = root.join("interface.txt");
    fs::write(&target, "interface").expect("interface target should be written");
    let target_literal = muga_string_literal(&display_path(&target));
    let entry = write_package_file(
        &root,
        "app/std_fs_file_handle_interface/main.muga",
        &format!(
            r#"
package app::std_fs_file_handle_interface

import std::fs
import std::io
import std::path

fn main(): Result[String, io::IOError] {{
  file_path = path::from_string({target_literal})
  file = try fs::open_text(file_path)
  text = try fs::read_text_from(file)
  done = try fs::close(file)
  Result::Ok(text)
}}
"#
        ),
    );

    let result =
        muga::check_package_aware_path(&entry).expect("package-aware checking should pass");
    let interfaces = result.typed_program.package_interfaces();
    let fs_interface = interfaces
        .package_by_path("std::fs")
        .expect("std::fs interface should exist");
    let file = interfaces
        .opaque_type_by_name(fs_interface.package, "File")
        .expect("File opaque type should be exported");
    assert!(file.handle_facts.runtime_backed);
    assert!(file.handle_facts.closeable);

    let close = interfaces
        .function_by_name(fs_interface.package, "close")
        .expect("close function should be exported");
    let write_text_to = interfaces
        .function_by_name(fs_interface.package, "write_text_to")
        .expect("write_text_to function should be exported");
    let flush = interfaces
        .function_by_name(fs_interface.package, "flush")
        .expect("flush function should be exported");
    assert_eq!(file.handle_facts.close_function, Some(close.item));
    assert_eq!(
        close.params[0].mode,
        muga::interface::PackageInterfaceParamMode::Consume
    );
    assert_eq!(
        write_text_to.params[0].mode,
        muga::interface::PackageInterfaceParamMode::Borrow
    );
    assert_eq!(
        flush.params[0].mode,
        muga::interface::PackageInterfaceParamMode::Borrow
    );

    let text = interfaces
        .persisted_artifact_text("std::fs", &result.typed_program.symbols)
        .expect("std::fs interface should persist");
    assert!(text.contains("opaque-type"), "{text}");
    assert!(text.contains("runtimeBacked=true"), "{text}");
    assert!(text.contains("closeable=true"), "{text}");
    assert!(text.contains("closeFunction="), "{text}");
    assert!(!text.contains("closeFunction=-"), "{text}");
    assert!(
        text.contains("function\t") && text.contains("\tcreate_text\t"),
        "{text}"
    );
    assert!(
        text.contains("function\t") && text.contains("\tappend_text\t"),
        "{text}"
    );
    assert!(
        text.contains("function\t") && text.contains("\twrite_text_to\t"),
        "{text}"
    );
    assert!(
        text.contains("function\t") && text.contains("\tflush\t"),
        "{text}"
    );
    assert!(text.contains("\tconsume\tPackageOpaque File"), "{text}");
    assert!(text.contains("\tborrow\tPackageOpaque File"), "{text}");
}

