#[test]
fn standard_fs_metadata_artifact_run_uses_emitted_std_implementations() {
    let root = temp_package_root("std-fs-metadata-artifacts");
    let data_dir = root.join("data");
    fs::create_dir_all(&data_dir).expect("data directory should be created");
    let target = data_dir.join("artifact-metadata.txt");
    fs::write(&target, "metadata").expect("metadata target should be written");
    let missing = data_dir.join("missing.txt");
    let target_literal = muga_string_literal(&display_path(&target));
    let data_dir_literal = muga_string_literal(&display_path(&data_dir));
    let missing_literal = muga_string_literal(&display_path(&missing));
    let entry = write_package_file(
        &root,
        "app/std_fs_metadata_artifacts/main.muga",
        &format!(
            r#"
package app::std_fs_metadata_artifacts

import std::fs
import std::path

fn kind_name(kind: fs::PathKind): String {{
  match kind {{
    fs::PathKind::Missing => "missing"
    fs::PathKind::File => "file"
    fs::PathKind::Directory => "directory"
    fs::PathKind::Other => "other"
  }}
}}

fn main(): String {{
  file_path = path::from_string({target_literal})
  dir_path = path::from_string({data_dir_literal})
  missing_path = path::from_string({missing_literal})
  file_info = fs::path_info(file_path)
  dir_info = fs::path_info(dir_path)
  missing_info = fs::path_info(missing_path)
  first = kind_name(file_info.kind).concat("/").concat(file_info.status.is_file.to_string())
  second = first.concat("/").concat(kind_name(dir_info.kind)).concat("/").concat(dir_info.status.is_dir.to_string())
  second.concat("/").concat(kind_name(missing_info.kind)).concat("/").concat(missing_info.status.exists.to_string())
}}
"#
        ),
    );
    let artifact_root = root.join("artifacts");
    let written =
        muga::write_package_artifacts(&entry, &artifact_root).expect("artifacts should emit");

    assert!(
        written
            .iter()
            .any(|path| path.file_name().is_some_and(|name| name == "std__fs.mgb")),
        "{written:#?}"
    );
    assert!(
        written
            .iter()
            .any(|path| path.file_name().is_some_and(|name| name == "std__path.mgb")),
        "{written:#?}"
    );

    let result = muga::run_path_against_artifact_root(&entry, &artifact_root)
        .expect("artifact-backed std::fs metadata program should run");
    let value = result.main_result.expect("main result should exist");
    assert_eq!(value.to_string(), "file/true/directory/true/missing/false");
}

