fn display_path(path: &Path) -> String {
    path.to_string_lossy().into_owned()
}

fn unix_millis_now() -> i64 {
    let duration = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .expect("system time should be after Unix epoch");
    i64::try_from(duration.as_millis()).expect("current Unix milliseconds should fit in Int")
}

fn muga_string_literal(value: &str) -> String {
    format!(
        "\"{}\"",
        value
            .replace('\\', "\\\\")
            .replace('"', "\\\"")
            .replace('\n', "\\n")
            .replace('\t', "\\t")
    )
}

fn assert_sample_runs(path: &str, expected_main: &str, expected_output: &str) {
    let source = fs::read_to_string(path).unwrap();
    let result = muga::run_source(&source).unwrap();
    let value = result.main_result.expect("main result should exist");
    assert_eq!(value.to_string(), expected_main, "sample: {path}");
    assert_eq!(result.output_text, expected_output, "sample: {path}");
}

fn assert_package_runs(path: &str, expected_main: &str, expected_output: &str) {
    let result = muga::run_path(Path::new(path)).unwrap();
    let value = result.main_result.expect("main result should exist");
    assert_eq!(value.to_string(), expected_main, "package sample: {path}");
    assert_eq!(
        result.output_text, expected_output,
        "package sample: {path}"
    );
}

fn assert_sample_without_main_runs(path: &str, expected_output: &str) {
    let source = fs::read_to_string(path).unwrap();
    let result = muga::run_source(&source).unwrap();
    assert!(result.main_result.is_none(), "sample: {path}");
    assert_eq!(result.output_text, expected_output, "sample: {path}");
}

fn parse_source(source: &str) -> muga::ast::Program {
    let tokens = muga::lexer::lex(source).unwrap();
    muga::parser::parse(tokens).unwrap()
}

fn persisted_interfaces_from_program(
    program: &muga::typed_hir::Program,
) -> (
    muga::interface::PackageInterfaceGraph,
    muga::symbol::SymbolTable,
) {
    let text = program
        .package_interfaces()
        .to_persisted_text(&program.symbols);
    let mut symbols = program.symbols.clone();
    let interfaces =
        muga::interface::PackageInterfaceGraph::from_persisted_text(&text, &mut symbols)
            .expect("persisted interfaces should parse");
    (interfaces, symbols)
}

fn assert_representative_public_signature_shapes(
    interfaces: &muga::interface::PackageInterfaceGraph,
    symbols: &muga::symbol::SymbolTable,
) {
    let model = interfaces
        .package_by_path("model::types")
        .expect("model::types interface should exist");
    let api = interfaces
        .package_by_path("api::shapes")
        .expect("api::shapes interface should exist");
    let std_io = interfaces
        .package_by_path("std::io")
        .expect("std::io interface should exist");
    let std_path = interfaces
        .package_by_path("std::path")
        .expect("std::path interface should exist");

    let score = interface_record(model, "Score");
    let box_record = interface_record(model, "Box");
    let stage = interface_enum(model, "Stage");
    let io_error = interface_record(std_io, "IOError");
    let path = interface_record(std_path, "Path");
    let event = interface_enum(api, "ApiEvent");
    let envelope = interface_record(api, "Envelope");

    assert_eq!(score.fields.len(), 3, "{score:#?}");
    assert_eq!(
        interface_field(score, "label").ty,
        muga::types::TypeInfo::String
    );
    assert_eq!(
        interface_field(score, "points").ty,
        muga::types::TypeInfo::Int
    );
    assert_eq!(
        interface_field(score, "active").ty,
        muga::types::TypeInfo::Bool
    );

    assert_eq!(box_record.type_params, vec!["T".to_string()]);
    assert_generic_param_type(&interface_field(box_record, "value").ty, "T", symbols);

    assert_eq!(stage.type_params, vec!["T".to_string()]);
    assert_generic_param_type(
        interface_variant(stage, "Ready")
            .payload
            .as_ref()
            .expect("Ready should carry T"),
        "T",
        symbols,
    );
    assert_eq!(
        interface_variant(stage, "Failed")
            .payload
            .as_ref()
            .expect("Failed should carry String"),
        &muga::types::TypeInfo::String
    );
    assert!(interface_variant(stage, "Empty").payload.is_none());

    let identity = interface_function(model, "identity");
    assert_eq!(identity.type_params, vec!["T".to_string()]);
    assert_eq!(identity.params.len(), 1, "{identity:#?}");
    assert_generic_param_type(&identity.params[0].ty, "T", symbols);
    assert_generic_param_type(&identity.ret, "T", symbols);
    assert_eq!(
        interface_function(model, "keep_unit").ret,
        muga::types::TypeInfo::Unit
    );
    let transform = interface_function(model, "transform");
    assert_package_record_type(&transform.params[0].ty, score.item);
    let (mapper_params, mapper_ret) = assert_function_type(&transform.params[1].ty);
    assert_eq!(mapper_params.len(), 1, "{transform:#?}");
    assert_package_record_type(&mapper_params[0], score.item);
    assert_package_record_type(mapper_ret, score.item);
    assert_package_record_type(&transform.ret, score.item);

    assert_eq!(event.type_params, vec!["T".to_string()]);
    assert_generic_param_type(
        interface_variant(event, "Wrapped")
            .payload
            .as_ref()
            .expect("Wrapped should carry T"),
        "T",
        symbols,
    );
    assert_package_record_type(
        interface_variant(event, "Score")
            .payload
            .as_ref()
            .expect("Score should carry model::types::Score"),
        score.item,
    );
    assert_package_record_type(
        interface_variant(event, "Located")
            .payload
            .as_ref()
            .expect("Located should carry std::path::Path"),
        path.item,
    );
    assert_package_record_type(
        interface_variant(event, "Failed")
            .payload
            .as_ref()
            .expect("Failed should carry std::io::IOError"),
        io_error.item,
    );
    assert!(interface_variant(event, "Nothing").payload.is_none());

    assert_eq!(envelope.type_params, vec!["T".to_string()]);
    assert_generic_param_type(&interface_field(envelope, "value").ty, "T", symbols);
    assert_generic_param_type(
        assert_list_type(&interface_field(envelope, "items").ty),
        "T",
        symbols,
    );
    let (index_key, index_value) = assert_map_type(&interface_field(envelope, "index").ty);
    assert_eq!(index_key, &muga::types::TypeInfo::String);
    assert_generic_param_type(index_value, "T", symbols);
    assert_generic_param_type(
        assert_option_type(&interface_field(envelope, "maybe").ty),
        "T",
        symbols,
    );
    let (outcome_ok, outcome_err) = assert_result_type(&interface_field(envelope, "outcome").ty);
    assert_generic_param_type(outcome_ok, "T", symbols);
    assert_package_record_type(outcome_err, io_error.item);

    let select_handler = interface_function(api, "select_handler");
    let (select_param_params, select_param_ret) =
        assert_function_type(&select_handler.params[0].ty);
    assert_eq!(select_param_params.len(), 1, "{select_handler:#?}");
    assert_package_record_type(&select_param_params[0], score.item);
    assert_package_record_type(select_param_ret, score.item);
    let (select_ret_params, select_ret_ret) = assert_function_type(&select_handler.ret);
    assert_eq!(select_ret_params.len(), 1, "{select_handler:#?}");
    assert_package_record_type(&select_ret_params[0], score.item);
    assert_package_record_type(select_ret_ret, score.item);

    let audit = interface_function(api, "audit");
    assert_eq!(audit.params.len(), 7, "{audit:#?}");
    let envelope_args = assert_package_record_type(&audit.params[0].ty, envelope.item);
    assert_eq!(envelope_args.len(), 1, "{audit:#?}");
    assert_package_record_type(&envelope_args[0], score.item);
    let (handler_params, handler_ret) = assert_function_type(&audit.params[1].ty);
    assert_eq!(handler_params.len(), 2, "{audit:#?}");
    assert_package_record_type(&handler_params[0], score.item);
    assert_package_record_type(&handler_params[1], path.item);
    let (handler_ok, handler_err) = assert_result_type(handler_ret);
    assert_eq!(handler_ok, &muga::types::TypeInfo::String);
    assert_package_record_type(handler_err, io_error.item);
    assert_package_record_type(assert_option_type(&audit.params[2].ty), score.item);
    assert_package_record_type(assert_list_type(&audit.params[3].ty), score.item);
    let (table_key, table_value) = assert_map_type(&audit.params[4].ty);
    assert_eq!(table_key, &muga::types::TypeInfo::String);
    assert_package_record_type(table_value, score.item);
    let stage_args = assert_package_enum_type(&audit.params[5].ty, stage.item);
    assert_eq!(stage_args.len(), 1, "{audit:#?}");
    assert_package_record_type(&stage_args[0], score.item);
    assert_package_record_type(&audit.params[6].ty, path.item);

    let (audit_ok, audit_err) = assert_result_type(&audit.ret);
    let event_args = assert_package_enum_type(audit_ok, event.item);
    assert_eq!(event_args.len(), 1, "{audit:#?}");
    assert_package_record_type(&event_args[0], score.item);
    assert_package_record_type(audit_err, io_error.item);
}

fn interface_record<'a>(
    package: &'a muga::interface::PackageInterface,
    name: &str,
) -> &'a muga::interface::PackageInterfaceRecord {
    package
        .records
        .iter()
        .find(|record| record.name == name)
        .unwrap_or_else(|| panic!("interface package {} missing record `{name}`", package.path))
}

fn interface_enum<'a>(
    package: &'a muga::interface::PackageInterface,
    name: &str,
) -> &'a muga::interface::PackageInterfaceEnum {
    package
        .enums
        .iter()
        .find(|enumeration| enumeration.name == name)
        .unwrap_or_else(|| panic!("interface package {} missing enum `{name}`", package.path))
}

fn interface_function<'a>(
    package: &'a muga::interface::PackageInterface,
    name: &str,
) -> &'a muga::interface::PackageInterfaceFunction {
    package
        .functions
        .iter()
        .find(|function| function.name == name)
        .unwrap_or_else(|| {
            panic!(
                "interface package {} missing function `{name}`",
                package.path
            )
        })
}

fn interface_field<'a>(
    record: &'a muga::interface::PackageInterfaceRecord,
    name: &str,
) -> &'a muga::interface::PackageInterfaceField {
    record
        .fields
        .iter()
        .find(|field| field.name == name)
        .unwrap_or_else(|| panic!("interface record {} missing field `{name}`", record.name))
}

fn interface_variant<'a>(
    enumeration: &'a muga::interface::PackageInterfaceEnum,
    name: &str,
) -> &'a muga::interface::PackageInterfaceEnumVariant {
    enumeration
        .variants
        .iter()
        .find(|variant| variant.name == name)
        .unwrap_or_else(|| {
            panic!(
                "interface enum {} missing variant `{name}`",
                enumeration.name
            )
        })
}

fn assert_generic_param_type(
    ty: &muga::types::TypeInfo,
    name: &str,
    symbols: &muga::symbol::SymbolTable,
) {
    assert!(
        matches!(ty, muga::types::TypeInfo::GenericParam(symbol) if symbols.resolve(*symbol) == name),
        "expected generic param `{name}`, found {ty:#?}"
    );
}

fn assert_package_record_type(
    ty: &muga::types::TypeInfo,
    item: muga::identity::PackageItemId,
) -> &[muga::types::TypeInfo] {
    match ty {
        muga::types::TypeInfo::PackageRecord {
            item: actual, args, ..
        } if *actual == item => args,
        _ => panic!("expected package record item {item:?}, found {ty:#?}"),
    }
}

fn assert_package_enum_type(
    ty: &muga::types::TypeInfo,
    item: muga::identity::PackageItemId,
) -> &[muga::types::TypeInfo] {
    match ty {
        muga::types::TypeInfo::PackageEnum {
            item: actual, args, ..
        } if *actual == item => args,
        _ => panic!("expected package enum item {item:?}, found {ty:#?}"),
    }
}

fn assert_list_type(ty: &muga::types::TypeInfo) -> &muga::types::TypeInfo {
    match ty {
        muga::types::TypeInfo::List(item) => item,
        _ => panic!("expected List[T], found {ty:#?}"),
    }
}

fn assert_map_type(ty: &muga::types::TypeInfo) -> (&muga::types::TypeInfo, &muga::types::TypeInfo) {
    match ty {
        muga::types::TypeInfo::Map(key, value) => (key, value),
        _ => panic!("expected Map[K, V], found {ty:#?}"),
    }
}

fn assert_option_type(ty: &muga::types::TypeInfo) -> &muga::types::TypeInfo {
    match ty {
        muga::types::TypeInfo::Option(item) => item,
        _ => panic!("expected Option[T], found {ty:#?}"),
    }
}

fn assert_result_type(
    ty: &muga::types::TypeInfo,
) -> (&muga::types::TypeInfo, &muga::types::TypeInfo) {
    match ty {
        muga::types::TypeInfo::Result(ok, err) => (ok, err),
        _ => panic!("expected Result[T, E], found {ty:#?}"),
    }
}

fn assert_function_type(
    ty: &muga::types::TypeInfo,
) -> (&[muga::types::TypeInfo], &muga::types::TypeInfo) {
    match ty {
        muga::types::TypeInfo::Function(function) => (&function.params, &function.ret),
        _ => panic!("expected function type, found {ty:#?}"),
    }
}

struct LocalArchiveDependencyFixture {
    app_root: std::path::PathBuf,
    archive: muga::PackageArchiveOutput,
    archive_file: String,
}

fn write_local_archive_dependency_fixture(
    name: &str,
    archive_package_name: &str,
) -> LocalArchiveDependencyFixture {
    let workspace = temp_package_root(name);
    let app_root = workspace.join("app");
    let shared_root = workspace.join("shared");
    let archive_root = workspace.join("archives");
    write_package_file(
        &shared_root,
        "muga.toml",
        &format!(
            r#"
[package]
name = "{archive_package_name}"
source = "src"
"#
        ),
    );
    let shared_entry = write_package_file(
        &shared_root,
        "src/logging/main.muga",
        r#"
pub fn value(): Int {
  11
}
"#,
    );
    let archive = muga::write_package_archive(&shared_entry, &archive_root)
        .expect("archive should be written");
    let archive_file = archive
        .path
        .file_name()
        .and_then(|name| name.to_str())
        .expect("archive should have a UTF-8 file name")
        .to_string();
    LocalArchiveDependencyFixture {
        app_root,
        archive,
        archive_file,
    }
}

fn write_local_archive_dependency_app(
    app_root: &Path,
    dependency_source: &str,
) -> std::path::PathBuf {
    write_package_file(
        app_root,
        "muga.toml",
        &format!(
            r#"
[package]
name = "app"
source = "src"

[dependencies]
shared = {dependency_source}
"#
        ),
    );
    write_package_file(
        app_root,
        "src/main/main.muga",
        r#"
import shared::logging as logging

fn main(): Int {
  logging::value() + 1
}
"#,
    )
}

fn temp_package_root(name: &str) -> std::path::PathBuf {
    let root = std::env::temp_dir().join(format!("muga-{name}-{}", std::process::id()));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root).expect("temp package root should be created");
    root
}

fn write_package_file(root: &Path, relative: &str, source: &str) -> std::path::PathBuf {
    let path = root.join(relative);
    fs::create_dir_all(path.parent().expect("package file should have parent"))
        .expect("package directory should be created");
    fs::write(&path, source.trim_start()).expect("package file should be written");
    path
}

fn write_package_bytes_file(root: &Path, relative: &str, contents: &[u8]) -> std::path::PathBuf {
    let path = root.join(relative);
    fs::create_dir_all(path.parent().expect("package file should have parent"))
        .expect("package directory should be created");
    fs::write(&path, contents).expect("package file should be written");
    path
}

fn package_archive_fixture(entries: &[(&str, &str, &str)]) -> Vec<u8> {
    let mut bytes = Vec::new();
    for (kind, path, contents) in entries {
        bytes.extend_from_slice(format!("{kind}\t{path}\t{}\n", contents.len()).as_bytes());
        bytes.extend_from_slice(contents.as_bytes());
        bytes.push(b'\n');
    }
    bytes
}

fn app_archive_fixture_bytes(body: &[u8]) -> Vec<u8> {
    let mut bytes = b"muga-app-bundle-archive-v1\n".to_vec();
    bytes.extend_from_slice(body);
    bytes
}

fn write_app_archive_fixture(root: &Path, index: usize, bytes: &[u8]) -> std::path::PathBuf {
    let hash = muga::package::content_hash_for_bytes(bytes);
    let hash = hash
        .strip_prefix("sha256:")
        .expect("app archive fixture hash should use sha256 prefix");
    let archive_root = root.join("archives");
    fs::create_dir_all(&archive_root).expect("app archive fixture root should be created");
    let path = archive_root.join(format!("fixture-{index}-sha256-{hash}.mga"));
    fs::write(&path, bytes).expect("app archive fixture should be written");
    path
}

fn lockfile_source_hash(lockfile: &str) -> String {
    let line = lockfile
        .lines()
        .find(|line| line.starts_with("source_hash = "))
        .unwrap_or_else(|| panic!("lockfile missing source_hash: {lockfile}"));
    line.trim_start_matches("source_hash = \"")
        .trim_end_matches('"')
        .to_string()
}

fn lockfile_archive_hash(lockfile: &str) -> String {
    let line = lockfile
        .lines()
        .find(|line| line.starts_with("hash = "))
        .unwrap_or_else(|| panic!("lockfile missing archive hash: {lockfile}"));
    line.trim_start_matches("hash = \"")
        .trim_end_matches('"')
        .to_string()
}

fn build_output_has_status_for_file(stdout: &str, status: &str, file_name: &str) -> bool {
    let prefix = format!("{status}\t");
    stdout
        .lines()
        .any(|line| line.starts_with(&prefix) && line.contains(file_name))
}

fn archive_dependency_cache_root_for_test(
    root: &Path,
    dependency: &str,
    hash: &str,
) -> std::path::PathBuf {
    let hash = hash.strip_prefix("sha256:").unwrap_or(hash);
    root.join(".muga").join("packages").join(format!(
        "{}-sha256-{}",
        dependency.replace("::", "__"),
        hash
    ))
}

fn write_interface_artifacts(
    root: &Path,
    interfaces: &muga::interface::PackageInterfaceGraph,
    symbols: &muga::symbol::SymbolTable,
    package_paths: &[&str],
) {
    fs::create_dir_all(root).expect("interface artifact root should be created");
    for package_path in package_paths {
        interfaces
            .write_persisted_artifact(root, package_path, symbols)
            .expect("interface artifact should be written");
    }
}

fn copy_interface_artifact(from_root: &Path, to_root: &Path, package_path: &str) {
    let from = muga::interface::PackageInterfaceGraph::persisted_file_path(from_root, package_path);
    let to = muga::interface::PackageInterfaceGraph::persisted_file_path(to_root, package_path);
    fs::copy(&from, &to).unwrap_or_else(|error| {
        panic!(
            "interface artifact should copy from {} to {}: {error}",
            from.display(),
            to.display()
        )
    });
}

fn copy_implementation_artifact(from_root: &Path, to_root: &Path, package_path: &str) {
    let from = muga::implementation_artifact::persisted_file_path(from_root, package_path);
    let to = muga::implementation_artifact::persisted_file_path(to_root, package_path);
    fs::copy(&from, &to).unwrap_or_else(|error| {
        panic!(
            "implementation artifact should copy from {} to {}: {error}",
            from.display(),
            to.display()
        )
    });
}

fn bytecode_program_has_control_flow(program: &bytecode::Program) -> bool {
    fn chunk_has_control_flow(chunk: &Chunk) -> bool {
        chunk.instructions.iter().any(|instruction| {
            matches!(
                instruction,
                Instruction::JumpIfFalse { .. }
                    | Instruction::JumpIfNotEnumVariant { .. }
                    | Instruction::Jump { .. }
            )
        })
    }

    chunk_has_control_flow(&program.entry)
        || program
            .functions
            .iter()
            .any(|function| chunk_has_control_flow(&function.chunk))
}

fn bytecode_function_named<'a>(
    program: &'a bytecode::Program,
    name: &str,
) -> &'a bytecode::Function {
    program
        .functions
        .iter()
        .find(|function| {
            function
                .name
                .is_some_and(|symbol| program.symbols.resolve(symbol).ends_with(name))
        })
        .unwrap_or_else(|| {
            let names = program
                .functions
                .iter()
                .filter_map(|function| function.name.map(|symbol| program.symbols.resolve(symbol)))
                .collect::<Vec<_>>();
            panic!("bytecode function `{name}` should exist; found {names:?}")
        })
}

fn bytecode_close_call_site_count(
    program: &bytecode::Program,
    function: &bytecode::Function,
) -> usize {
    function
        .chunk
        .instructions
        .windows(3)
        .filter(|window| {
            matches!(
                (&window[0], &window[2]),
                (
                    Instruction::LoadName { target, .. },
                    Instruction::Call { argc: 1, .. }
                ) if program.symbols.resolve(target.name).contains("close")
            )
        })
        .count()
}

fn write_tampered_states_implementation_artifact(
    name: &str,
    tamper: impl FnOnce(&mut muga::implementation_artifact::PackageImplementationArtifact),
) -> (std::path::PathBuf, std::path::PathBuf) {
    let artifact_root = temp_package_root(name);
    let emitted = muga_command()
        .arg("emit-artifacts")
        .arg("--artifact-root")
        .arg(&artifact_root)
        .arg("samples/packages/app/enum_demo/main.muga")
        .output()
        .expect("muga command should run");
    assert!(emitted.status.success(), "{emitted:#?}");

    let artifact_path =
        muga::implementation_artifact::persisted_file_path(&artifact_root, "util::states");
    let mut artifact = muga::implementation_artifact::read_persisted_file(&artifact_path)
        .expect("implementation artifact should parse before tampering");
    tamper(&mut artifact);
    artifact
        .write_persisted_artifact(&artifact_root)
        .expect("tampered implementation artifact should be rewritten");

    (artifact_root, artifact_path)
}

fn diagnostics_text(diagnostics: &[muga::diagnostic::Diagnostic]) -> String {
    diagnostics
        .iter()
        .map(ToString::to_string)
        .collect::<Vec<_>>()
        .join("\n")
}

