fn write_control_flow_implementation_provider(root: &Path) {
    write_package_file(
        root,
        "model/workflow/main.muga",
        r#"
package model::workflow

pub record Packet {
  label: String,
  count: Int
}

pub enum Status {
  Done(Packet)
  Skipped(String)
}
"#,
    );
    write_package_file(
        root,
        "api/control/aaa_private.muga",
        r#"
package api::control

import model::workflow

fn bump(value: Int): Int {
  value + 1
}

pkg fn adjust(seed: Int): Int {
  mut current = seed
  while current < 6 {
    current = bump(current)
    if current == 3 {
      continue
    }
    if current == 5 {
      break
    }
  }
  current
}

pkg fn choose(seed: Int): workflow::Status {
  total = adjust(seed)
  if total > 4 {
    workflow::Status::Done(workflow::Packet { label: "done", count: total })
  } else {
    workflow::Status::Skipped("small")
  }
}

pkg fn parse_limit(raw: String): Result[Int, String] {
  raw.trim().parse_int()
}
"#,
    );
    write_package_file(
        root,
        "api/control/main.muga",
        r#"
package api::control

import model::workflow

pub fn score(limit: Int): Int {
  mut total = 0
  for item in [1, 2, 3, 4] {
    if item == 2 {
      continue
    }
    total = total + adjust(item)
    if total > limit {
      break
    }
  }
  total
}

pub fn classify(seed: Int): workflow::Status {
  match choose(seed) {
    workflow::Status::Done(packet) => workflow::Status::Done(packet)
    workflow::Status::Skipped(reason) => workflow::Status::Skipped(reason)
  }
}

pub fn final_count(seed: Int): Int {
  match classify(seed) {
    workflow::Status::Done(packet) => packet.count
    workflow::Status::Skipped(reason) => reason.char_count()
  }
}

pub fn final_count_result(raw: String): Result[Int, String] {
  limit = try parse_limit(raw)
  Result::Ok(score(limit) + final_count(1))
}
"#,
    );
    write_package_file(
        root,
        "app/provider/main.muga",
        r#"
package app::provider

import api::control

fn main(): Int {
  match control::final_count_result("8") {
    Result::Ok(value) => value
    Result::Err(message) => message.char_count()
  }
}
"#,
    );
}

